/* Helper utilitario de alto rendimiento para debouncing de eventos interactivos */
function crearDebounce(fn, delayMs = 120) {
    let timerId = null;
    return function(...args) {
        if (timerId) clearTimeout(timerId);
        timerId = setTimeout(() => {
            fn.apply(this, args);
            timerId = null;
        }, delayMs);
    };
}

/* Utilidades Centrales de Ciberseguridad (Anti-XSS, Sanitización de URLs y Anti-Prototype Pollution) */
function escapeHtml(str) {
    if (str === null || str === undefined) return "";
    return String(str)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}

function sanitizarUrlSegura(url) {
    if (!url || typeof url !== "string") return "";
    const trimmed = url.trim();
    if (/^data:image\/(png|jpeg|jpg|webp|gif);base64,[a-zA-Z0-9+/=\s]+$/i.test(trimmed)) {
        return trimmed;
    }
    if (/^data:audio\/(webm|mp3|mpeg|ogg|wav|mp4|x-m4a);base64,[a-zA-Z0-9+/=\s]+$/i.test(trimmed)) {
        return trimmed;
    }
    if (/^blob:/i.test(trimmed)) {
        return trimmed;
    }
    if (/^https:\/\//i.test(trimmed) && !/["'<>]/.test(trimmed)) {
        return trimmed;
    }
    if (/^[a-zA-Z0-9_.-]+\.(png|jpg|jpeg|webp|svg|mp4)$/i.test(trimmed)) {
        return trimmed;
    }
    return "";
}


/* ==========================================================
   ARQUITECTURA Y REGISTRO CENTRAL DE MÓDULOS (LUIBAÑEZ CORE)
   ========================================================== */
const LuibanezCore = (function() {
    const _modulos = new Map();
    const _eventos = new Map();

    return {
        registrarModulo(nombre, instancia) {
            if (_modulos.has(nombre)) {
                console.warn(`[LuibanezCore] Módulo "${nombre}" ya registrado. Sobrescribiendo.`);
            }
            _modulos.set(nombre, instancia);
        },
        obtenerModulo(nombre) {
            return _modulos.get(nombre) || null;
        },
        listarModulos() {
            return Array.from(_modulos.keys());
        },
        on(evento, callback) {
            if (!_eventos.has(evento)) _eventos.set(evento, []);
            _eventos.get(evento).push(callback);
        },
        emit(evento, datos) {
            const listeners = _eventos.get(evento) || [];
            listeners.forEach(cb => {
                try { cb(datos); } catch (e) { console.error(`[LuibanezCore Event Error: ${evento}]`, e); }
            });
        }
    };
})();

if (typeof window !== "undefined") {
    window.LuibanezCore = LuibanezCore;
}

