function actualizarUIAuthHeader() {
    const tieneSesion = !perfilUsuario.esInvitado && Boolean(currentUser()) && perfilUsuario.apodo && perfilUsuario.apodo !== "Invitado";

    // Header Desktop
    const guestContainer = document.getElementById("topNavAuthGuest");
    const userContainer = document.getElementById("topNavAuthUser");
    if (guestContainer) guestContainer.classList.toggle("hidden", tieneSesion);
    if (userContainer) userContainer.classList.toggle("hidden", !tieneSesion);

    // Drawer Mobile
    const drawerGuest = document.getElementById("drawerAuthGuest");
    const drawerUser = document.getElementById("drawerAuthUser");
    if (drawerGuest) drawerGuest.classList.toggle("hidden", tieneSesion);
    if (drawerUser) drawerUser.classList.toggle("hidden", !tieneSesion);

    if (tieneSesion) {
        const apodo = perfilUsuario.apodo || "Usuario";
        const carrera = perfilUsuario.carrera || "Estudiante";

        const userAvatar = document.getElementById("userHeaderAvatar");
        const safeFotoUrl = sanitizarUrlSegura(perfilUsuario.fotoDataUrl);
        if (userAvatar) {
            if (safeFotoUrl) {
                setHTML(userAvatar, `<img src="${safeFotoUrl}" alt="${escapeHtml(apodo)}" class="user-header-avatar-img">`);
            } else {
                userAvatar.textContent = perfilUsuario.avatar || "👤";
            }
        }
        const userName = document.getElementById("userHeaderName");
        if (userName) userName.textContent = apodo;

        const dropdownName = document.getElementById("userDropdownName");
        if (dropdownName) dropdownName.textContent = apodo;
        const dropdownRole = document.getElementById("userDropdownRole");
        if (dropdownRole) dropdownRole.textContent = carrera;

        const drawerName = document.getElementById("drawerUserName");
        const drawerCareer = document.getElementById("drawerUserCareer");
        const drawerAvatar = document.getElementById("drawerUserAvatar");
        if (drawerName) drawerName.textContent = apodo;
        if (drawerCareer) drawerCareer.textContent = carrera;
        if (drawerAvatar) {
            if (safeFotoUrl) {
                setHTML(drawerAvatar, `<img src="${safeFotoUrl}" alt="${escapeHtml(apodo)}" style="width:100%;height:100%;border-radius:50%;object-fit:cover;">`);
            } else {
                drawerAvatar.textContent = perfilUsuario.avatar || "👤";
            }
        }

        // Modo Medicina: EXCLUSIVO Y ÚNICO PARA IVÁN ('ivi')
        const esIvan = esCuentaIvanActiva();
        actualizarNavExclusivoIvan(esIvan);

        const heroElem = document.querySelector("#viewHome .hero");
        const portalHub = document.querySelector("#viewHome .portal-hub-container");
        const panelMed = document.getElementById("panelMedicinaIvan");
        const shockRoom = document.getElementById("medShockRoomHome");

        if (esIvan) {
            // Para el Dr. Iván, su pantalla de Inicio es el Shock Room
            if (heroElem) heroElem.classList.add("hidden");
            if (portalHub) portalHub.classList.add("hidden");
            if (panelMed) panelMed.classList.add("hidden");
            if (shockRoom) {
                shockRoom.classList.remove("hidden");
                sincronizarShockRoomHome();
            }
            asegurarMateriasMedicinaIvan();
        } else {
            if (heroElem) heroElem.classList.remove("hidden");
            if (portalHub) portalHub.classList.remove("hidden");
            if (panelMed) panelMed.classList.add("hidden");
            sincronizarPortalCardsHome(false);
            if (shockRoom) {
                shockRoom.classList.add("hidden");
                detenerEcgMonitorCanvas();
            }
        }

        const medBtn = document.getElementById("userDropdownMedBtn");
        if (medBtn) {
            medBtn.classList.toggle("hidden", !esIvan);
        }
    } else {
        actualizarNavExclusivoIvan(false);
        const heroElem = document.querySelector("#viewHome .hero");
        const portalHub = document.querySelector("#viewHome .portal-hub-container");
        const panelMed = document.getElementById("panelMedicinaIvan");
        const shockRoom = document.getElementById("medShockRoomHome");

        if (heroElem) heroElem.classList.remove("hidden");
        if (portalHub) portalHub.classList.remove("hidden");
        if (panelMed) panelMed.classList.add("hidden");
        sincronizarPortalCardsHome(false);

        if (shockRoom) {
            shockRoom.classList.add("hidden");
            detenerEcgMonitorCanvas();
        }
        const medBtn = document.getElementById("userDropdownMedBtn");
        if (medBtn) {
            medBtn.classList.add("hidden");
        }
    }
}

function abrirModalAuth(pestaña = "login") {
    if (!dom.authAccountModal) return;
    cambiarPestañaAuth(pestaña);
    if (dom.authLoginUserInput && pestaña === "login") {
        dom.authLoginUserInput.value = "";
    }
    if (dom.authLoginPin && pestaña === "login") {
        dom.authLoginPin.value = "";
    }
    if (dom.authRegApodo) {
        dom.authRegApodo.value = perfilUsuario.apodo !== "Invitado" ? perfilUsuario.apodo : "";
    }
    if (dom.authRegAvatarPreview) {
        setHTML(dom.authRegAvatarPreview, renderAvatarHTML(perfilUsuario, 0, false, 40));
    }
    try {
        dom.authAccountModal.showModal();
    } catch {
        dom.authAccountModal.setAttribute("open", "");
    }
    if (dom.authLoginUserInput && pestaña === "login") {
        setTimeout(() => dom.authLoginUserInput.focus(), 80);
    }
}

function cambiarPestañaAuth(pestaña) {
    if (dom.authTabRegister) dom.authTabRegister.classList.toggle("is-active", pestaña === "register");
    if (dom.authTabLogin) dom.authTabLogin.classList.toggle("is-active", pestaña === "login");
    if (dom.authRegisterForm) dom.authRegisterForm.classList.toggle("hidden", pestaña !== "register");
    if (dom.authLoginForm) dom.authLoginForm.classList.toggle("hidden", pestaña !== "login");
    if (dom.authLoginError) dom.authLoginError.classList.add("hidden");
}


async function crearOActualizarCuenta(apodo, avatar, tipoAvatar, fotoDataUrl, password, email = '', carrera = 'General') {
 return withAuthAction(dom.authSubmitRegisterBtn, async () => {
  if (!currentUser() && !dom.authRegisterForm.reportValidity()) return;
  await registerAccount({ apodo, avatar, tipoAvatar, fotoDataUrl, password, email, carrera });
  mostrarToast('Revisá tu correo para verificar tu cuenta y luego iniciá sesión.', 'info');
  cambiarPestañaAuth('login');
 }, mostrarToast);
}

async function iniciarSesionConPin(email, password) {
 return withAuthAction(dom.authSubmitLoginBtn, () => signIn(email, password), mostrarToast);
}

async function cerrarSesionPerfil() {
 if (!currentUser()) { dom.authAccountModal?.close(); return; }
 return withAuthAction(document.getElementById('userDropdownLogoutBtn'), () => signOut(), mostrarToast);
}

async function recuperarPin() {
 return withAuthAction(dom.authForgotPinBtn, async () => {
  await resetPassword(dom.authLoginUserInput?.value);
  mostrarToast('Si el correo está registrado, recibirás un enlace para cambiar tu contraseña.', 'info');
 }, mostrarToast);
}

function asegurarMateriasMedicinaIvan() {
    let modifico = false;
    MATERIAS_MEDICINA_IVAN.forEach(materia => {
        const existe = estado.listas.some(l => 
            l.id === materia.id || 
            l.nombre.toLowerCase().trim() === materia.nombre.toLowerCase().trim() ||
            l.nombre.toLowerCase().includes(materia.nombre.split(" ")[0].toLowerCase())
        );
        if (!existe) {
            estado.listas.push(JSON.parse(JSON.stringify(materia)));
            modifico = true;
        }
    });
    if (modifico) {
        if (!estado.listaSeleccionadaId) {
            estado.listaSeleccionadaId = MATERIAS_MEDICINA_IVAN[0].id;
        }
        guardarDatos();
        actualizarInterfaz();
    }
}

