/* ==========================================================
   GESTOR DE MULTI-PDF PERSISTENTE PARA CADA MATERIA MÉDICA
   ========================================================== */
const MED_MULTI_PDF_KEY = "luibanez_med_multipdf_v2";

const estadoMultiPdfMedicina = {
    interna: [], // [{ id, name, size, pages, text, timestamp }]
    farma: [],
    salud: []
};

function cargarEstadoPdfsMedicina() {
    try {
        const guardado = studyStorage.getItem(MED_MULTI_PDF_KEY);
        if (guardado) {
            const parsed = JSON.parse(guardado);
            if (parsed.interna) estadoMultiPdfMedicina.interna = parsed.interna;
            if (parsed.farma) estadoMultiPdfMedicina.farma = parsed.farma;
            if (parsed.salud) estadoMultiPdfMedicina.salud = parsed.salud;
        }
    } catch (e) {
        console.warn("No se pudo cargar estado Multi-PDF:", e);
    }
    renderizarListaPdfsMedicina("interna");
    renderizarListaPdfsMedicina("farma");
    renderizarListaPdfsMedicina("salud");
}

function guardarEstadoPdfsMedicina() {
    try {
        // Guardamos metadatos y extractos de texto optimizados
        studyStorage.setItem(MED_MULTI_PDF_KEY, JSON.stringify(estadoMultiPdfMedicina));
    } catch (e) {
        console.warn("Error guardando multi-PDF en localStorage:", e);
    }
}

function obtenerIdsMateria(materia) {
    if (materia === "interna") {
        return {
            list: "medInternaPdfList",
            count: "medInternaPdfCount",
            clear: "medInternaClearPdfsBtn"
        };
    }
    if (materia === "farma") {
        return {
            list: "farmaPdfList",
            count: "farmaPdfCount",
            clear: "farmaClearPdfsBtn"
        };
    }
    if (materia === "salud") {
        return {
            list: "saludPdfList",
            count: "saludPdfCount",
            clear: "saludClearPdfsBtn"
        };
    }
    return {
        list: `med${materia}PdfList`,
        count: `med${materia}PdfCount`,
        clear: `med${materia}ClearPdfsBtn`
    };
}

function renderizarListaPdfsMedicina(materia) {
    const ids = obtenerIdsMateria(materia);
    const listElem = document.getElementById(ids.list);
    const countElem = document.getElementById(ids.count);
    const clearBtn = document.getElementById(ids.clear);
    if (!listElem) return;

    const items = estadoMultiPdfMedicina[materia] || [];
    if (countElem) {
        countElem.textContent = `${items.length} material${items.length === 1 ? '' : 'es'} activo${items.length === 1 ? '' : 's'}`;
    }
    if (clearBtn) {
        clearBtn.classList.toggle("hidden", items.length === 0);
    }

    if (items.length === 0) {
        setHTML(listElem, `<li class="med-pdf-empty">No hay archivos cargados. El simulador usará casos y teoría avanzada del banco universitario.</li>`);
        return;
    }

    setHTML(listElem, items.map((doc, idx) => `
        <li class="med-pdf-item">
            <span aria-hidden="true">📄</span>
            <span class="med-pdf-item-name" title="${escapeHtml(doc.name)}">${escapeHtml(doc.name)}</span>
            <span class="med-pdf-item-meta">${Number(doc.pages) || 1} pág.</span>
            <button type="button" class="med-pdf-item-remove" data-materia="${escapeHtml(materia)}" data-idx="${idx}" title="Quitar archivo">✕</button>
        </li>
    `).join(""));

    listElem.querySelectorAll(".med-pdf-item-remove").forEach(btn => {
        btn.onclick = (e) => {
            e.stopPropagation();
            const mat = btn.dataset.materia;
            const index = parseInt(btn.dataset.idx, 10);
            if (!isNaN(index) && estadoMultiPdfMedicina[mat]) {
                const removido = estadoMultiPdfMedicina[mat].splice(index, 1);
                guardarEstadoPdfsMedicina();
                renderizarListaPdfsMedicina(mat);
                if (removido && removido[0]) {
                    mostrarToast(`🗑️ Quitado: ${removido[0].name}`, "info");
                }
            }
        };
    });
}

async function procesarSubidaArchivosMedicina(files, materia) {
    if (!files || !files.length) return;
    mostrarToast(`📑 Procesando ${files.length} archivo(s)...`, "info");
    let agregados = 0;

    for (let i = 0; i < files.length; i++) {
        const file = files[i];
        try {
            const data = await extraerTextoDeCualquierArchivo(file);
            if (data && data.texto) {
                estadoMultiPdfMedicina[materia].push({
                    id: "doc_" + Date.now() + "_" + Math.random().toString(36).substr(2, 5),
                    name: file.name,
                    size: file.size,
                    pages: data.paginas || 1,
                    text: data.texto.slice(0, 50000), // Muestra rica de conceptos clave
                    timestamp: Date.now()
                });
                agregados++;
            }
        } catch (err) {
            console.error("Error leyendo archivo médico:", err);
            mostrarToast(`⚠️ Error en ${file.name}: ${err.message}`, "error");
        }
    }

    if (agregados > 0) {
        guardarEstadoPdfsMedicina();
        renderizarListaPdfsMedicina(materia);
        mostrarToast(`✅ ¡${agregados} archivo(s) agregados a la biblioteca de ${materia.toUpperCase()}!`, "exito");
    }
}

/* ==========================================================
   BANCO Y MOTOR DE CASOS CLÍNICOS AVANZADOS: MEDICINA INTERNA
   ========================================================== */
let dificultadInternaActiva = 2; // 1: Jr, 2: JTP/Planta, 3: Ateneo Extremo
let sistemaInternaActivo = "todos";
let casoInternaActivoActual = null;
let casoFarmaActivoActual = null;

/* ==========================================================
   HOSPITAL CLINICAL SHOCK ROOM & RESUCITACIÓN (DR. IVÁN)
   ========================================================== */
let casoShockRoomActivo = null;
let ecgAnimationId = null;

const BANCO_CASOS_SHOCK_ROOM = [];

let ecgCanvasObserver = null;
let ecgIntersectionObserver = null;
let ecgIsRunning = false;
let ecgIsIntersecting = true;
let ecgCurrentRitmo = "st_elevado";
let ecgResumeFrameFn = null;

function iniciarEcgMonitorCanvas(ritmoTipo = "st_elevado") {
    detenerEcgMonitorCanvas();
    ecgCurrentRitmo = ritmoTipo;
    const canvas = document.getElementById("shockEcgMonitorCanvas");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    const wrap = canvas.parentElement;

    const dpr = window.devicePixelRatio || 1;
    let rect = canvas.getBoundingClientRect();
    let width = rect.width > 0 ? rect.width : (wrap && wrap.clientWidth > 0 ? wrap.clientWidth : 600);
    const height = 95;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    ctx.scale(dpr, dpr);

    ctx.fillStyle = "#02140a";
    ctx.fillRect(0, 0, width, height);
    dibujarGrillaEcgMonitor(ctx, width, height);

    let x = 0;
    let lastY = height / 2;

    // Adaptabilidad reactiva del monitor ante giros de pantalla y cambios de tamaño
    if (wrap && window.ResizeObserver && !ecgCanvasObserver) {
        ecgCanvasObserver = new ResizeObserver((entries) => {
            for (const entry of entries) {
                const newWidth = Math.floor(entry.contentRect.width);
                if (newWidth > 0 && Math.abs(newWidth - width) > 4) {
                    width = newWidth;
                    canvas.width = width * dpr;
                    canvas.height = height * dpr;
                    ctx.scale(dpr, dpr);
                    ctx.fillStyle = "#02140a";
                    ctx.fillRect(0, 0, width, height);
                    dibujarGrillaEcgMonitor(ctx, width, height);
                    x = 0;
                    lastY = height / 2;
                }
            }
        });
        ecgCanvasObserver.observe(wrap);
    }

    function pasoAnimacion() {
        if (!ecgIsRunning) return;

        // Si la pestaña está oculta o el canvas no está en el viewport, pausar el requestAnimationFrame para ahorrar GPU/batería
        if (document.hidden || !ecgIsIntersecting) {
            ecgAnimationId = null;
            return;
        }

        const speed = ecgCurrentRitmo === "taquicardia" ? 2.8 : (ecgCurrentRitmo === "bradicardia" ? 1.6 : 2.2);
        const nextX = x + speed;

        ctx.fillStyle = "rgba(2, 20, 10, 0.08)";
        ctx.fillRect(x, 0, speed + 14, height);
        dibujarSegmentoGrillaEcg(ctx, x, speed + 14, height);

        const baseY = height / 2;
        let y = baseY;

        const ciclo = ecgCurrentRitmo === "taquicardia" ? 90 : (ecgCurrentRitmo === "bradicardia" ? 220 : 130);
        const pos = Math.floor(x % ciclo);

        if (ecgCurrentRitmo === "st_elevado") {
            if (pos >= 15 && pos < 30) {
                y = baseY - Math.sin(((pos - 15) / 15) * Math.PI) * 5;
            } else if (pos >= 38 && pos < 42) {
                y = baseY + 6;
            } else if (pos >= 42 && pos < 48) {
                y = baseY - 36;
            } else if (pos >= 48 && pos < 52) {
                y = baseY - 12;
            } else if (pos >= 52 && pos < 78) {
                y = baseY - 14 - Math.sin(((pos - 52) / 26) * Math.PI) * 7;
            } else if (pos >= 78 && pos < 88) {
                y = baseY - (1 - (pos - 78) / 10) * 10;
            }
        } else if (ecgCurrentRitmo === "tep") {
            if (pos >= 10 && pos < 22) {
                y = baseY - Math.sin(((pos - 10) / 12) * Math.PI) * 6;
            } else if (pos >= 28 && pos < 32) {
                y = baseY + 4;
            } else if (pos >= 32 && pos < 38) {
                y = baseY - 30;
            } else if (pos >= 38 && pos < 44) {
                y = baseY + 14;
            } else if (pos >= 52 && pos < 68) {
                y = baseY + Math.sin(((pos - 52) / 16) * Math.PI) * 7;
            }
        } else if (ecgCurrentRitmo === "fibrilacion") {
            const jitter = (Math.sin(pos * 0.9) + Math.cos(pos * 1.7)) * 2.5;
            y = baseY + jitter;
            if (pos >= 40 && pos < 45) {
                y = baseY - 28;
            } else if (pos >= 45 && pos < 50) {
                y = baseY + 10;
            } else if (pos >= 56 && pos < 70) {
                y = baseY - Math.sin(((pos - 56) / 14) * Math.PI) * 4;
            }
        } else {
            if (pos >= 15 && pos < 28) {
                y = baseY - Math.sin(((pos - 15) / 13) * Math.PI) * 5;
            } else if (pos >= 36 && pos < 40) {
                y = baseY + 5;
            } else if (pos >= 40 && pos < 45) {
                y = baseY - 34;
            } else if (pos >= 45 && pos < 50) {
                y = baseY + 8;
            } else if (pos >= 58 && pos < 78) {
                y = baseY - Math.sin(((pos - 58) / 20) * Math.PI) * 7;
            }
        }

        ctx.beginPath();
        ctx.strokeStyle = "#4ade80";
        ctx.lineWidth = 1.8;
        ctx.shadowColor = "#22c55e";
        ctx.shadowBlur = 8;
        ctx.moveTo(x, lastY);
        ctx.lineTo(nextX, y);
        ctx.stroke();

        ctx.beginPath();
        ctx.fillStyle = "#86efac";
        ctx.shadowColor = "#86efac";
        ctx.shadowBlur = 12;
        ctx.arc(nextX, y, 2.2, 0, Math.PI * 2);
        ctx.fill();

        ctx.shadowBlur = 0;

        lastY = y;
        x = nextX;

        if (x >= width) {
            x = 0;
            lastY = baseY;
        }

        ecgAnimationId = requestAnimationFrame(pasoAnimacion);
    }

    ecgResumeFrameFn = function() {
        if (ecgIsRunning && !ecgAnimationId && !document.hidden && ecgIsIntersecting) {
            ecgAnimationId = requestAnimationFrame(pasoAnimacion);
        }
    };

    ecgIsRunning = true;

    // IntersectionObserver: pausa el renderizado cuando el monitor no está en la pantalla (scroll)
    if (window.IntersectionObserver) {
        ecgIntersectionObserver = new IntersectionObserver((entries) => {
            for (const entry of entries) {
                ecgIsIntersecting = entry.isIntersecting;
                if (ecgIsIntersecting) {
                    if (ecgResumeFrameFn) ecgResumeFrameFn();
                } else if (ecgAnimationId) {
                    cancelAnimationFrame(ecgAnimationId);
                    ecgAnimationId = null;
                }
            }
        }, { threshold: 0.05 });
        ecgIntersectionObserver.observe(canvas);
    } else {
        ecgIsIntersecting = true;
    }

    if (!document.hidden && ecgIsIntersecting) {
        ecgAnimationId = requestAnimationFrame(pasoAnimacion);
    }
}

function detenerEcgMonitorCanvas() {
    ecgIsRunning = false;
    if (ecgAnimationId) {
        cancelAnimationFrame(ecgAnimationId);
        ecgAnimationId = null;
    }
    if (ecgCanvasObserver) {
        ecgCanvasObserver.disconnect();
        ecgCanvasObserver = null;
    }
    if (ecgIntersectionObserver) {
        ecgIntersectionObserver.disconnect();
        ecgIntersectionObserver = null;
    }
    ecgResumeFrameFn = null;
}

// Pausar el bucle del ECG cuando el usuario cambia de pestaña y reanudarlo al regresar
if (typeof document !== "undefined") {
    document.addEventListener("visibilitychange", () => {
        if (document.hidden) {
            if (ecgAnimationId) {
                cancelAnimationFrame(ecgAnimationId);
                ecgAnimationId = null;
            }
        } else if (ecgIsRunning && ecgResumeFrameFn) {
            ecgResumeFrameFn();
        }
    });
}

function dibujarGrillaEcgMonitor(ctx, width, height) {
    ctx.strokeStyle = "rgba(34, 197, 94, 0.12)";
    ctx.lineWidth = 0.5;
    const step = 15;
    ctx.beginPath();
    for (let gx = 0; gx < width; gx += step) {
        ctx.moveTo(gx, 0);
        ctx.lineTo(gx, height);
    }
    for (let gy = 0; gy < height; gy += step) {
        ctx.moveTo(0, gy);
        ctx.lineTo(width, gy);
    }
    ctx.stroke();
}

function dibujarSegmentoGrillaEcg(ctx, startX, widthSpan, height) {
    ctx.strokeStyle = "rgba(34, 197, 94, 0.08)";
    ctx.lineWidth = 0.5;
    const step = 15;
    ctx.beginPath();
    const firstGx = Math.floor(startX / step) * step;
    for (let gx = firstGx; gx < startX + widthSpan; gx += step) {
        if (gx >= startX && gx <= startX + widthSpan) {
            ctx.moveTo(gx, 0);
            ctx.lineTo(gx, height);
        }
    }
    for (let gy = 0; gy < height; gy += step) {
        ctx.moveTo(startX, gy);
        ctx.lineTo(startX + widthSpan, gy);
    }
    ctx.stroke();
}

function generarCasoShockRoomHome(forzarNuevo = false) {
    if (!BANCO_CASOS_SHOCK_ROOM || BANCO_CASOS_SHOCK_ROOM.length === 0) return;

    let caso = null;
    if (forzarNuevo || !casoShockRoomActivo) {
        const casosDisponibles = BANCO_CASOS_SHOCK_ROOM.filter(c => !casoShockRoomActivo || c.id !== casoShockRoomActivo.id);
        caso = casosDisponibles[Math.floor(Math.random() * casosDisponibles.length)] || BANCO_CASOS_SHOCK_ROOM[0];
        casoShockRoomActivo = caso;
    } else {
        caso = casoShockRoomActivo;
    }

    const bedTag = document.getElementById("shockBedCode");
    if (bedTag) bedTag.textContent = caso.cama || "BOX 01";
    const timeTag = document.getElementById("shockAdmitTime");
    if (timeTag) timeTag.textContent = `⏱️ ${caso.ingreso || "Reciente"}`;
    const patSummary = document.getElementById("shockPatientSummaryTitle");
    if (patSummary) patSummary.textContent = `${caso.edad} · ${caso.titulo.split(" en ")[0] || "Urgencia"}`;
    const synTag = document.getElementById("shockPatientSyndromeTag");
    if (synTag) synTag.textContent = caso.sindrome || "Emergencia Médica";

    const ecgLabel = document.getElementById("shockEcgRhythmLabel");
    if (ecgLabel) ecgLabel.textContent = caso.signosVitales?.fcRitmo || "TAQUICARDIA SINUSAL";

    const fcNum = document.getElementById("shockVitalFc");
    if (fcNum) fcNum.textContent = caso.signosVitales?.fc || 120;
    const fcTrend = document.getElementById("shockVitalFcTrend");
    if (fcTrend) fcTrend.textContent = caso.signosVitales?.fcTrend || "▲ Taquicardia";

    const paNum = document.getElementById("shockVitalPa");
    if (paNum) paNum.textContent = caso.signosVitales?.pa || "80/50";
    const tamElem = document.getElementById("shockVitalTam");
    if (tamElem) {
        tamElem.textContent = `TAM: ${caso.signosVitales?.tam || 60} mmHg`;
        tamElem.className = `shock-metric-trend shock-metric-trend--${caso.signosVitales?.paStatus || "danger"}`;
    }

    const spo2Num = document.getElementById("shockVitalSpo2");
    if (spo2Num) spo2Num.textContent = caso.signosVitales?.spo2 || 90;
    const spo2Trend = document.getElementById("shockVitalSpo2Trend");
    if (spo2Trend) {
        spo2Trend.textContent = caso.signosVitales?.spo2Trend || "FiO2 21%";
        spo2Trend.className = `shock-metric-trend shock-metric-trend--${caso.signosVitales?.spo2Status || "warning"}`;
    }

    const frNum = document.getElementById("shockVitalFr");
    if (frNum) frNum.textContent = caso.signosVitales?.fr || 28;
    const frTrend = document.getElementById("shockVitalFrTrend");
    if (frTrend) frTrend.textContent = caso.signosVitales?.frTrend || "▲ Taquipnea";

    const tempNum = document.getElementById("shockVitalTemp");
    if (tempNum) tempNum.textContent = caso.signosVitales?.temp || "36.5";
    const tempTrend = document.getElementById("shockVitalTempTrend");
    if (tempTrend) tempTrend.textContent = caso.signosVitales?.tempTrend || "Normotérmico";

    const glasgowNum = document.getElementById("shockVitalGlasgow");
    if (glasgowNum) glasgowNum.textContent = (caso.signosVitales?.glasgow || "13").replace("/15", "");
    const glasgowNote = document.getElementById("shockVitalGlasgowNote");
    if (glasgowNote) glasgowNote.textContent = caso.signosVitales?.glasgowNota || "AO:3 RV:4 RM:6";

    const vitalsAnnouncer = document.getElementById("shockVitalsAriaAnnouncer");
    if (vitalsAnnouncer) {
        vitalsAnnouncer.textContent = `Paciente ingresado. Signos vitales: Frecuencia cardíaca ${caso.signosVitales?.fc || 120} latidos por minuto, Presión arterial ${caso.signosVitales?.pa || "80/50"}, Saturación de oxígeno ${caso.signosVitales?.spo2 || 90} por ciento. Ritmo: ${caso.signosVitales?.fcRitmo || "Taquicardia sinusal"}.`;
    }

    // Sincronizar barra fija compacta de signos vitales para móviles
    const stickyFc = document.getElementById("shockStickyFc");
    if (stickyFc) stickyFc.textContent = caso.signosVitales?.fc || 120;
    const stickyPa = document.getElementById("shockStickyPa");
    if (stickyPa) stickyPa.textContent = caso.signosVitales?.pa || "80/50";
    const stickySpo2 = document.getElementById("shockStickySpo2");
    if (stickySpo2) stickySpo2.textContent = `${caso.signosVitales?.spo2 || 90}%`;
    const stickyRhythm = document.getElementById("shockStickyRhythm");
    if (stickyRhythm) stickyRhythm.textContent = caso.signosVitales?.fcRitmo || "TAQUICARDIA SINUSAL";

    iniciarEcgMonitorCanvas(caso.signosVitales?.ritmoEcg || "st_elevado");

    const caseTitle = document.getElementById("shockCaseTitle");
    if (caseTitle) caseTitle.textContent = caso.titulo;
    const patAge = document.getElementById("shockPatientAge");
    if (patAge) patAge.textContent = caso.edad;
    const patBed = document.getElementById("shockPatientBed");
    if (patBed) patBed.textContent = caso.cama;
    const caseEnf = document.getElementById("shockCaseEnfermedadActual");
    if (caseEnf) caseEnf.textContent = caso.motivoIngreso;
    const caseAnt = document.getElementById("shockCaseAntecedentes");
    if (caseAnt) caseAnt.textContent = caso.antecedentes;

    actualizarOrganoFocoShock(caso.organoFocoDefault || "corazon");

    renderizarTablaLaboratorioShock(caso.laboratorio || []);

    if (caso.estudios?.radiografia) {
        const rxTitle = document.getElementById("shockRxTitle");
        if (rxTitle) rxTitle.textContent = caso.estudios.radiografia.titulo || "Rx de Tórax";
        const rxFind = document.getElementById("shockRxFindingsText");
        if (rxFind) rxFind.textContent = caso.estudios.radiografia.hallazgos || "";
        const rxImp = document.getElementById("shockRxImpressionText");
        if (rxImp) rxImp.textContent = caso.estudios.radiografia.impresion || "";
    }

    if (caso.estudios?.tomografia) {
        const tcTitle = document.getElementById("shockTcTitle");
        if (tcTitle) tcTitle.textContent = caso.estudios.tomografia.titulo || "Tomografía Computada";
        const tcFind = document.getElementById("shockTcFindingsText");
        if (tcFind) tcFind.textContent = caso.estudios.tomografia.hallazgos || "";
        const tcImp = document.getElementById("shockTcImpressionText");
        if (tcImp) tcImp.textContent = caso.estudios.tomografia.impresion || "";
    }

    if (caso.estudios?.ecg) {
        const ecgTitle = document.getElementById("shockEcgTitle");
        if (ecgTitle) ecgTitle.textContent = caso.estudios.ecg.titulo || "Electrocardiograma 12D";
        const ecgFind = document.getElementById("shockEcgFindingsText");
        if (ecgFind) ecgFind.textContent = caso.estudios.ecg.hallazgos || "";
        const ecgImp = document.getElementById("shockEcgImpressionText");
        if (ecgImp) ecgImp.textContent = caso.estudios.ecg.impresion || "";
    }

    const inputDiag = document.getElementById("shockStudentDiagnosisInput");
    if (inputDiag) inputDiag.value = "";
    const feedbackPanel = document.getElementById("shockAiFeedbackPanel");
    if (feedbackPanel) {
        feedbackPanel.classList.add("hidden");
        setHTML(feedbackPanel, "");
    }

    // Restablecer pestaña activa a Historia Clínica por defecto
    const tabHistoriaBtn = document.querySelector(".shock-tab-btn[data-tab='historia']");
    if (tabHistoriaBtn) {
        document.querySelectorAll(".shock-tab-btn").forEach(t => t.classList.toggle("is-active", t === tabHistoriaBtn));
        const historiaPane = document.getElementById("shockTabContentHistoria");
        const labPane = document.getElementById("shockTabContentLab");
        const imgPane = document.getElementById("shockTabContentImagenes");
        if (historiaPane) historiaPane.classList.remove("hidden");
        if (labPane) labPane.classList.add("hidden");
        if (imgPane) imgPane.classList.add("hidden");
    }
}

function renderizarTablaLaboratorioShock(datosLab) {
    const wrap = document.getElementById("shockLabTableWrap");
    if (!wrap) return;

    if (!datosLab || datosLab.length === 0) {
        setHTML(wrap, `<div style="padding:1rem;color:#94a3b8;font-size:0.8rem;text-align:center;">Sin datos de laboratorio disponibles.</div>`);
        return;
    }

    const rows = datosLab.map(item => `
        <tr>
            <td class="shock-lab-td-param">
                <div class="shock-lab-param-title">${item.parametro}</div>
                <div class="shock-lab-param-ref">Ref: ${item.ref}</div>
            </td>
            <td class="shock-lab-td-val">
                <span class="shock-lab-val-text">${item.valor}</span>
            </td>
            <td class="shock-lab-td-status">
                <span class="shock-lab-flag ${item.flagClass || "shock-lab-flag--norm"}">${item.alerta}</span>
            </td>
        </tr>
    `).join("");

    setHTML(wrap, `
        <table class="shock-lab-table">
            <thead>
                <tr>
                    <th class="shock-lab-th-param">Determinación & Ref.</th>
                    <th class="shock-lab-th-val">Valor</th>
                    <th class="shock-lab-th-status">Estado</th>
                </tr>
            </thead>
            <tbody>
                ${rows}
            </tbody>
        </table>
    `);
}

function actualizarOrganoFocoShock(organoKey) {
    if (!casoShockRoomActivo || !casoShockRoomActivo.organos) return;
    const datos = casoShockRoomActivo.organos[organoKey] || casoShockRoomActivo.organos.corazon;
    if (!datos) return;

    document.querySelectorAll(".shock-organ-btn").forEach(btn => {
        btn.classList.toggle("is-active", btn.dataset.organ === organoKey);
    });

    document.querySelectorAll(".shock-hotspot").forEach(spot => {
        const isActive = spot.dataset.organ === organoKey;
        spot.classList.toggle("is-active", isActive);
        spot.setAttribute("aria-pressed", isActive ? "true" : "false");
    });

    const iconElem = document.getElementById("shockOrganIcon");
    if (iconElem) iconElem.textContent = datos.icon || "🩺";
    const titleElem = document.getElementById("shockOrganTitle");
    if (titleElem) titleElem.textContent = datos.titulo || "Exploración de Órgano";
    const statusElem = document.getElementById("shockOrganStatus");
    if (statusElem) {
        statusElem.textContent = (datos.estado || "NORMAL").toUpperCase();
        statusElem.className = `shock-status-badge ${datos.statusClass || "shock-status-badge--crit"}`;
    }
    const descElem = document.getElementById("shockOrganDesc");
    if (descElem) descElem.textContent = datos.hallazgos || "Sin particularidades registradas en este foco.";
}

function sincronizarShockRoomHome() {
    const esIvan = esCuentaIvanActiva();
    const heroElem = document.querySelector("#viewHome .hero");
    const portalHub = document.querySelector("#viewHome .portal-hub-container");
    const panelMed = document.getElementById("panelMedicinaIvan");
    const shockRoom = document.getElementById("medShockRoomHome");

    if (esIvan) {
        if (heroElem) heroElem.classList.add("hidden");
        if (portalHub) portalHub.classList.add("hidden");
        if (panelMed) panelMed.classList.add("hidden");
        if (shockRoom) {
            shockRoom.classList.remove("hidden");
            if (!casoShockRoomActivo) {
                generarCasoShockRoomHome();
            } else if (!ecgAnimationId) {
                iniciarEcgMonitorCanvas(casoShockRoomActivo.signosVitales?.ritmoEcg || "st_elevado");
            }
        }
    } else {
        if (heroElem) heroElem.classList.remove("hidden");
        if (portalHub) portalHub.classList.remove("hidden");
        if (panelMed) panelMed.classList.add("hidden");
        if (shockRoom) {
            shockRoom.classList.add("hidden");
            detenerEcgMonitorCanvas();
        }
        sincronizarPortalCardsHome(false);
    }
}

function inicializarEventosShockRoom() {
    // Accesibilidad por teclado en hotspots anatómicos (Enter o Espacio)
    document.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " ") {
            const hotspot = e.target.closest(".shock-hotspot");
            if (hotspot && hotspot.dataset.organ) {
                e.preventDefault();
                actualizarOrganoFocoShock(hotspot.dataset.organ);
            }
        }
    });

    document.addEventListener("click", (e) => {
        const organBtn = e.target.closest(".shock-organ-btn");
        if (organBtn && organBtn.dataset.organ) {
            actualizarOrganoFocoShock(organBtn.dataset.organ);
            return;
        }

        const hotspot = e.target.closest(".shock-hotspot");
        if (hotspot && hotspot.dataset.organ) {
            actualizarOrganoFocoShock(hotspot.dataset.organ);
            return;
        }

        const studyTab = e.target.closest(".shock-tab-btn");
        if (studyTab && studyTab.dataset.tab) {
            const tabId = studyTab.dataset.tab;
            document.querySelectorAll(".shock-tab-btn").forEach(t => t.classList.toggle("is-active", t === studyTab));
            
            const tabMap = {
                historia: "shockTabContentHistoria",
                lab: "shockTabContentLab",
                imagenes: "shockTabContentImagenes",
                rx: "shockTabContentRx",
                tc: "shockTabContentTc",
                ecg: "shockTabContentEcg"
            };

            Object.entries(tabMap).forEach(([key, elemId]) => {
                const el = document.getElementById(elemId);
                if (el) el.classList.toggle("hidden", key !== tabId);
            });
            return;
        }

        const imgSubtab = e.target.closest(".shock-img-subtab-btn");
        if (imgSubtab && imgSubtab.dataset.imgSubtab) {
            const subId = imgSubtab.dataset.imgSubtab;
            document.querySelectorAll(".shock-img-subtab-btn").forEach(t => t.classList.toggle("is-active", t === imgSubtab));
            
            const subMap = {
                rx: "shockTabContentRx",
                tc: "shockTabContentTc",
                ecg: "shockTabContentEcg"
            };

            Object.entries(subMap).forEach(([key, elemId]) => {
                const el = document.getElementById(elemId);
                if (el) el.classList.toggle("hidden", key !== subId);
            });
            return;
        }

        const mobTab = e.target.closest(".shock-mobile-tab-btn");
        if (mobTab && mobTab.dataset.shockTab) {
            const tabName = mobTab.dataset.shockTab;
            document.querySelectorAll(".shock-mobile-tab-btn").forEach(t => t.classList.toggle("is-active", t === mobTab));
            
            // En móvil alternamos visibilidad entre las 3 columnas de la consola
            document.querySelectorAll(".shock-col[data-shock-panel]").forEach(col => {
                const panel = col.dataset.shockPanel;
                const isMatch = (panel === tabName) ||
                                (tabName === "monitor" && (panel === "monitor" || panel === "vitals" || panel === "anatomy")) ||
                                (tabName === "caso" && (panel === "caso" || panel === "center" || panel === "studies")) ||
                                (tabName === "dx" && panel === "dx");
                col.classList.toggle("is-mobile-visible", isMatch);
            });

            if (tabName === "monitor") {
                const canvas = document.getElementById("shockEcgMonitorCanvas");
                if (canvas && (!ecgAnimationId || canvas.width <= 0)) {
                    iniciarEcgMonitorCanvas(casoShockRoomActivo?.signosVitales?.ritmoEcg || "st_elevado");
                }
            }

            if (tabName === "dx") {
                const diagInput = document.getElementById("shockStudentDiagnosisInput");
                if (diagInput && !diagInput.value.trim()) {
                    setTimeout(() => diagInput.focus(), 150);
                }
            }
            return;
        }

        const refreshBtn = e.target.closest("#shockRefreshPatientBtn");
        if (refreshBtn) {
            generarCasoShockRoomHome(true);
            mostrarToast("🔄 Nuevo paciente ingresado a Shock Room", "info");
            return;
        }

        const directBolilleroBtn = e.target.closest("#shockDirectOralBtn");
        if (directBolilleroBtn) {
            cargarMateriaMedicinaEnBolillero("interna");
            return;
        }

        const tplBtn = e.target.closest("#shockTemplateBtn");
        if (tplBtn) {
            const inputDiag = document.getElementById("shockStudentDiagnosisInput");
            if (inputDiag) {
                inputDiag.value = `DIAGNÓSTICO PRINCIPAL: \nDIAGNÓSTICOS DIFERENCIALES: \nCONDUCTA INMEDIATA DE RESUCITACIÓN: `;
                inputDiag.focus();
                inputDiag.setSelectionRange(23, 23);
            }
            return;
        }

        const submitDiagBtn = e.target.closest("#shockSubmitDiagnosisBtn");
        if (submitDiagBtn) {
            evaluarDiagnosticoConIA("shock");
            return;
        }
    });

    const firstMobPanel = document.querySelector(".shock-col[data-shock-panel='monitor']") || 
                          document.querySelector(".shock-col[data-shock-panel='vitals']");
    if (firstMobPanel) firstMobPanel.classList.add("is-mobile-visible");
}

const BANCO_CASOS_INTERNA_AVANZADOS = [];

function generarCasoClinicoInterna(esUrgencia = false) {
    let casosFiltrados = BANCO_CASOS_INTERNA_AVANZADOS;

    if (esUrgencia) {
        const urgentes = casosFiltrados.filter(c => c.dificultad === 3 || c.cama.includes("Shock") || c.cama.includes("Terapia") || c.cama.includes("UCO"));
        if (urgentes.length > 0) casosFiltrados = urgentes;
    } else {
        if (sistemaInternaActivo !== "todos") {
            const porSistema = casosFiltrados.filter(c => c.sistema === sistemaInternaActivo);
            if (porSistema.length > 0) casosFiltrados = porSistema;
        }
        const porDiff = casosFiltrados.filter(c => c.dificultad === dificultadInternaActiva);
        if (porDiff.length > 0) casosFiltrados = porDiff;
    }

    const casoElegido = casosFiltrados[Math.floor(Math.random() * casosFiltrados.length)] || BANCO_CASOS_INTERNA_AVANZADOS[0];
    casoInternaActivoActual = casoElegido;

    // Verificar si hay PDFs cargados en Medicina Interna para integrar
    const pdfsInterna = estadoMultiPdfMedicina.interna || [];
    let customNotice = "";
    if (pdfsInterna.length > 0) {
        const nombresDocs = pdfsInterna.map(d => d.name).join(", ");
        customNotice = `<br><span style="display:inline-block;margin-top:0.35rem;font-size:0.75rem;color:#38bdf8;">📑 Integrado con teoría de tus PDFs: ${nombresDocs}</span>`;
    }

    // Llenar la interfaz
    const pId = document.getElementById("casePatientId");
    const pMeta = document.getElementById("casePatientMeta");
    const diffBadge = document.getElementById("caseDiffBadge");
    const enfAct = document.getElementById("caseEnfermedadActual");
    const antec = document.getElementById("caseAntecedentes");
    const exFis = document.getElementById("caseExamenFisico");
    const labTable = document.getElementById("caseLabTable");
    const qList = document.getElementById("caseQuestionsList");
    const discContent = document.getElementById("medDiscussionContent");
    const discPanel = document.getElementById("medOfficialDiscussionPanel");
    const revealBtn = document.getElementById("medRevealDiscussionBtn");

    if (pId) pId.textContent = `${casoElegido.id} · ${casoElegido.cama}`;
    if (pMeta) setHTML(pMeta, `${casoElegido.edad} · ${casoElegido.ingreso}${customNotice}`);
    if (diffBadge) {
        const labels = { 1: "Nivel 1: Residente Jr.", 2: "Nivel 2: Médico de Planta", 3: "Nivel 3: Ateneo Complejo" };
        diffBadge.textContent = esUrgencia ? "🚨 Urgencia de Guardia" : (labels[casoElegido.dificultad] || "Ateneo Clínico");
        diffBadge.className = esUrgencia ? "badge badge--danger" : (casoElegido.dificultad === 3 ? "badge badge--danger" : casoElegido.dificultad === 1 ? "badge badge--success" : "badge badge--warning");
    }
    if (enfAct) enfAct.textContent = casoElegido.enfermedadActual;
    if (antec) antec.textContent = casoElegido.antecedentes;

    if (exFis) {
        setHTML(exFis, casoElegido.examenFisico.map(it => `<li>${it}</li>`).join(""));
    }

    if (labTable && casoElegido.laboratorio) {
        setHTML(labTable, `<tbody>` + casoElegido.laboratorio.map(row => `
            <tr>
                <td>${row.c1}</td>
                <td>${row.c2 || ''}</td>
            </tr>
        `).join("") + `</tbody>`);
    }

    if (qList && casoElegido.preguntas) {
        setHTML(qList, casoElegido.preguntas.map(q => `<li>${q}</li>`).join(""));
    }

    if (discContent) {
        setHTML(discContent, casoElegido.discusion);
    }

    // Resetear panel de discusión oculto
    if (discPanel) discPanel.classList.add("hidden");
    if (revealBtn) revealBtn.textContent = "💡 Revelar Discusión Clínica y Resolución Razonada";

    // Limpiar input de diagnóstico del alumno y panel de feedback previo
    const inputDiag = document.getElementById("medStudentDiagnosisInput");
    if (inputDiag) inputDiag.value = "";
    const feedbackPanel = document.getElementById("medAiEvaluationFeedback");
    if (feedbackPanel) {
        feedbackPanel.classList.add("hidden");
        setHTML(feedbackPanel, "");
    }

    // Actualizar monitores simulados según el cuadro clínico
    const fcElem = document.getElementById("vitalFC");
    const paElem = document.getElementById("vitalPA");
    const spo2Elem = document.getElementById("vitalSPO2");
    const frElem = document.getElementById("vitalFR");

    if (casoElegido.sistema === "cardio") {
        if (fcElem) fcElem.textContent = casoElegido.dificultad === 3 ? "122" : "118";
        if (paElem) paElem.textContent = casoElegido.dificultad === 3 ? "75/45" : "175/105";
        if (spo2Elem) spo2Elem.textContent = "88%";
        if (frElem) frElem.textContent = "28";
    } else if (casoElegido.sistema === "nefro") {
        if (fcElem) fcElem.textContent = "130";
        if (paElem) paElem.textContent = "85/50";
        if (spo2Elem) spo2Elem.textContent = "96%";
        if (frElem) frElem.textContent = "34";
    } else if (casoElegido.sistema === "neumo") {
        if (fcElem) fcElem.textContent = "128";
        if (paElem) paElem.textContent = "130/80";
        if (spo2Elem) spo2Elem.textContent = "81%";
        if (frElem) frElem.textContent = "38";
    } else if (casoElegido.sistema === "gastro") {
        if (fcElem) fcElem.textContent = "115";
        if (paElem) paElem.textContent = "95/55";
        if (spo2Elem) spo2Elem.textContent = "95%";
        if (frElem) frElem.textContent = "22";
    } else if (casoElegido.sistema === "neuro") {
        if (fcElem) fcElem.textContent = "112";
        if (paElem) paElem.textContent = "165/95";
        if (spo2Elem) spo2Elem.textContent = "97%";
        if (frElem) frElem.textContent = "18";
    } else if (casoElegido.sistema === "infecto") {
        if (fcElem) fcElem.textContent = "132";
        if (paElem) paElem.textContent = "78/42";
        if (spo2Elem) spo2Elem.textContent = "93%";
        if (frElem) frElem.textContent = "30";
    }

    mostrarToast(`⚡ Caso generado: ${casoElegido.id} (${casoElegido.cama})`, "exito");
}

/* ==========================================================
   BANCO Y MOTOR DE DESAFÍOS: FARMACOLOGÍA 2
   ========================================================== */
let dificultadFarmaActiva = 2; // 1: Cinética & Diana, 2: Ajuste & Interacciones, 3: Toxicología & Crisis
let familiaFarmaActiva = "todas";

const BANCO_DESAFIOS_FARMACOLOGIA = [];

function generarDesafioFarma() {
    let filtrados = BANCO_DESAFIOS_FARMACOLOGIA;
    if (familiaFarmaActiva !== "todas") {
        const porFam = filtrados.filter(d => d.familia === familiaFarmaActiva);
        if (porFam.length > 0) filtrados = porFam;
    }
    const porDiff = filtrados.filter(d => d.dificultad === dificultadFarmaActiva);
    if (porDiff.length > 0) filtrados = porDiff;

    const desafio = filtrados[Math.floor(Math.random() * filtrados.length)] || BANCO_DESAFIOS_FARMACOLOGIA[0];
    casoFarmaActivoActual = desafio;

    const pdfsFarma = estadoMultiPdfMedicina.farma || [];
    let customNotice = "";
    if (pdfsFarma.length > 0) {
        customNotice = `<br><span style="display:inline-block;margin-top:0.35rem;font-size:0.75rem;color:#c084fc;">💊 Contrastado con tus textos de Farma: ${pdfsFarma.map(d => d.name).join(", ")}</span>`;
    }

    const cId = document.getElementById("farmaCaseId");
    const cMeta = document.getElementById("farmaCaseMeta");
    const diffBadge = document.getElementById("farmaDiffBadge");
    const cText = document.getElementById("farmaCaseText");
    const labList = document.getElementById("farmaCaseLabList");
    const qList = document.getElementById("farmaQuestionsList");
    const discPanel = document.getElementById("farmaDiscussionPanel");
    const discContent = document.getElementById("farmaDiscussionContent");
    const revealBtn = document.getElementById("farmaRevealDiscussionBtn");

    if (cId) cId.textContent = `${desafio.id} · ${desafio.subtitulo}`;
    if (cMeta) setHTML(cMeta, `Desafío Farmacoterapéutico Universitario${customNotice}`);
    if (diffBadge) {
        const labels = { 1: "Nivel 1: Cinética & Diana", 2: "Nivel 2: Ajuste & Interacciones", 3: "Nivel 3: Toxicología & Crisis" };
        diffBadge.textContent = labels[desafio.dificultad] || "Desafío Farmacológico";
    }
    if (cText) cText.textContent = desafio.texto;
    if (labList && desafio.laboratorio) {
        setHTML(labList, desafio.laboratorio.map(it => `<li>${it}</li>`).join(""));
    }
    if (qList && desafio.preguntas) {
        setHTML(qList, desafio.preguntas.map(it => `<li>${it}</li>`).join(""));
    }
    if (discContent) {
        setHTML(discContent, desafio.discusion);
    }
    if (discPanel) discPanel.classList.add("hidden");
    if (revealBtn) revealBtn.textContent = "💡 Revelar Análisis Farmacoterapéutico";

    // Limpiar notas previas y feedback de IA
    const notesInput = document.getElementById("farmaStudentNotes");
    if (notesInput) notesInput.value = "";
    const fbPanel = document.getElementById("farmaAiEvaluationFeedback");
    if (fbPanel) {
        fbPanel.classList.add("hidden");
        setHTML(fbPanel, "");
    }

    mostrarToast(`🧪 Desafío generado: ${desafio.id}`, "exito");
}

/* ==========================================================
   MOTOR DE EVALUACIÓN DIAGNÓSTICA CON IA CLÍNICA (GEMINI PRO)
   ========================================================== */
async function evaluarDiagnosticoConIA(materia = "interna") {
    const esFarma = materia === "farma";
    const esShock = materia === "shock";
    const inputElem = document.getElementById(
        esShock ? "shockStudentDiagnosisInput" : (esFarma ? "farmaStudentNotes" : "medStudentDiagnosisInput")
    );
    const btnElem = document.getElementById(
        esShock ? "shockSubmitDiagnosisBtn" : (esFarma ? "farmaSubmitDiagnosisBtn" : "medSubmitDiagnosisBtn")
    );
    const feedbackPanel = document.getElementById(
        esShock ? "shockAiFeedbackPanel" : (esFarma ? "farmaAiEvaluationFeedback" : "medAiEvaluationFeedback")
    );

    const textoEstudiante = (inputElem?.value || "").trim();
    if (!textoEstudiante) {
        mostrarToast("✍️ Por favor escribí tu resolución o planteo terapéutico en el recuadro antes de enviar.", "advertencia");
        if (inputElem) {
            inputElem.focus();
            inputElem.scrollIntoView({ behavior: "smooth", block: "center" });
            inputElem.style.borderColor = "#c084fc";
            inputElem.style.boxShadow = "0 0 16px rgba(192, 132, 252, 0.5)";
            setTimeout(() => {
                inputElem.style.borderColor = "";
                inputElem.style.boxShadow = "";
            }, 2500);
        }
        return;
    }

    let casoActivo = esShock ? casoShockRoomActivo : (esFarma ? casoFarmaActivoActual : casoInternaActivoActual);
    if (!casoActivo) {
        if (esShock) {
            casoShockRoomActivo = BANCO_CASOS_SHOCK_ROOM[0];
            casoActivo = casoShockRoomActivo;
        } else if (esFarma) {
            casoFarmaActivoActual = BANCO_DESAFIOS_FARMACOLOGIA[0];
            casoActivo = casoFarmaActivoActual;
        } else {
            casoInternaActivoActual = BANCO_CASOS_INTERNA_AVANZADOS[0];
            casoActivo = casoInternaActivoActual;
        }
    }

    const textoOriginalBoton = btnElem ? btnElem.innerHTML : "";
    if (btnElem) {
        btnElem.disabled = true;
        setHTML(btnElem, `<i class="fas fa-spinner fa-spin"></i> Evaluando con IA Médica...`);
    }

    if (feedbackPanel) {
        feedbackPanel.classList.remove("hidden");
        setHTML(feedbackPanel, `
            <div class="med-ai-feedback-loading">
                <i class="fas fa-brain fa-spin"></i>
                <div style="font-weight:600;font-size:0.95rem;">Profesor Virtual Evaluando Razonamiento Clínico...</div>
                <div style="font-size:0.8rem;color:#94a3b8;margin-top:0.35rem;">Analizando concordancia nosológica, fisiopatología y farmacovigilancia.</div>
            </div>
        `);
        feedbackPanel.scrollIntoView({ behavior: "smooth", block: "nearest" });
    }

    let resultadoFinal = null;

    try {
        let casoTexto = "";
        if (esShock) {
            casoTexto = `${casoActivo.id} (${casoActivo.cama}): ${casoActivo.titulo}. Motivo de Ingreso: ${casoActivo.motivoIngreso}. Signos Vitales: FC ${casoActivo.signosVitales?.fc} lpm, PA ${casoActivo.signosVitales?.pa}, SpO2 ${casoActivo.signosVitales?.spo2}%, FR ${casoActivo.signosVitales?.fr}, Temp ${casoActivo.signosVitales?.temp}°C, Glasgow ${casoActivo.signosVitales?.glasgow}. Laboratorio: ${(casoActivo.laboratorio || []).map(l => `${l.parametro}: ${l.valor} (${l.alerta})`).join(" | ")}. Rx: ${casoActivo.estudios?.radiografia?.hallazgos || ""}. TC: ${casoActivo.estudios?.tomografia?.hallazgos || ""}. ECG: ${casoActivo.estudios?.ecg?.hallazgos || ""}.`;
        } else if (esFarma) {
            casoTexto = `${casoActivo.id}: ${casoActivo.subtitulo}. Enunciado: ${casoActivo.texto}. Laboratorio: ${(casoActivo.laboratorio || []).join(" | ")}.`;
        } else {
            casoTexto = `${casoActivo.id} (${casoActivo.cama}): ${casoActivo.titulo}. Motivo de Ingreso: ${casoActivo.cuadro || casoActivo.enfermedadActual || ""}. Laboratorio: ${(casoActivo.laboratorio || []).map(l => typeof l === 'string' ? l : `${l.c1 || ''} ${l.c2 || ''}`).join(" | ")}. Examen: ${Array.isArray(casoActivo.examenFisico) ? casoActivo.examenFisico.join(" | ") : (casoActivo.examenFisico || "")}.`;
        }

        const payload = {
            tipoJuego: "evaluacion_clinica",
            materia: esShock ? "Shock Room / Medicina de Emergencias" : (esFarma ? "Farmacología 2" : "Medicina Interna"),
            casoClinico: casoTexto,
            diagnosticoOficial: (casoActivo.diagnosticoOficial || casoActivo.discusion || "").replace(/<[^>]*>?/gm, " "),
            diagnosticoEstudiante: textoEstudiante
        };

        resultadoFinal = await requestAI(payload);
        resultadoFinal.fuente = 'Evaluación por IA';
    } catch (err) {
        console.warn("[Evaluador Clínico IA] Fallback a evaluación semántica local:", err);
    }

    if (!resultadoFinal) {
        resultadoFinal = evaluarDiagnosticoClinicoLocal(casoActivo, textoEstudiante, materia);
        resultadoFinal.fuente = "Evaluación orientativa local · IA no disponible";
    }

    if (feedbackPanel) {
        renderizarResultadoEvaluacionIA(feedbackPanel, resultadoFinal);
    }

    if (btnElem) {
        btnElem.disabled = false;
        setHTML(btnElem, textoOriginalBoton);
    }

    mostrarToast(`Evaluación completada: ${resultadoFinal.puntaje}/100 pts`, resultadoFinal.puntaje >= 60 ? "exito" : "advertencia");
}

function renderizarResultadoEvaluacionIA(container, data) {
    if (!container || !data) return;

    const esAprobado = (data.puntaje || 0) >= 60;
    const badgeClass = esAprobado ? "score-badge--pass" : "score-badge--fail";
    const estadoIcon = data.diagnosticoCorrecto ? "fa-circle-check" : "fa-triangle-exclamation";
    const estadoColor = data.diagnosticoCorrecto ? "#22c55e" : "#f59e0b";

    const aciertosHtml = (data.aciertos && data.aciertos.length > 0)
        ? data.aciertos.map(a => `<li><i class="fas fa-check" style="color:#22c55e;margin-right:0.4rem;"></i>${a}</li>`).join("")
        : `<li>Aproximación inicial registrada.</li>`;

    const erroresHtml = (data.erroresUOmitidos && data.erroresUOmitidos.length > 0)
        ? data.erroresUOmitidos.map(e => `<li><i class="fas fa-exclamation-triangle" style="color:#f59e0b;margin-right:0.4rem;"></i>${e}</li>`).join("")
        : `<li>Sin omisiones críticas detectadas en el planteo.</li>`;

    setHTML(container, `
        <div class="med-ai-feedback-header">
            <div style="display:flex;align-items:center;gap:0.75rem;">
                <i class="fas ${estadoIcon}" style="font-size:1.6rem;color:${estadoColor};"></i>
                <div>
                    <h4 style="margin:0;font-size:1.05rem;color:#f8fafc;">${data.veredicto || "Dictamen de Cátedra"}</h4>
                    <span style="font-size:0.75rem;color:#94a3b8;">${escapeHtml(data.fuente || "Evaluación orientativa local")}</span>
                </div>
            </div>
            <div class="score-badge ${badgeClass}">
                <span class="score-number">${data.puntaje || 0}</span>
                <span class="score-label">/ 100</span>
            </div>
        </div>

        <div class="med-ai-critique-box">
            <strong><i class="fas fa-microscope" style="color:#60a5fa;margin-right:0.35rem;"></i>Análisis Fisiopatológico y Razonamiento:</strong>
            <p style="margin:0.4rem 0 0 0;font-size:0.88rem;color:#cbd5e1;line-height:1.5;">${data.analisisFisiopatologico || "Evaluación clínica completada con éxito."}</p>
        </div>

        <div class="med-ai-lists-grid">
            <div class="med-ai-list-card med-ai-list-card--success">
                <span class="med-ai-list-title"><i class="fas fa-thumbs-up"></i> Aciertos y Fortalezas:</span>
                <ul>${aciertosHtml}</ul>
            </div>
            <div class="med-ai-list-card med-ai-list-card--warning">
                <span class="med-ai-list-title"><i class="fas fa-shield-virus"></i> Oportunidades y Omisiones:</span>
                <ul>${erroresHtml}</ul>
            </div>
        </div>

        ${data.conductaTerapeuticaSugerida ? `
            <div style="background:rgba(59,130,246,0.08);border:1px solid rgba(59,130,246,0.25);border-radius:10px;padding:0.75rem 1rem;margin-top:0.8rem;font-size:0.85rem;color:#93c5fd;">
                <strong><i class="fas fa-pills" style="margin-right:0.35rem;"></i>Conducta Terapéutica Sugerida:</strong> ${data.conductaTerapeuticaSugerida}
            </div>
        ` : ""}

        ${data.consejoDocente ? `
            <div style="margin-top:0.75rem;padding:0.6rem 0.85rem;border-left:3px solid #c084fc;background:rgba(192,132,252,0.08);font-size:0.82rem;color:#e9d5ff;border-radius:0 8px 8px 0;">
                <strong><i class="fas fa-user-doctor" style="margin-right:0.35rem;"></i>Consejo del Docente:</strong> "${data.consejoDocente}"
            </div>
        ` : ""}
    `);
    container.classList.remove("hidden");
    container.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function evaluarDiagnosticoClinicoLocal(caso, textoEstudiante, materia) {
    const textoNorm = (textoEstudiante || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    const nombreCaso = caso.titulo || caso.subtitulo || "Caso Clínico";

    // 1. Extracción y análisis de conceptos clave de la resolución oficial
    const discusionLimpia = (caso.discusion || "").replace(/<[^>]*>?/gm, " ").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    const palabrasClave = discusionLimpia.match(/\b[a-z]{5,}\b/g) || [];
    
    const stopWords = new Set([
        "porque", "cuando", "donde", "paciente", "cuadro", "clinico", "administracion",
        "tratamiento", "presenta", "ademas", "durante", "produce", "debido", "inmediata",
        "deberia", "primer", "segundo", "tercer", "pueden", "generar", "llevar", "cuanto",
        "tiempo", "forma", "horas", "dias", "nivel", "niveles"
    ]);
    const terminosImportantes = [...new Set(palabrasClave.filter(w => !stopWords.has(w)))];

    // Contar coincidencias reales
    let coincidencias = 0;
    const aciertosDetectados = [];
    terminosImportantes.forEach(t => {
        if (textoNorm.includes(t)) {
            coincidencias++;
            if (aciertosDetectados.length < 4) {
                aciertosDetectados.push(`Mención precisa del concepto fisiopatológico / farmacológico: "${t}"`);
            }
        }
    });

    // Detección de hipótesis descabelladas, sin correlato o frases de prueba
    const tieneCancer = textoNorm.includes("cancer") || textoNorm.includes("oncolog") || textoNorm.includes("tumor");
    const esCasoCancer = discusionLimpia.includes("cancer") || discusionLimpia.includes("oncolog") || discusionLimpia.includes("tumor");
    const diceMuerte = textoNorm.includes("morir") || textoNorm.includes("muerte") || textoNorm.includes("letal");

    // 2. CASO CERO ACIERTOS / ERROR CRÍTICO O DIAGNÓSTICO DISPARATADO (0/100)
    if (coincidencias === 0) {
        let motivoCritica = `Tu planteo ('"${textoEstudiante.length > 70 ? textoEstudiante.substring(0, 67) + "..." : textoEstudiante}"') NO guarda ninguna relación con la presentación clínica, los signos vitales ni el laboratorio de este paciente.`;
        if (tieneCancer && !esCasoCancer) {
            motivoCritica += ` Diagnosticaste patología oncológica ("cáncer") en un paciente que no presenta ningún antecedente, síndrome consuntivo ni biopsia que lo sugiera.`;
        }
        if (diceMuerte) {
            motivoCritica += ` Afirmar fatalidad ("se va a morir") sin formular una hipótesis nosológica ni una intervención terapéutica constituye una conducta inaceptable en la práctica médica.`;
        }
        motivoCritica += ` El paciente presenta en realidad: <strong>${nombreCaso}</strong>. En un hospital real o examen universitario, este planteo implicaría desaprobación fulminante por riesgo iatrogénico.`;

        return {
            diagnosticoCorrecto: false,
            puntaje: 0,
            veredicto: "Desacierto Diagnóstico Total / Error Crítico (0/100)",
            analisisFisiopatologico: motivoCritica,
            aciertos: [
                "Ninguno. No se identificó la patología del caso ni se formularon medidas terapéuticas válidas."
            ],
            erroresUOmitidos: [
                "Diagnóstico completamente erróneo sin correlación clínica ni paraclínica",
                "Omisión absoluta de los valores de laboratorio y electrocardiograma aportados",
                "Falta de indicación de medidas de soporte vital y rescate farmacológico real",
                tieneCancer && !esCasoCancer ? "Presunción infundada de neoplasia sin evidencia" : "Inconsistencia nosológica grave"
            ],
            conductaTerapeuticaSugerida: caso.discusion ? caso.discusion.replace(/<[^>]*>?/gm, " ").substring(0, 260) + "..." : "Consultar resolución oficial de cátedra.",
            consejoDocente: "Dr. Iván: La cátedra exige rigurosidad científica implacable. Un médico jamás puede adivinar o diagnosticar por intuición sin contrastar los datos. Antes de emitir una conducta, lee los antecedentes, el examen físico y el laboratorio."
        };
    }

    // 3. APROXIMACIÓN MUY INSUFICIENTE (1 coincidencia aislada - 25/100)
    if (coincidencias === 1) {
        return {
            diagnosticoCorrecto: false,
            puntaje: 25,
            veredicto: "Aproximación Muy Insuficiente (25/100)",
            analisisFisiopatologico: `Identificaste únicamente un término aislado (${aciertosDetectados[0]}), pero careces de desarrollo fisiopatológico. No se articula la relación de causa-efecto ni el protocolo terapéutico de primera línea para ${nombreCaso}.`,
            aciertos: aciertosDetectados,
            erroresUOmitidos: [
                "Falta de formulación del síndrome cardinal completo",
                "Omisión del mecanismo farmacológico o diana molecular principal",
                "Plan terapéutico incompleto o insuficiente para estabilizar al paciente"
            ],
            conductaTerapeuticaSugerida: materia === "farma"
                ? "Identificar el transportador/enzima afectada, ajustar según clearance y dosificar el antídoto específico."
                : "Monitoreo invasivo continuo y terapia etiológica dirigida según guías clínicas.",
            consejoDocente: "Dr. Iván: Nombrar un concepto no alcanza para aprobar un pase de sala. Necesitás fundamentar el por qué y el tratamiento de rescate inmediato."
        };
    }

    // 4. ENFOQUE PARCIAL (2 coincidencias - 50/100)
    if (coincidencias === 2) {
        return {
            diagnosticoCorrecto: false,
            puntaje: 50,
            veredicto: "Enfoque Parcial / Insuficiente para Criterio de Alta (50/100)",
            analisisFisiopatologico: `Demuestras orientación general hacia ${nombreCaso}, pero con omisiones determinantes en la farmacovigilancia o en las contraindicaciones críticas del paciente.`,
            aciertos: aciertosDetectados,
            erroresUOmitidos: [
                "Falta precisar interacciones farmacocinéticas o ajustes orgánicos",
                "Monitoreo de parámetros de seguridad pendientes"
            ],
            conductaTerapeuticaSugerida: "Profundizar en la conducta razonada de cátedra y dosificación protocolizada.",
            consejoDocente: "Dr. Iván: Buen inicio del razonamiento, pero en la práctica estas omisiones pueden generar descompensación. Ajustá la farmacocinética fina."
        };
    }

    // 5. DIAGNÓSTICO CERTERO Y SÓLIDO (3 a 4 coincidencias - 78/100)
    if (coincidencias < 5) {
        return {
            diagnosticoCorrecto: true,
            puntaje: 78,
            veredicto: "Diagnóstico Certero con Buen Razonamiento Clínico (78/100)",
            analisisFisiopatologico: `¡Muy buen planteo! Identificaste los factores determinantes de ${nombreCaso}. Tu conducta terapéutica es coherente con las guías de cátedra.`,
            aciertos: aciertosDetectados,
            erroresUOmitidos: [
                "Podrías afinar detalles sobre la ventana de monitoreo o dosis exactas"
            ],
            conductaTerapeuticaSugerida: materia === "farma"
                ? "Ajustar dosis según función renal/hepática y verificar interacciones con la medicación de base."
                : "Medidas de soporte hemodinámico y tratamiento de rescate según normativas vigentes.",
            consejoDocente: "Excelente criterio diagnóstico, colega. Mantén este estándar de fundamentación en cada pase de guardia."
        };
    }

    // 6. RESOLUCIÓN DE EXCELENCIA (5+ coincidencias - 95/100)
    return {
        diagnosticoCorrecto: true,
        puntaje: 95,
        veredicto: "Resolución de Excelencia · Nivel Médico de Planta (95/100)",
        analisisFisiopatologico: `Resolución impecable. Dominas la fisiopatología, las dianas moleculares, la interacción farmacocinética y la conducta de rescate para ${nombreCaso}.`,
        aciertos: aciertosDetectados,
        erroresUOmitidos: [
            "Sin omisiones de relevancia clínica detectadas en tu desarrollo"
        ],
        conductaTerapeuticaSugerida: "Conducta óptima aplicada.",
        consejoDocente: "Brillante, Dr. Iván. Un análisis exhaustivo y de máxima solvencia que salvaría la vida del paciente en un escenario real."
    };
}

