function inicializarCalculadoraCientificaMini() {
    if (!dom.labWidgetProb) return;
    const keys = dom.labWidgetProb.querySelectorAll(".lab-ckey");
    let expr = "";

    keys.forEach(k => {
        k.addEventListener("click", () => {
            const key = k.getAttribute("data-key");
            if (!dom.labCalcScreen) return;

            if (key === "clear") {
                expr = "";
                dom.labCalcScreen.value = "0";
            } else if (key === "del") {
                expr = expr.slice(0, -1);
                dom.labCalcScreen.value = expr || "0";
            } else if (key === "=") {
                try {
                    const cleanExpr = expr.replace(/×/g, "*").replace(/÷/g, "/");
                    const res = evaluateExpression(cleanExpr);
                    if (!Number.isFinite(res)) throw new Error('Expresión inválida');
                    dom.labCalcScreen.value = String(res);
                    expr = String(res);
                } catch (e) {
                    dom.labCalcScreen.value = "Error";
                    expr = "";
                }
            } else if (key === "sqrt") {
                try {
                    const val = parseFloat(expr || dom.labCalcScreen.value);
                    const res = Math.sqrt(val);
                    dom.labCalcScreen.value = String(res);
                    expr = String(res);
                } catch(e) {}
            } else if (key === "pow") {
                try {
                    const val = parseFloat(expr || dom.labCalcScreen.value);
                    const res = Math.pow(val, 2);
                    dom.labCalcScreen.value = String(res);
                    expr = String(res);
                } catch(e) {}
            } else {
                if (expr === "0" && key !== ".") expr = "";
                expr += key;
                dom.labCalcScreen.value = expr;
            }
        });
    });
}

// ==========================================
// CONTROLADOR DE MATRIZ DE BAYES Y FÓRMULAS DE PROBABILIDAD
// ==========================================

function recalcularMatrizBayes() {
    const ab = parseFloat(dom.labBayesCellAB?.value) || 0;
    const aNotB = parseFloat(dom.labBayesCellANotB?.value) || 0;
    const notAB = parseFloat(dom.labBayesCellNotAB?.value) || 0;
    const notANotB = parseFloat(dom.labBayesCellNotANotB?.value) || 0;

    const totalA = ab + aNotB;
    const totalNotA = notAB + notANotB;
    const totalB = ab + notAB;
    const totalNotB = aNotB + notANotB;
    const grandTotal = totalA + totalNotA;

    // Nombres de los 4 eventos personalizados
    const evA = (dom.labBayesEvAName?.value || "A (Enfermo)").trim();
    const evNotA = (dom.labBayesEvNotAName?.value || "A' (Sano)").trim();
    const evB = (dom.labBayesEvBName?.value || "B (Test +)").trim();
    const evNotB = (dom.labBayesEvNotBName?.value || "B' (Test -)").trim();

    // Actualizar encabezados de la tabla de contingencia
    if (dom.labBayesThA) dom.labBayesThA.textContent = evA;
    if (dom.labBayesThNotA) dom.labBayesThNotA.textContent = evNotA;
    if (dom.labBayesThB) dom.labBayesThB.textContent = evB;
    if (dom.labBayesThNotB) dom.labBayesThNotB.textContent = evNotB;

    // Actualizar celdas marginales
    if (dom.labBayesTotalA) dom.labBayesTotalA.textContent = String(totalA);
    if (dom.labBayesTotalNotA) dom.labBayesTotalNotA.textContent = String(totalNotA);
    if (dom.labBayesTotalB) dom.labBayesTotalB.textContent = String(totalB);
    if (dom.labBayesTotalNotB) dom.labBayesTotalNotB.textContent = String(totalNotB);
    if (dom.labBayesGrandTotal) dom.labBayesGrandTotal.textContent = String(grandTotal);

    // Cálculos de Probabilidad
    const N = grandTotal > 0 ? grandTotal : 1;
    const pA = totalA / N;
    const pNotA = totalNotA / N;
    const pB = totalB / N;
    const pNotB = totalNotB / N;

    const pAnB = ab / N;
    const pAnNotB = aNotB / N;
    const pNotAnB = notAB / N;
    const pNotAnNotB = notANotB / N;

    // 1. Regla de la Unión: P(A U B) = P(A) + P(B) - P(A ∩ B)
    const pAuB = pA + pB - pAnB;
    const sonIncompatibles = ab === 0;

    // 2. Probabilidad Condicional
    const pAgivenB = totalB > 0 ? (ab / totalB) : 0;
    const pBgivenA = totalA > 0 ? (ab / totalA) : 0;
    const pNotAgivenB = totalB > 0 ? (notAB / totalB) : 0;

    // 3. Regla del Producto / Independencia
    const pProdIndep = pA * pB;
    const sonIndependientes = Math.abs(pAnB - pProdIndep) < 0.0001;

    // 4. Suceso Contrario / Complementario
    const pContrarioA = 1 - pA;
    const pContrarioB = 1 - pB;
    const pDeMorganUnion = pNotAnNotB; // P(A' ∩ B') = 1 - P(A U B)
    const pDeMorganIntersec = 1 - pAnB; // P(A' U B') = 1 - P(A ∩ B)

    // Compatibilidad hacia atrás si existen elementos individuales
    if (dom.labBayesFormulaText) {
        dom.labBayesFormulaText.textContent = `P(${evA}|${evB}) = P(${evA} ∩ ${evB}) / P(${evB}) = ${ab} / ${totalB}`;
    }
    if (dom.labBayesResultVal) {
        dom.labBayesResultVal.textContent = `${pAgivenB.toFixed(4)} (${(pAgivenB * 100).toFixed(2)}%)`;
    }

    // Renderizar sección completa de fórmulas de probabilidad de cátedra
    if (dom.labBayesFormulasContainer) {
        setHTML(dom.labBayesFormulasContainer, `
            <div class="lab-bayes-header-box" style="margin-top: 0.5rem;">
                <span class="lab-bayes-header-title">📐 Fórmulas Oficiales de Probabilidad de Cátedra (Cálculo en Vivo):</span>
                <p class="lab-bayes-header-desc">Desglose analítico paso a paso calculado automáticamente con los totales y celdas de la tabla.</p>
            </div>

            <div class="lab-bayes-formulas-grid">
                <!-- CARD 1: REGLA DE LA UNIÓN -->
                <div class="lab-bayes-card">
                    <div class="lab-bayes-card-header">
                        <span class="lab-bayes-card-title">1. Regla de la Unión (O / Suma)</span>
                        <span class="lab-bayes-badge-rule">${sonIncompatibles ? 'Incompatibles' : 'Compatibles'}</span>
                    </div>
                    <div class="lab-bayes-math-formula">
                        P(A ∪ B) = P(A) + P(B) - P(A ∩ B)
                    </div>
                    <div class="lab-bayes-step-calc">
                        • <strong>P(A)</strong> = ${totalA}/${N} = ${pA.toFixed(4)}<br>
                        • <strong>P(B)</strong> = ${totalB}/${N} = ${pB.toFixed(4)}<br>
                        • <strong>P(A ∩ B)</strong> = ${ab}/${N} = ${pAnB.toFixed(4)}<br>
                        • Sustitución: ${pA.toFixed(4)} + ${pB.toFixed(4)} - ${pAnB.toFixed(4)}
                    </div>
                    <div class="lab-bayes-result-row">
                        <span class="lab-bayes-res-label">P(A ∪ B):</span>
                        <strong class="lab-bayes-res-val">${pAuB.toFixed(4)} (${(pAuB * 100).toFixed(2)}%)</strong>
                    </div>
                </div>

                <!-- CARD 2: PROBABILIDAD CONDICIONAL (BAYES) -->
                <div class="lab-bayes-card">
                    <div class="lab-bayes-card-header">
                        <span class="lab-bayes-card-title">2. Probabilidad Condicional (Dado que...)</span>
                        <span class="lab-bayes-badge-rule">Teorema de Bayes</span>
                    </div>
                    <div class="lab-bayes-math-formula">
                        P(A / B) = P(A ∩ B) / P(B)
                    </div>
                    <div class="lab-bayes-step-calc">
                        • <strong>P(A | B)</strong> = ${ab} / ${totalB} = <strong>${pAgivenB.toFixed(4)}</strong> (${(pAgivenB * 100).toFixed(2)}%)<br>
                        • <strong>P(B | A)</strong> = ${ab} / ${totalA} = <strong>${pBgivenA.toFixed(4)}</strong> (${(pBgivenA * 100).toFixed(2)}%)<br>
                        • <strong>P(A' | B)</strong> = ${notAB} / ${totalB} = <strong>${pNotAgivenB.toFixed(4)}</strong> (${(pNotAgivenB * 100).toFixed(2)}%)
                    </div>
                    <div class="lab-bayes-result-row">
                        <span class="lab-bayes-res-label">P(A | B) Valor Predictivo:</span>
                        <strong class="lab-bayes-res-val lab-bayes-res-val--info">${pAgivenB.toFixed(4)} (${(pAgivenB * 100).toFixed(2)}%)</strong>
                    </div>
                </div>

                <!-- CARD 3: REGLA DE LA MULTIPLICACIÓN E INDEPENDENCIA -->
                <div class="lab-bayes-card">
                    <div class="lab-bayes-card-header">
                        <span class="lab-bayes-card-title">3. Multiplicación & Independencia</span>
                        <span class="lab-bayes-badge-rule">${sonIndependientes ? '✅ Independientes' : '⚠️ Dependientes'}</span>
                    </div>
                    <div class="lab-bayes-math-formula">
                        P(A ∩ B) = P(A) · P(B / A)
                    </div>
                    <div class="lab-bayes-step-calc">
                        • <strong>Regla general:</strong> P(A) · P(B|A) = ${pA.toFixed(4)} · ${pBgivenA.toFixed(4)} = ${pAnB.toFixed(4)}<br>
                        • <strong>Test de independencia:</strong><br>
                        &nbsp;&nbsp;P(A) · P(B) = ${pProdIndep.toFixed(4)} ${sonIndependientes ? '==' : '≠'} P(A ∩ B) = ${pAnB.toFixed(4)}<br>
                        • <em>${sonIndependientes ? 'Los sucesos son estadísticamente independientes.' : 'Los sucesos son dependientes (el resultado de B afecta a A).'}</em>
                    </div>
                    <div class="lab-bayes-result-row">
                        <span class="lab-bayes-res-label">Intersección P(A ∩ B):</span>
                        <strong class="lab-bayes-res-val lab-bayes-res-val--purple">${pAnB.toFixed(4)} (${(pAnB * 100).toFixed(2)}%)</strong>
                    </div>
                </div>

                <!-- CARD 4: SUCESOS CONTRARIOS Y LEYES DE DE MORGAN -->
                <div class="lab-bayes-card">
                    <div class="lab-bayes-card-header">
                        <span class="lab-bayes-card-title">4. Complementarios & De Morgan</span>
                        <span class="lab-bayes-badge-rule">P(Ā) = 1 - P(A)</span>
                    </div>
                    <div class="lab-bayes-math-formula">
                        P(A̅ ∩ B̅) = P(A̅ ∪ B̅)' = 1 - P(A ∪ B)
                    </div>
                    <div class="lab-bayes-step-calc">
                        • <strong>P(A̅) = P(No A)</strong> = 1 - ${pA.toFixed(4)} = <strong>${pContrarioA.toFixed(4)}</strong> (${(pContrarioA * 100).toFixed(2)}%)<br>
                        • <strong>P(B̅) = P(No B)</strong> = 1 - ${pB.toFixed(4)} = <strong>${pContrarioB.toFixed(4)}</strong> (${(pContrarioB * 100).toFixed(2)}%)<br>
                        • <strong>De Morgan P(A̅ ∩ B̅):</strong> ${notANotB}/${N} = <strong>${pDeMorganUnion.toFixed(4)}</strong> (${(pDeMorganUnion * 100).toFixed(2)}%)<br>
                        • <strong>De Morgan P(A̅ ∪ B̅):</strong> 1 - P(A∩B) = <strong>${pDeMorganIntersec.toFixed(4)}</strong> (${(pDeMorganIntersec * 100).toFixed(2)}%)
                    </div>
                    <div class="lab-bayes-result-row">
                        <span class="lab-bayes-res-label">P(A̅) [Suceso Contrario]:</span>
                        <strong class="lab-bayes-res-val lab-bayes-res-val--amber">${pContrarioA.toFixed(4)} (${(pContrarioA * 100).toFixed(2)}%)</strong>
                    </div>
                </div>
            </div>
        `);
    }
}

// ==========================================
// CONTROLADOR DEL PIZARRÓN CIENTÍFICO FLOTANTE
// (CUADRICULADO + REGLA + DESHACER + IA OCR)
// ==========================================

function inicializarScratchpadLab() {
    const canvas = dom.labScratchCanvas;
    const floating = dom.labFloatingWhiteboard;
    if (!canvas || !floating) return;
    const ctx = canvas.getContext("2d");
    const st = laboratorioEstado.scratchState;

    if (!st.undoStack) st.undoStack = [];

    function guardarEstadoUndo() {
        try {
            if (st.undoStack.length >= 25) st.undoStack.shift();
            st.undoStack.push(ctx.getImageData(0, 0, canvas.width, canvas.height));
        } catch (e) {
            console.warn("No se pudo capturar estado undo del canvas:", e);
        }
    }

    function resize() {
        const wrap = dom.labScratchCanvasWrap;
        if (!wrap) return;
        const rect = wrap.getBoundingClientRect();
        if (rect.width > 0 && rect.height > 0) {
            const w = Math.round(rect.width);
            const h = Math.round(rect.height);
            if (canvas.width !== w || canvas.height !== h) {
                const temp = document.createElement("canvas");
                temp.width = canvas.width;
                temp.height = canvas.height;
                const tCtx = temp.getContext("2d");
                tCtx.drawImage(canvas, 0, 0);

                canvas.width = w;
                canvas.height = h;
                ctx.lineCap = "round";
                ctx.lineJoin = "round";
                ctx.drawImage(temp, 0, 0, w, h);
            }
        }
    }

    function getCoords(e) {
        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width;
        const scaleY = canvas.height / rect.height;
        return {
            x: (e.clientX - rect.left) * scaleX,
            y: (e.clientY - rect.top) * scaleY
        };
    }

    if (!st.initialized) {
        st.initialized = true;

        // 1. Eventos de dibujo en canvas (Pointer Events con bloqueo de scroll nativo)
        canvas.addEventListener("pointerdown", (e) => {
            e.preventDefault();
            try { canvas.setPointerCapture(e.pointerId); } catch (_) {}
            st.drawing = true;
            const p = getCoords(e);
            st.startX = p.x;
            st.startY = p.y;
            st.lastX = p.x;
            st.lastY = p.y;

            guardarEstadoUndo();

            if (st.tool === "ruler") {
                st.rulerSnapshot = ctx.getImageData(0, 0, canvas.width, canvas.height);
            } else if (st.tool === "eraser") {
                ctx.save();
                ctx.globalCompositeOperation = "destination-out";
                ctx.beginPath();
                ctx.arc(p.x, p.y, (st.size || 2) * 5, 0, Math.PI * 2);
                ctx.fill();
                ctx.restore();
            } else {
                ctx.save();
                ctx.globalCompositeOperation = "source-over";
                ctx.beginPath();
                ctx.arc(p.x, p.y, (st.size || 2) / 2, 0, Math.PI * 2);
                ctx.fillStyle = st.color || "#ffffff";
                ctx.fill();
                ctx.restore();
            }
        }, { passive: false });

        canvas.addEventListener("pointermove", (e) => {
            if (!st.drawing) return;
            e.preventDefault();
            const p = getCoords(e);

            if (st.tool === "ruler") {
                if (st.rulerSnapshot) {
                    ctx.putImageData(st.rulerSnapshot, 0, 0);
                    ctx.save();
                    ctx.globalCompositeOperation = "source-over";
                    ctx.beginPath();
                    ctx.moveTo(st.startX, st.startY);
                    ctx.lineTo(p.x, p.y);
                    ctx.strokeStyle = st.color || "#38bdf8";
                    ctx.lineWidth = st.size || 2;
                    ctx.lineCap = "round";
                    ctx.stroke();
                    ctx.restore();
                }
            } else if (st.tool === "eraser") {
                ctx.save();
                ctx.globalCompositeOperation = "destination-out";
                ctx.beginPath();
                ctx.moveTo(st.lastX, st.lastY);
                ctx.lineTo(p.x, p.y);
                ctx.strokeStyle = "rgba(0,0,0,1)";
                ctx.lineWidth = (st.size || 2) * 10;
                ctx.lineCap = "round";
                ctx.lineJoin = "round";
                ctx.stroke();
                ctx.restore();
                st.lastX = p.x;
                st.lastY = p.y;
            } else {
                ctx.save();
                ctx.globalCompositeOperation = "source-over";
                ctx.beginPath();
                ctx.moveTo(st.lastX, st.lastY);
                ctx.lineTo(p.x, p.y);
                ctx.strokeStyle = st.color || "#ffffff";
                ctx.lineWidth = st.size || 2;
                ctx.lineCap = "round";
                ctx.lineJoin = "round";
                ctx.stroke();
                ctx.restore();
                st.lastX = p.x;
                st.lastY = p.y;
            }
        }, { passive: false });

        const stopDrawing = () => {
            if (st.drawing) {
                st.drawing = false;
                st.rulerSnapshot = null;
            }
        };
        canvas.addEventListener("pointerup", stopDrawing);
        canvas.addEventListener("pointercancel", stopDrawing);

        // Bloqueo explícito de gestos touch en móviles para evitar que la pantalla se trabe o deslice la página
        canvas.addEventListener("touchstart", (e) => {
            e.preventDefault();
        }, { passive: false });
        canvas.addEventListener("touchmove", (e) => {
            e.preventDefault();
        }, { passive: false });

        // 2. Herramientas: Lápiz, Regla, Goma
        if (dom.labScratchPenBtn) {
            dom.labScratchPenBtn.addEventListener("click", () => {
                st.tool = "pen";
                dom.labScratchPenBtn.classList.add("is-active");
                if (dom.labScratchRulerBtn) dom.labScratchRulerBtn.classList.remove("is-active");
                if (dom.labScratchEraserBtn) dom.labScratchEraserBtn.classList.remove("is-active");
                if (dom.labScratchCanvasWrap) dom.labScratchCanvasWrap.classList.remove("is-ruler-mode");
            });
        }

        if (dom.labScratchRulerBtn) {
            dom.labScratchRulerBtn.addEventListener("click", () => {
                st.tool = "ruler";
                dom.labScratchRulerBtn.classList.add("is-active");
                if (dom.labScratchPenBtn) dom.labScratchPenBtn.classList.remove("is-active");
                if (dom.labScratchEraserBtn) dom.labScratchEraserBtn.classList.remove("is-active");
                if (dom.labScratchCanvasWrap) dom.labScratchCanvasWrap.classList.add("is-ruler-mode");
                mostrarToast("📏 Modo Regla: hacé clic y arrastrá para trazar líneas rectas");
            });
        }

        if (dom.labScratchEraserBtn) {
            dom.labScratchEraserBtn.addEventListener("click", () => {
                st.tool = "eraser";
                dom.labScratchEraserBtn.classList.add("is-active");
                if (dom.labScratchPenBtn) dom.labScratchPenBtn.classList.remove("is-active");
                if (dom.labScratchRulerBtn) dom.labScratchRulerBtn.classList.remove("is-active");
                if (dom.labScratchCanvasWrap) dom.labScratchCanvasWrap.classList.remove("is-ruler-mode");
            });
        }

        // 3. Selección de Colores
        floating.querySelectorAll(".color-dot").forEach(dot => {
            dot.addEventListener("click", () => {
                floating.querySelectorAll(".color-dot").forEach(d => d.classList.remove("is-active"));
                dot.classList.add("is-active");
                st.color = dot.getAttribute("data-color") || "#ffffff";
                if (st.tool === "eraser") {
                    st.tool = "pen";
                    if (dom.labScratchPenBtn) dom.labScratchPenBtn.classList.add("is-active");
                    if (dom.labScratchEraserBtn) dom.labScratchEraserBtn.classList.remove("is-active");
                }
            });
        });

        // 4. Selección de Grosor
        floating.querySelectorAll(".stroke-dot").forEach(dot => {
            dot.addEventListener("click", () => {
                floating.querySelectorAll(".stroke-dot").forEach(d => d.classList.remove("is-active"));
                dot.classList.add("is-active");
                st.size = parseInt(dot.getAttribute("data-size") || "2", 10);
            });
        });

        // 5. Botón Deshacer (Undo)
        if (dom.labScratchUndoBtn) {
            dom.labScratchUndoBtn.addEventListener("click", () => {
                if (st.undoStack && st.undoStack.length > 0) {
                    const prev = st.undoStack.pop();
                    ctx.putImageData(prev, 0, 0);
                    mostrarToast("↩️ Trazo deshecho");
                } else {
                    mostrarToast("ℹ️ No hay trazos previos para deshacer");
                }
            });
        }

        // 6. Botón Borrar Todo (Clear)
        if (dom.labScratchClearBtn) {
            dom.labScratchClearBtn.addEventListener("click", () => {
                guardarEstadoUndo();
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                mostrarToast("🗑️ Pizarrón limpiado (podés deshacer con Atrás)");
            });
        }

        // 7. Botón Emprolijar con IA
        if (dom.labScratchAiCleanBtn) {
            dom.labScratchAiCleanBtn.addEventListener("click", () => {
                emprolijarFormulasConIA();
            });
        }

        // 8. Botón Minimizar / Restaurar
        if (dom.labWhiteboardMinBtn) {
            dom.labWhiteboardMinBtn.addEventListener("click", () => {
                floating.classList.toggle("is-minimized");
                if (floating.classList.contains("is-minimized")) {
                    dom.labWhiteboardMinBtn.textContent = "□";
                    dom.labWhiteboardMinBtn.title = "Restaurar";
                } else {
                    dom.labWhiteboardMinBtn.textContent = "_";
                    dom.labWhiteboardMinBtn.title = "Minimizar";
                    setTimeout(resize, 80);
                }
            });
        }

        // 9. Botón Cerrar
        if (dom.labWhiteboardCloseBtn) {
            dom.labWhiteboardCloseBtn.addEventListener("click", () => {
                cerrarPizarronFlotanteLab();
            });
        }

        // 10. Drawer de Resultados IA
        if (dom.labAiResultCloseBtn) {
            dom.labAiResultCloseBtn.addEventListener("click", () => {
                if (dom.labWhiteboardAiResult) dom.labWhiteboardAiResult.classList.add("hidden");
            });
        }
        if (dom.labAiCleanSpaceBtn) {
            dom.labAiCleanSpaceBtn.addEventListener("click", () => {
                guardarEstadoUndo();
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                mostrarToast("🧹 Espacio liberado en el pizarrón. Tus fórmulas siguen acá abajo.");
            });
        }

        // 11. Arrastre del Pizarrón (Draggable Header)
        const header = dom.labWhiteboardHeader;
        if (header) {
            let dragging = false;
            let startX = 0;
            let startY = 0;
            let initialLeft = 0;
            let initialTop = 0;

            header.addEventListener("pointerdown", (e) => {
                if (e.target.closest("button")) return;
                dragging = true;
                header.setPointerCapture(e.pointerId);
                const rect = floating.getBoundingClientRect();
                startX = e.clientX;
                startY = e.clientY;
                initialLeft = rect.left;
                initialTop = rect.top;
            });

            header.addEventListener("pointermove", (e) => {
                if (!dragging) return;
                const dx = e.clientX - startX;
                const dy = e.clientY - startY;

                const maxLeft = window.innerWidth - 80;
                const maxTop = window.innerHeight - 60;
                const newLeft = Math.max(10, Math.min(maxLeft, initialLeft + dx));
                const newTop = Math.max(10, Math.min(maxTop, initialTop + dy));

                floating.style.left = `${newLeft}px`;
                floating.style.top = `${newTop}px`;
                floating.style.right = "auto";
                floating.style.bottom = "auto";
            });

            const stopDrag = () => { dragging = false; };
            header.addEventListener("pointerup", stopDrag);
            header.addEventListener("pointercancel", stopDrag);
        }

        // Atajo de teclado: Ctrl+Z para deshacer
        window.addEventListener("keydown", (e) => {
            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z" && !floating.classList.contains("hidden")) {
                const targetTag = (e.target.tagName || "").toLowerCase();
                if (targetTag !== "input" && targetTag !== "textarea") {
                    e.preventDefault();
                    if (dom.labScratchUndoBtn) dom.labScratchUndoBtn.click();
                }
            }
        });
    }

    setTimeout(resize, 80);
}

function conmutarPizarronFlotanteLab() {
    const floating = dom.labFloatingWhiteboard;
    const tabBtn = dom.labTabBtnScratch;
    if (!floating) return;

    if (floating.classList.contains("hidden")) {
        floating.classList.remove("hidden");
        floating.classList.remove("is-minimized");
        if (dom.labWhiteboardMinBtn) {
            dom.labWhiteboardMinBtn.textContent = "_";
            dom.labWhiteboardMinBtn.title = "Minimizar";
        }
        if (tabBtn) tabBtn.classList.add("is-active");
        inicializarScratchpadLab();
        mostrarToast("📝 Pizarrón abierto. Podés moverlo arrastrando la barra superior.");
    } else if (floating.classList.contains("is-minimized")) {
        floating.classList.remove("is-minimized");
        if (dom.labWhiteboardMinBtn) {
            dom.labWhiteboardMinBtn.textContent = "_";
            dom.labWhiteboardMinBtn.title = "Minimizar";
        }
        if (tabBtn) tabBtn.classList.add("is-active");
        inicializarScratchpadLab();
    } else {
        cerrarPizarronFlotanteLab();
    }
}

function cerrarPizarronFlotanteLab() {
    const floating = dom.labFloatingWhiteboard;
    const tabBtn = dom.labTabBtnScratch;
    if (floating) floating.classList.add("hidden");
    if (tabBtn) tabBtn.classList.remove("is-active");
}

async function emprolijarFormulasConIA() {
 const canvas = dom.labScratchCanvas;
 if (!canvas) return;
 const button = document.getElementById('labScratchAiCleanBtn');
 return withAuthAction(button, async () => {
  if (dom.labAiCleanOverlay) dom.labAiCleanOverlay.classList.remove('hidden');
  try {
   const result = await requestAI({ tipoJuego: 'pizarron_ocr', imagenBase64: canvas.toDataURL('image/png'), materia: 'Estadística y Probabilidad', tema: laboratorioEstado.temaSeleccionado || 'descriptiva' });
   if (!result.formulas.length) { mostrarToast('No se reconocieron fórmulas. Escribí más claro y reintentá.', 'info'); return; }
   renderizarFormulasReconocidas(result.formulas, result.consejo);
  } finally { dom.labAiCleanOverlay?.classList.add('hidden'); }
 }, mostrarToast);
}

function renderizarFormulasReconocidas(formulas, consejo) {
    if (!dom.labWhiteboardAiResult || !dom.labAiResultContent) return;

    setHTML(dom.labAiResultContent, "");

    formulas.forEach((f, idx) => {
        const item = document.createElement("div");
        item.className = "lab-ai-formula-item";

        setHTML(item, `
            <div class="lab-ai-formula-item-top">
                <span class="lab-ai-formula-title">✨ ${f.titulo || `Fórmula ${idx + 1}`}</span>
                <button type="button" class="button button--ghost button--xs lab-copy-formula-btn" title="Copiar fórmula">
                    📋 Copiar
                </button>
            </div>
            <div class="lab-ai-formula-math">${f.latex || f.resultado || f.manuscrito || ""}</div>
            ${f.explicacion ? `<span class="lab-ai-formula-exp">${f.explicacion}</span>` : ""}
        `);

        const copyBtn = item.querySelector(".lab-copy-formula-btn");
        if (copyBtn) {
            copyBtn.addEventListener("click", () => {
                const textToCopy = `${f.titulo || ''}: ${f.latex || f.resultado || ''}`.trim();
                navigator.clipboard.writeText(textToCopy).then(() => {
                    mostrarToast("📋 ¡Fórmula copiada al portapapeles!");
                }).catch(() => {
                    mostrarToast(`Copiado: ${textToCopy}`);
                });
            });
        }

        dom.labAiResultContent.appendChild(item);
    });

    if (consejo) {
        const tipEl = document.createElement("div");
        tipEl.style.fontSize = "0.74rem";
        tipEl.style.color = "#38bdf8";
        tipEl.style.marginTop = "0.25rem";
        setHTML(tipEl, `💡 <em>${consejo}</em>`);
        dom.labAiResultContent.appendChild(tipEl);
    }

    if (dom.labAiCopyAllBtn) {
        dom.labAiCopyAllBtn.onclick = () => {
            const fullText = formulas.map(f => `${f.titulo}: ${f.latex || f.resultado}`).join("\n");
            navigator.clipboard.writeText(fullText).then(() => {
                mostrarToast("📋 ¡Todas las fórmulas copiadas!");
            });
        };
    }

    dom.labWhiteboardAiResult.classList.remove("hidden");
    mostrarToast("✨ Fórmulas detectadas y emprolijadas con éxito.");
}

// ==========================================
// CONTROLADORES DE INTERFAZ Y VISTA MÓVIL
// ==========================================

function filtrarTabsPorMateria(materiaId) {
    if (!dom.labTabsNav) return;
    
    // Mapeo de visibilidad de pestañas según la materia
    const visibilidadPorMateria = {
        contabilidad: ["contabilidad"],
        estadistica: ["freq", "prob", "bayes"],
        quimica: ["quimica"],
        fisica: ["fisica"],
        matematicas: ["matematicas"],
        calculo: ["calculo"],
        algebra_lineal: ["matrices"],
        computacion: ["computacion"],
        biologia: ["biologia"],
        financiera: ["financiera"],
        medicina: ["medicina"]
    };

    const permitidas = visibilidadPorMateria[materiaId] || ["matematicas"];

    // Mostrar/ocultar botones de pestañas según la materia
    const tabBtns = [
        { btn: dom.labTabBtnFreq, id: "freq" },
        { btn: dom.labTabBtnProb, id: "prob" },
        { btn: dom.labTabBtnBayes, id: "bayes" },
        { btn: dom.labTabBtnContabilidad, id: "contabilidad" },
        { btn: dom.labTabBtnQuimica, id: "quimica" },
        { btn: dom.labTabBtnFisica, id: "fisica" },
        { btn: dom.labTabBtnMatematicas, id: "matematicas" },
        { btn: dom.labTabBtnCalculo, id: "calculo" },
        { btn: dom.labTabBtnMatrices, id: "matrices" },
        { btn: dom.labTabBtnComputacion, id: "computacion" },
        { btn: dom.labTabBtnBiologia, id: "biologia" },
        { btn: dom.labTabBtnFinanciera, id: "financiera" },
        { btn: dom.labTabBtnMedicina, id: "medicina" }
    ];

    tabBtns.forEach(({ btn, id }) => {
        if (!btn) return;
        const visible = permitidas.includes(id);
        btn.classList.toggle("hidden", !visible);
    });

    // Activar la primera pestaña permitida
    activarTabLaboratorio(permitidas[0]);
}

function activarTabLaboratorio(tabId) {
    if (tabId === "scratch") {
        conmutarPizarronFlotanteLab();
        return;
    }

    const tabPanels = [
        { btn: dom.labTabBtnFreq, pane: dom.labWidgetFreq, id: "freq" },
        { btn: dom.labTabBtnProb, pane: dom.labWidgetProb, id: "prob" },
        { btn: dom.labTabBtnBayes, pane: dom.labWidgetBayes, id: "bayes" },
        { btn: dom.labTabBtnContabilidad, pane: dom.labWidgetContabilidad, id: "contabilidad" },
        { btn: dom.labTabBtnQuimica, pane: dom.labWidgetQuimica, id: "quimica" },
        { btn: dom.labTabBtnFisica, pane: dom.labWidgetFisica, id: "fisica" },
        { btn: dom.labTabBtnMatematicas, pane: dom.labWidgetMatematicas, id: "matematicas" },
        { btn: dom.labTabBtnCalculo, pane: dom.labWidgetCalculo, id: "calculo" },
        { btn: dom.labTabBtnMatrices, pane: dom.labWidgetMatrices, id: "matrices" },
        { btn: dom.labTabBtnComputacion, pane: dom.labWidgetComputacion, id: "computacion" },
        { btn: dom.labTabBtnBiologia, pane: dom.labWidgetBiologia, id: "biologia" },
        { btn: dom.labTabBtnFinanciera, pane: dom.labWidgetFinanciera, id: "financiera" },
        { btn: dom.labTabBtnMedicina, pane: dom.labWidgetMedicina, id: "medicina" }
    ];

    tabPanels.forEach(t => {
        const matches = t.id === tabId;
        if (t.btn) t.btn.classList.toggle("is-active", matches);
        if (t.pane) t.pane.classList.toggle("hidden", !matches);
    });

    laboratorioEstado.tabActiva = tabId;

    // Disparar renderizados iniciales si entra por primera vez a un widget interactivo
    if (tabId === "quimica" && typeof renderizarTablaPeriodicaUI === "function") {
        renderizarTablaPeriodicaUI();
    } else if (tabId === "fisica" && typeof inicializarSimuladorFisica === "function") {
        inicializarSimuladorFisica();
    } else if (tabId === "matematicas" && typeof inicializarGraficadorMatematicas === "function") {
        inicializarGraficadorMatematicas();
    }
}

function cambiarVistaMovilLab(vista, scrollTarget = false) {
    if (!dom.laboratorioSplit) return;
    dom.laboratorioSplit.setAttribute("data-mobile-view", vista);

    if (dom.labMobileBtnEnunciado) {
        dom.labMobileBtnEnunciado.classList.toggle("is-active", vista === "enunciado");
        dom.labMobileBtnEnunciado.setAttribute("aria-selected", vista === "enunciado" ? "true" : "false");
    }
    if (dom.labMobileBtnHerramientas) {
        dom.labMobileBtnHerramientas.classList.toggle("is-active", vista === "herramientas");
        dom.labMobileBtnHerramientas.setAttribute("aria-selected", vista === "herramientas" ? "true" : "false");
    }

    if (dom.labMobileFloatIcon && dom.labMobileFloatText) {
        if (vista === "enunciado") {
            dom.labMobileFloatIcon.textContent = "🛠️";
            dom.labMobileFloatText.textContent = "Mesa de Trabajo";
        } else {
            dom.labMobileFloatIcon.textContent = "📋";
            dom.labMobileFloatText.textContent = "Ver Enunciado";
        }
    }

    // Si toca la mesa de trabajo y la materia es contabilidad, SIEMPRE abrir Libro Diario (nunca el mayor)
    if (vista === "herramientas" && (laboratorioEstado.materiaSeleccionada === "contabilidad" || laboratorioEstado.tabActiva === "contabilidad")) {
        cambiarSubvistaContabilidad("diario");
    }

    if (scrollTarget) {
        const target = vista === "enunciado" ? (dom.labActiveCheckpointCard || dom.labPanelEnunciado) : dom.labPanelHerramientas;
        if (target) {
            target.scrollIntoView({ behavior: "smooth", block: "nearest" });
        }
    }
}

// ==========================================
// FLUJO DEL LABORATORIO Y GENERADOR DE CASOS
// ==========================================

function iniciarOReanudarLaboratorio() {
    // Restaurar progreso previo de almacenamiento
    cargarLaboratorioStorage();
    cargarContabilidadStorage();

    if (!laboratorioEstado.iniciado) {
        laboratorioEstado.iniciado = true;
        configurarEventosLaboratorio();
        inicializarGrillaFrecuencias();
        inicializarCalculadoraDistribuciones();
        inicializarCalculadoraCientificaMini();
        recalcularMatrizBayes();
        inicializarScratchpadLab();
        sincronizarSelectoresDificultadLab();
        inicializarModuloContabilidad();
        inicializarCalculadorasLaboratorio();
    }

    // Si la materia es contabilidad, asegurar subvista de Libro Diario
    if (laboratorioEstado.materiaSeleccionada === "contabilidad") {
        cambiarSubvistaContabilidad("diario");
    }

    cambiarVistaMovilLab("enunciado");
    filtrarTabsPorMateria(laboratorioEstado.materiaSeleccionada || "estadistica");

    // Abrir menú flotante solo si no hay ejercicio o si se ingresa por primera vez
    if (!laboratorioEstado.ejercicioActual) {
        abrirModalConfigLab();
    } else {
        actualizarBadgesMateriaLabUI();
        if (typeof renderizarEjercicioActual === "function") {
            renderizarEjercicioActual(false);
        }
    }
}

// ------------------------------------------
// SELECTOR MULTIDISCIPLINARIO DE EXACTAS Y CONTABILIDAD (PASO 1 & PASO 2)
// ------------------------------------------

function mostrarPasoModalLab(paso) {
    if (paso === 1) {
        if (dom.labStepMaterias) dom.labStepMaterias.classList.remove("hidden");
        if (dom.labStepConfigMateria) dom.labStepConfigMateria.classList.add("hidden");
        if (dom.labBtnCargarConfig) dom.labBtnCargarConfig.classList.add("hidden");
        if (dom.labConfigModalSubtitle) {
            dom.labConfigModalSubtitle.textContent = "Elegí tu disciplina para empezar a practicar con simuladores interactivos e IA.";
        }
    } else {
        if (dom.labStepMaterias) dom.labStepMaterias.classList.add("hidden");
        if (dom.labStepConfigMateria) dom.labStepConfigMateria.classList.remove("hidden");
        if (dom.labBtnCargarConfig) dom.labBtnCargarConfig.classList.remove("hidden");
        const mat = CATALOGO_MATERIAS_LABORATORIO[laboratorioEstado.materiaSeleccionada] || CATALOGO_MATERIAS_LABORATORIO.estadistica;
        if (dom.labConfigModalSubtitle) {
            dom.labConfigModalSubtitle.textContent = `Configurá los temas de ${mat.nombre} y cargá material de apoyo opcional.`;
        }
    }
}

function renderizarSelectorMateriasLab() {
    const grid = dom.labDisciplinesGrid || dom.labDisciplinesList;
    if (!grid) return;
    setHTML(grid, "");

    const ordenPrioritario = ["estadistica", "contabilidad"];
    const materiasList = Object.values(CATALOGO_MATERIAS_LABORATORIO).slice().sort((a, b) => {
        const idxA = ordenPrioritario.indexOf(a.id);
        const idxB = ordenPrioritario.indexOf(b.id);
        if (idxA !== -1 && idxB !== -1) return idxA - idxB;
        if (idxA !== -1) return -1;
        if (idxB !== -1) return 1;
        return 0;
    });

    materiasList.forEach(mat => {
        const card = document.createElement("div");
        card.className = "lab-subject-card";
        card.setAttribute("role", "button");
        card.setAttribute("tabindex", "0");
        card.dataset.materia = mat.id;

        setHTML(card, `
            <div class="lab-subject-icon-box">
                <span>${mat.icono}</span>
            </div>
            <strong class="lab-subject-name">${mat.nombre}</strong>
            <span class="lab-subject-badge">${mat.badge}</span>
        `);

        const entrarAMateria = () => {
            seleccionarMateriaLab(mat.id);
        };

        card.addEventListener("click", entrarAMateria);
        card.addEventListener("keydown", (e) => {
            if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                entrarAMateria();
            }
        });

        grid.appendChild(card);
    });

    // Iniciar siempre en Paso 1 (Solo las materias)
    mostrarPasoModalLab(1);
}

function seleccionarMateriaLab(materiaId) {
    const mat = CATALOGO_MATERIAS_LABORATORIO[materiaId];
    if (!mat) return;

    // Guardar el estado de la materia anterior
    sincronizarEstadoMateriaActualLab();

    laboratorioEstado.materiaSeleccionada = materiaId;

    // Cargar progreso previo guardado para la nueva materia (si existía)
    cargarEstadoMateriaLab(materiaId);
    guardarLaboratorioStorage();

    // Actualizar Banner y tema del Modal Paso 2
    if (dom.labStepConfigMateria) {
        dom.labStepConfigMateria.setAttribute("data-materia", materiaId);
    }
    if (dom.labConfigModal) {
        dom.labConfigModal.setAttribute("data-materia", materiaId);
    }
    if (dom.labMateriaBannerIcon) dom.labMateriaBannerIcon.textContent = mat.icono;
    if (dom.labMateriaBannerTitle) dom.labMateriaBannerTitle.textContent = mat.nombre;
    if (dom.labMateriaBannerDesc) dom.labMateriaBannerDesc.textContent = mat.descripcion;

    renderizarOpcionesSubtemasLab(materiaId);

    // Cambiar al Paso 2: vista personalizada de la materia
    mostrarPasoModalLab(2);
}

function renderizarOpcionesSubtemasLab(materiaId) {
    if (!dom.labSubtopicsGrid) return;
    setHTML(dom.labSubtopicsGrid, "");

    const mat = CATALOGO_MATERIAS_LABORATORIO[materiaId] || CATALOGO_MATERIAS_LABORATORIO.contabilidad;
    if (dom.labSubtopicsTitle) {
        setHTML(dom.labSubtopicsTitle, `<span>🎯 Opciones y temas a practicar en <strong>${mat.nombre}</strong>:</span>`);
    }

    const seleccionados = Array.isArray(laboratorioEstado.temasSeleccionados)
        ? laboratorioEstado.temasSeleccionados
        : [];

    mat.subtemas.forEach(sub => {
        const estaMarcado = seleccionados.includes(sub.id);
        const card = document.createElement("label");
        card.className = `lab-subtopic-card ${estaMarcado ? "is-selected" : ""}`;
        card.dataset.subtemaId = sub.id;
        card.dataset.materia = materiaId;
        card.setAttribute("role", "checkbox");
        card.setAttribute("aria-checked", estaMarcado ? "true" : "false");
        card.setAttribute("tabindex", "0");

        const chk = document.createElement("input");
        chk.type = "checkbox";
        chk.className = "lab-subtopic-checkbox hidden";
        chk.checked = estaMarcado;
        chk.value = sub.id;

        chk.addEventListener("change", (e) => {
            e.stopPropagation();
            alternarSeleccionSubtemaLab(sub.id, chk.checked);
        });

        card.appendChild(chk);

        // Estructura visual idéntica a las tarjetas del primer menú
        setHTML(card, card.innerHTML + `
            <div class="lab-subtopic-icon-box">
                <span>${sub.icono || mat.icono}</span>
            </div>
            <strong class="lab-subtopic-name">${sub.nombre}</strong>
            <span class="lab-subtopic-desc">${sub.desc}</span>
            <span class="lab-subtopic-badge">${estaMarcado ? "✓ Seleccionado" : "+ Elegir"}</span>
        `);

        const toggler = () => {
            const nuevoEstado = !chk.checked;
            chk.checked = nuevoEstado;
            alternarSeleccionSubtemaLab(sub.id, nuevoEstado);
        };

        card.addEventListener("click", (e) => {
            if (e.target === chk) return;
            e.preventDefault();
            toggler();
        });

        card.addEventListener("keydown", (e) => {
            if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                toggler();
            }
        });

        dom.labSubtopicsGrid.appendChild(card);
    });

    actualizarContadorSubtemasBadge();
}

function alternarSeleccionSubtemaLab(subtemaId, checked) {
    if (!Array.isArray(laboratorioEstado.temasSeleccionados)) {
        laboratorioEstado.temasSeleccionados = [];
    }

    if (checked) {
        if (!laboratorioEstado.temasSeleccionados.includes(subtemaId)) {
            laboratorioEstado.temasSeleccionados.push(subtemaId);
        }
    } else {
        laboratorioEstado.temasSeleccionados = laboratorioEstado.temasSeleccionados.filter(id => id !== subtemaId);
    }

    // Reflejar clase, atributo de accesibilidad y badge en la tarjeta
    if (dom.labSubtopicsGrid) {
        const card = dom.labSubtopicsGrid.querySelector(`[data-subtema-id="${subtemaId}"]`);
        if (card) {
            card.classList.toggle("is-selected", checked);
            card.setAttribute("aria-checked", checked ? "true" : "false");
            const chk = card.querySelector('input[type="checkbox"]');
            if (chk) chk.checked = checked;
            const badge = card.querySelector('.lab-subtopic-badge');
            if (badge) badge.textContent = checked ? "✓ Seleccionado" : "+ Elegir";
        }
    }

    actualizarContadorSubtemasBadge();
}

function seleccionarTodosSubtemasLab() {
    const mat = CATALOGO_MATERIAS_LABORATORIO[laboratorioEstado.materiaSeleccionada] || CATALOGO_MATERIAS_LABORATORIO.contabilidad;
    laboratorioEstado.temasSeleccionados = mat.subtemas.map(s => s.id);
    renderizarOpcionesSubtemasLab(laboratorioEstado.materiaSeleccionada);
}

function limpiarSubtemasLab() {
    laboratorioEstado.temasSeleccionados = [];
    renderizarOpcionesSubtemasLab(laboratorioEstado.materiaSeleccionada);
}

function actualizarContadorSubtemasBadge() {
    if (!dom.labSubtopicsCountBadge) return;
    const count = (laboratorioEstado.temasSeleccionados || []).length;
    dom.labSubtopicsCountBadge.textContent = `${count} ${count === 1 ? 'tema seleccionado' : 'temas seleccionados'}`;
}

function actualizarBadgesMateriaLabUI() {
    const matId = laboratorioEstado.materiaSeleccionada || "contabilidad";
    const mat = CATALOGO_MATERIAS_LABORATORIO[matId] || CATALOGO_MATERIAS_LABORATORIO.contabilidad;

    if (dom.labMateriaBadge) {
        dom.labMateriaBadge.textContent = `${mat.icono} ${mat.nombre}`;
    }

    if (dom.labActiveTopicBadge) {
        const seleccionados = laboratorioEstado.temasSeleccionados || [];
        if (seleccionados.length === 0) {
            dom.labActiveTopicBadge.textContent = `${mat.icono} Práctica General`;
        } else if (seleccionados.length === 1) {
            const sub = mat.subtemas.find(s => s.id === seleccionados[0]);
            dom.labActiveTopicBadge.textContent = `${mat.icono} ${sub ? sub.nombre : seleccionados[0]}`;
        } else {
            const subPrimero = mat.subtemas.find(s => s.id === seleccionados[0]);
            dom.labActiveTopicBadge.textContent = `${mat.icono} ${subPrimero ? subPrimero.nombre : 'Temas'} (+${seleccionados.length - 1})`;
        }
    }
}

// ------------------------------------------
// MODAL DE CONFIGURACIÓN Y APERTURA
// ------------------------------------------

function abrirModalConfigLab() {
    renderizarSelectorMateriasLab();
    if (typeof sincronizarSelectoresDificultadLab === "function") sincronizarSelectoresDificultadLab();

    if (dom.labConfigModal) {
        if (typeof dom.labConfigModal.showModal === "function") {
            try { dom.labConfigModal.showModal(); } catch { dom.labConfigModal.setAttribute("open", ""); }
        } else {
            dom.labConfigModal.setAttribute("open", "");
        }
    }
}

function cerrarModalConfigLab() {
    if (dom.labConfigModal) {
        if (typeof dom.labConfigModal.close === "function") {
            try { dom.labConfigModal.close(); } catch { dom.labConfigModal.removeAttribute("open"); }
        } else {
            dom.labConfigModal.removeAttribute("open");
        }
    }
}

// =========================================================
// MÓDULO CONTABLE: LIBRO DIARIO, MAYOR (CUENTAS T) Y BALANCE
// =========================================================

function inicializarModuloContabilidad() {
    // Configurar pestañas internas de contabilidad
    if (dom.labBtnSubtabDiario) {
        dom.labBtnSubtabDiario.addEventListener("click", () => cambiarSubvistaContabilidad("diario"));
    }
    if (dom.labBtnSubtabMayor) {
        dom.labBtnSubtabMayor.addEventListener("click", () => cambiarSubvistaContabilidad("mayor"));
    }
    if (dom.labBtnSubtabBalance) {
        dom.labBtnSubtabBalance.addEventListener("click", () => cambiarSubvistaContabilidad("balance"));
    }
    if (dom.labBtnSubtabCalcContab) {
        dom.labBtnSubtabCalcContab.addEventListener("click", () => cambiarSubvistaContabilidad("calc"));
    }

    // Botones del Libro Diario
    if (dom.labBtnAddAsiento) {
        dom.labBtnAddAsiento.addEventListener("click", () => agregarAsientoContable());
    }
    if (dom.labBtnAutoMayorizar) {
        dom.labBtnAutoMayorizar.addEventListener("click", () => {
            sincronizarLibroMayor();
            cambiarSubvistaContabilidad("mayor");
            mostrarToast("📖 Asientos mayorizados con éxito en las Cuentas T.", "exito");
        });
    }
    if (dom.labBtnLimpiarDiario) {
        dom.labBtnLimpiarDiario.addEventListener("click", () => {
            contabilidadEstado.asientos = [
                {
                    id: 1,
                    fecha: "01/03",
                    detalle: "",
                    filas: [
                        { id: "f1", cuenta: "", variacion: "", debe: "", haber: "" },
                        { id: "f2", cuenta: "", variacion: "", debe: "", haber: "" }
                    ]
                }
            ];
            contabilidadEstado.mayores = {};
            contabilidadEstado.balance = [];
            guardarContabilidadStorage();
            cambiarSubvistaContabilidad("diario");
            renderizarLibroDiarioUI();
            renderLibroMayorUI();
            sincronizarBalanceSumasYSaldos();
            mostrarToast("🗑️ Libro Diario vaciado y listo para comenzar.", "info");
        });
    }

    // Botones del Libro Mayor
    if (dom.labBtnSyncMayor) {
        dom.labBtnSyncMayor.addEventListener("click", () => {
            sincronizarLibroMayor();
            mostrarToast("🔄 Cuentas T actualizadas desde el Diario.", "info");
        });
    }
    if (dom.labBtnAddCuentaTManual) {
        dom.labBtnAddCuentaTManual.addEventListener("click", () => {
            const nombre = prompt("Ingresá el nombre de la nueva cuenta contable:");
            if (nombre && nombre.trim()) {
                const nombreLimpio = nombre.trim();
                if (!contabilidadEstado.mayores[nombreLimpio]) {
                    contabilidadEstado.mayores[nombreLimpio] = {
                        debe: [],
                        haber: [],
                        totalDebe: 0,
                        totalHaber: 0,
                        saldo: 0,
                        tipoSaldo: "deudor"
                    };
                    renderLibroMayorUI();
                    sincronizarBalanceSumasYSaldos();
                }
            }
        });
    }

    // Botón de Balance
    if (dom.labBtnActualizarBalance) {
        dom.labBtnActualizarBalance.addEventListener("click", () => {
            sincronizarBalanceSumasYSaldos();
            mostrarToast("⚖️ Balance de Sumas y Saldos recalculado.", "info");
        });
    }

    // Botón de Verificación del Ejercicio Contable
    if (dom.labBtnVerificarContabilidad) {
        dom.labBtnVerificarContabilidad.addEventListener("click", verificarEjercicioContable);
    }
    if (dom.labBtnCerrarFeedbackContab) {
        dom.labBtnCerrarFeedbackContab.addEventListener("click", () => {
            if (dom.labContabFeedbackBox) dom.labContabFeedbackBox.classList.add("hidden");
        });
    }

    // Cargar estado persistente y renderizado inicial
    cargarContabilidadStorage();
    cambiarSubvistaContabilidad("diario");
    renderizarLibroDiarioUI();
    sincronizarLibroMayor();
    sincronizarBalanceSumasYSaldos();
}

function cambiarSubvistaContabilidad(vista) {
    contabilidadEstado.subvistaActiva = vista;

    if (dom.labBtnSubtabDiario) dom.labBtnSubtabDiario.classList.toggle("is-active", vista === "diario");
    if (dom.labBtnSubtabMayor) dom.labBtnSubtabMayor.classList.toggle("is-active", vista === "mayor");
    if (dom.labBtnSubtabBalance) dom.labBtnSubtabBalance.classList.toggle("is-active", vista === "balance");
    if (dom.labBtnSubtabCalcContab) dom.labBtnSubtabCalcContab.classList.toggle("is-active", vista === "calc");

    if (dom.labContabSeccionDiario) dom.labContabSeccionDiario.classList.toggle("hidden", vista !== "diario");
    if (dom.labContabSeccionMayor) dom.labContabSeccionMayor.classList.toggle("hidden", vista !== "mayor");
    if (dom.labContabSeccionBalance) dom.labContabSeccionBalance.classList.toggle("hidden", vista !== "balance");
    if (dom.labContabSeccionCalc) dom.labContabSeccionCalc.classList.toggle("hidden", vista !== "calc");

    if (vista === "mayor") renderLibroMayorUI();
    if (vista === "balance") sincronizarBalanceSumasYSaldos();
}

function actualizarFechaAsiento(asientoIndex, valor) {
    if (!contabilidadEstado.asientos[asientoIndex]) return;
    contabilidadEstado.asientos[asientoIndex].fecha = String(valor).trim();
    guardarContabilidadStorage();
}

function actualizarDetalleAsiento(asientoIndex, valor) {
    if (!contabilidadEstado.asientos[asientoIndex]) return;
    contabilidadEstado.asientos[asientoIndex].detalle = String(valor);
    guardarContabilidadStorage();
}

function renderizarLibroDiarioUI() {
    if (!dom.labDiarioTableBody) return;
    setHTML(dom.labDiarioTableBody, "");

    contabilidadEstado.asientos.forEach((asiento, aIdx) => {
        // Fila de Encabezado del Asiento (📝 Asiento N° X | 📅 Fecha | Detalle | 🗑️)
        const headerRow = document.createElement("tr");
        headerRow.className = "lab-asiento-header-row";
        setHTML(headerRow, `
            <td colspan="4" class="lab-asiento-header-cell">
                <div class="lab-asiento-header-top">
                    <span class="lab-asiento-title-badge">📝 Asiento N° ${asiento.id || aIdx + 1}</span>
                    <div class="lab-asiento-fecha-box" title="Fecha del asiento contable">
                        <span class="lab-asiento-fecha-icon" aria-hidden="true">📅</span>
                        <input type="text" class="lab-diario-input lab-asiento-fecha-input" value="${escapeHtml(asiento.fecha || '')}" placeholder="dd/mm" title="Fecha del asiento (ej. 03/10)" data-study-input="actualizarFechaAsiento(${aIdx}, this.value)">
                    </div>
                </div>
                <div class="lab-asiento-header-bottom">
                    <input type="text" class="lab-diario-input lab-asiento-detalle-input" value="${escapeHtml(asiento.detalle || '')}" placeholder="Concepto / Detalle de la operación..." data-study-input="actualizarDetalleAsiento(${aIdx}, this.value)">
                </div>
            </td>
            <td class="lab-asiento-del-cell" style="text-align: center; vertical-align: middle;">
                <button type="button" class="button button--ghost button--xs button--danger-text lab-btn-del-asiento" title="Eliminar este asiento completo" data-study-click="eliminarAsientoContable(${aIdx})">🗑️</button>
            </td>
        `);
        dom.labDiarioTableBody.appendChild(headerRow);

        // Filas de Cuentas (Cuenta, Variación, Debe, Haber, Eliminar) - La fecha ya pertenece al asiento
        asiento.filas.forEach((fila, fIdx) => {
            const tr = document.createElement("tr");
            tr.className = "lab-asiento-row";

            const v = fila.variacion || "";

            setHTML(tr, `
                <td class="lab-cell-cuenta">
                    <input type="text" list="labListaCuentasContables" class="lab-diario-input lab-diario-input--cuenta" value="${escapeHtml(fila.cuenta || '')}" placeholder="Cuenta (ej. Caja, Deudores por Ventas...)" data-study-input="actualizarCeldaDiario(${aIdx}, ${fIdx}, 'cuenta', this.value)">
                </td>
                <td class="lab-cell-variacion">
                    <select class="lab-diario-input lab-diario-select-variacion" data-study-change="actualizarCeldaDiario(${aIdx}, ${fIdx}, 'variacion', this.value)">
                        <option value="" ${!v ? 'selected' : ''}>Variación</option>
                        <option value="A+" ${v === 'A+' ? 'selected' : ''}>A+ (Activo +)</option>
                        <option value="A-" ${v === 'A-' ? 'selected' : ''}>A- (Activo -)</option>
                        <option value="P+" ${v === 'P+' ? 'selected' : ''}>P+ (Pasivo +)</option>
                        <option value="P-" ${v === 'P-' ? 'selected' : ''}>P- (Pasivo -)</option>
                        <option value="PN+" ${v === 'PN+' ? 'selected' : ''}>PN+ (Patrimonio Neto +)</option>
                        <option value="PN-" ${v === 'PN-' ? 'selected' : ''}>PN- (Patrimonio Neto -)</option>
                        <option value="RP+" ${v === 'RP+' ? 'selected' : ''}>RP+ (Resultado Positivo)</option>
                        <option value="RN+" ${v === 'RN+' ? 'selected' : ''}>RN+ (Resultado Negativo)</option>
                        <option value="Reg. A+" ${v === 'Reg. A+' ? 'selected' : ''}>Reg. A+ (Reg. Activo +)</option>
                        <option value="Reg. A-" ${v === 'Reg. A-' ? 'selected' : ''}>Reg. A- (Reg. Activo -)</option>
                        <option value="Reg. P+" ${v === 'Reg. P+' ? 'selected' : ''}>Reg. P+ (Reg. Pasivo +)</option>
                        <option value="Reg. P-" ${v === 'Reg. P-' ? 'selected' : ''}>Reg. P- (Reg. Pasivo -)</option>
                    </select>
                </td>
                <td class="lab-cell-debe">
                    <input type="number" step="any" min="0" class="lab-diario-input lab-diario-input--number lab-diario-input--debe" value="${fila.debe !== '' && fila.debe !== undefined && fila.debe !== null ? fila.debe : ''}" placeholder="$ Debe" data-study-input="actualizarCeldaDiario(${aIdx}, ${fIdx}, 'debe', this.value)">
                </td>
                <td class="lab-cell-haber">
                    <input type="number" step="any" min="0" class="lab-diario-input lab-diario-input--number lab-diario-input--haber" value="${fila.haber !== '' && fila.haber !== undefined && fila.haber !== null ? fila.haber : ''}" placeholder="$ Haber" data-study-input="actualizarCeldaDiario(${aIdx}, ${fIdx}, 'haber', this.value)">
                </td>
                <td class="lab-cell-actions lab-asiento-actions-cell">
                    <button type="button" class="button button--ghost button--xs button--danger-text lab-btn-quitar-fila" title="Quitar línea de cuenta" data-study-click="eliminarFilaDeAsiento(${aIdx}, ${fIdx})">✕</button>
                </td>
            `);
            dom.labDiarioTableBody.appendChild(tr);
        });

        // Fila para agregar otra cuenta al asiento
        const addRow = document.createElement("tr");
        addRow.className = "lab-asiento-add-row";
        setHTML(addRow, `
            <td colspan="5" class="lab-asiento-add-cell">
                <button type="button" class="button button--ghost button--xs lab-btn-add-cuenta" data-study-click="agregarFilaAAsiento(${aIdx})">
                    ➕ Agregar Renglón al Asiento N° ${asiento.id || aIdx + 1}
                </button>
            </td>
        `);
        dom.labDiarioTableBody.appendChild(addRow);
    });

    recalcularTotalesDiario();
}

function agregarAsientoContable(fecha = null, detalle = null) {
    const nuevoId = contabilidadEstado.asientos.length + 1;
    const fechaDefecto = fecha || (nuevoId > 1 ? contabilidadEstado.asientos[nuevoId - 2]?.fecha || "10/03" : "01/03");

    contabilidadEstado.asientos.push({
        id: nuevoId,
        fecha: fechaDefecto,
        detalle: detalle || `Operación comercial N° ${nuevoId}`,
        filas: [
            { id: "f_" + Date.now() + "_1", cuenta: "", variacion: "", debe: "", haber: "" },
            { id: "f_" + Date.now() + "_2", cuenta: "", variacion: "", debe: "", haber: "" }
        ]
    });

    renderizarLibroDiarioUI();
    guardarContabilidadStorage();
    mostrarToast(`➕ Asiento N° ${nuevoId} creado.`, "info");
}

function agregarFilaAAsiento(asientoIndex, cuenta = "", debe = "", haber = "", variacion = "") {
    const asiento = contabilidadEstado.asientos[asientoIndex];
    if (!asiento) return;

    asiento.filas.push({
        id: "f_" + Date.now(),
        cuenta: cuenta,
        variacion: variacion || "",
        debe: debe !== "" ? (Number(debe) || 0) : "",
        haber: haber !== "" ? (Number(haber) || 0) : ""
    });

    renderizarLibroDiarioUI();
    guardarContabilidadStorage();
}

function eliminarFilaDeAsiento(asientoIndex, filaIndex) {
    const asiento = contabilidadEstado.asientos[asientoIndex];
    if (!asiento) return;

    if (asiento.filas.length <= 1) {
        mostrarToast("⚠️ El asiento debe tener al menos una línea.", "aviso");
        return;
    }

    asiento.filas.splice(filaIndex, 1);
    renderizarLibroDiarioUI();
    guardarContabilidadStorage();
}

function eliminarAsientoContable(asientoIndex) {
    if (contabilidadEstado.asientos.length <= 1) {
        mostrarToast("⚠️ Debe haber al menos un asiento en el Libro Diario.", "aviso");
        return;
    }

    contabilidadEstado.asientos.splice(asientoIndex, 1);
    contabilidadEstado.asientos.forEach((a, i) => { a.id = i + 1; });
    renderizarLibroDiarioUI();
    sincronizarLibroMayor();
    sincronizarBalanceSumasYSaldos();
    guardarContabilidadStorage();
}

function actualizarCeldaDiario(asientoIndex, filaIndex, campo, valor) {
    const asiento = contabilidadEstado.asientos[asientoIndex];
    if (!asiento || !asiento.filas[filaIndex]) return;

    if (campo === "debe" || campo === "haber") {
        asiento.filas[filaIndex][campo] = valor === "" ? "" : Math.max(0, parseFloat(valor) || 0);
    } else {
        asiento.filas[filaIndex][campo] = String(valor);
    }

    recalcularTotalesDiario();
    guardarContabilidadStorage();
}

function recalcularTotalesDiario() {
    let totalDebe = 0;
    let totalHaber = 0;

    contabilidadEstado.asientos.forEach(a => {
        a.filas.forEach(f => {
            totalDebe += (Number(f.debe) || 0);
            totalHaber += (Number(f.haber) || 0);
        });
    });

    const diff = Math.abs(totalDebe - totalHaber);
    const balanceado = diff < 0.01;

    if (dom.labDiarioTotalDebe) dom.labDiarioTotalDebe.textContent = `$${totalDebe.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    if (dom.labDiarioTotalHaber) dom.labDiarioTotalHaber.textContent = `$${totalHaber.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

    if (dom.labDiarioPartidaDobleBar) {
        dom.labDiarioPartidaDobleBar.classList.toggle("is-descuadrada", !balanceado);
    }

    if (dom.labDiarioStatusText) {
        dom.labDiarioStatusText.textContent = balanceado
            ? "Partida Doble Cuadrada: Total Debe y Total Haber coinciden."
            : "Partida Doble Descuadrada: El Debe y el Haber no son iguales.";
    }

    if (dom.labDiarioDiffText) {
        dom.labDiarioDiffText.textContent = balanceado
            ? "Diferencia: $0.00"
            : `Diferencia: $${diff.toLocaleString('es-AR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    }
}

function sincronizarLibroMayor() {
    const cuentasMap = {};

    contabilidadEstado.asientos.forEach(a => {
        a.filas.forEach(f => {
            const nom = (f.cuenta || "").trim();
            if (!nom) return;

            if (!cuentasMap[nom]) {
                cuentasMap[nom] = {
                    debe: [],
                    haber: [],
                    totalDebe: 0,
                    totalHaber: 0,
                    saldo: 0,
                    tipoSaldo: "deudor"
                };
            }

            const d = Number(f.debe) || 0;
            const h = Number(f.haber) || 0;

            if (d > 0) cuentasMap[nom].debe.push(d);
            if (h > 0) cuentasMap[nom].haber.push(h);
        });
    });

    // Calcular saldos
    Object.keys(cuentasMap).forEach(k => {
        const c = cuentasMap[k];
        c.totalDebe = c.debe.reduce((acc, v) => acc + v, 0);
        c.totalHaber = c.haber.reduce((acc, v) => acc + v, 0);

        if (c.totalDebe >= c.totalHaber) {
            c.saldo = c.totalDebe - c.totalHaber;
            c.tipoSaldo = "deudor";
        } else {
            c.saldo = c.totalHaber - c.totalDebe;
            c.tipoSaldo = "acreedor";
        }
    });

    contabilidadEstado.mayores = cuentasMap;
    renderLibroMayorUI();
    sincronizarBalanceSumasYSaldos();
}

function renderLibroMayorUI() {
    if (!dom.labMayorCuentasGrid) return;
    setHTML(dom.labMayorCuentasGrid, "");

    const cuentas = Object.keys(contabilidadEstado.mayores);
    if (cuentas.length === 0) {
        setHTML(dom.labMayorCuentasGrid, `
            <div style="grid-column: 1 / -1; padding: 2rem; text-align: center; color: var(--color-text-muted);">
                <p>No hay cuentas registradas aún en el Libro Diario.</p>
                <p style="font-size: 0.8rem;">Escribí las cuentas e importes en el Libro Diario y tocá 'Pasar a Libro Mayor'.</p>
            </div>
        `);
        return;
    }

    cuentas.forEach(nom => {
        const c = contabilidadEstado.mayores[nom];
        const card = document.createElement("div");
        card.className = "lab-cuenta-t-card";

        const filasMax = Math.max(c.debe.length, c.haber.length, 1);
        let debeItems = "";
        let haberItems = "";

        for (let i = 0; i < filasMax; i++) {
            const dVal = c.debe[i] !== undefined ? `$${c.debe[i].toLocaleString('es-AR')}` : "";
            const hVal = c.haber[i] !== undefined ? `$${c.haber[i].toLocaleString('es-AR')}` : "";
            debeItems += `<span>${dVal}</span>`;
            haberItems += `<span>${hVal}</span>`;
        }

        const pillClass = c.tipoSaldo === "deudor" ? "lab-t-saldo-pill--deudor" : "lab-t-saldo-pill--acreedor";
        const saldoTexto = `Saldo ${c.tipoSaldo === 'deudor' ? 'Deudor' : 'Acreedor'}: $${c.saldo.toLocaleString('es-AR', { minimumFractionDigits: 2 })}`;

        setHTML(card, `
            <div class="lab-t-header">${nom}</div>
            <div class="lab-t-body">
                <div class="lab-t-col lab-t-col--debe">
                    <span class="lab-t-col-header">DEBE</span>
                    ${debeItems}
                </div>
                <div class="lab-t-col lab-t-col--haber">
                    <span class="lab-t-col-header">HABER</span>
                    ${haberItems}
                </div>
            </div>
            <div class="lab-t-footer">
                <div>
                    <strong>Σ D:</strong> $${c.totalDebe.toLocaleString('es-AR')} | 
                    <strong>Σ H:</strong> $${c.totalHaber.toLocaleString('es-AR')}
                </div>
                <span class="lab-t-saldo-pill ${pillClass}">${saldoTexto}</span>
            </div>
        `);

        dom.labMayorCuentasGrid.appendChild(card);
    });
}

function sincronizarBalanceSumasYSaldos() {
    if (!dom.labBalanceTableBody) return;
    setHTML(dom.labBalanceTableBody, "");

    const cuentas = Object.keys(contabilidadEstado.mayores);
    let totSumDebe = 0;
    let totSumHaber = 0;
    let totSalDeudor = 0;
    let totSalAcreedor = 0;

    if (cuentas.length === 0) {
        setHTML(dom.labBalanceTableBody, `
            <tr>
                <td colspan="5" style="text-align: center; color: var(--color-text-muted); padding: 1.5rem;">
                    Sin cuentas registradas aún. Completá los asientos en el Libro Diario y tocalos en 'Pasar a Libro Mayor' para balancear.
                </td>
            </tr>
        `);
        if (dom.labBalTotalSumasDebe) dom.labBalTotalSumasDebe.textContent = "$0.00";
        if (dom.labBalTotalSumasHaber) dom.labBalTotalSumasHaber.textContent = "$0.00";
        if (dom.labBalTotalSaldoDeudor) dom.labBalTotalSaldoDeudor.textContent = "$0.00";
        if (dom.labBalTotalSaldoAcreedor) dom.labBalTotalSaldoAcreedor.textContent = "$0.00";
        if (dom.labBalanceVerificationText) {
            dom.labBalanceVerificationText.textContent = "Pendiente de completar el Libro Diario y Mayor.";
        }
        return;
    }

    cuentas.forEach(nom => {
        const c = contabilidadEstado.mayores[nom];
        totSumDebe += c.totalDebe;
        totSumHaber += c.totalHaber;

        const salDeudor = c.tipoSaldo === "deudor" ? c.saldo : 0;
        const salAcreedor = c.tipoSaldo === "acreedor" ? c.saldo : 0;

        totSalDeudor += salDeudor;
        totSalAcreedor += salAcreedor;

        const tr = document.createElement("tr");
        setHTML(tr, `
            <td><strong>${nom}</strong></td>
            <td style="text-align: right; font-family: monospace;">$${c.totalDebe.toLocaleString('es-AR', { minimumFractionDigits: 2 })}</td>
            <td style="text-align: right; font-family: monospace;">$${c.totalHaber.toLocaleString('es-AR', { minimumFractionDigits: 2 })}</td>
            <td style="text-align: right; font-family: monospace; color: #34d399;">$${salDeudor ? salDeudor.toLocaleString('es-AR', { minimumFractionDigits: 2 }) : '-'}</td>
            <td style="text-align: right; font-family: monospace; color: #38bdf8;">$${salAcreedor ? salAcreedor.toLocaleString('es-AR', { minimumFractionDigits: 2 }) : '-'}</td>
        `);
        dom.labBalanceTableBody.appendChild(tr);
    });

    if (dom.labBalTotalSumasDebe) dom.labBalTotalSumasDebe.textContent = `$${totSumDebe.toLocaleString('es-AR', { minimumFractionDigits: 2 })}`;
    if (dom.labBalTotalSumasHaber) dom.labBalTotalSumasHaber.textContent = `$${totSumHaber.toLocaleString('es-AR', { minimumFractionDigits: 2 })}`;
    if (dom.labBalTotalSaldoDeudor) dom.labBalTotalSaldoDeudor.textContent = `$${totSalDeudor.toLocaleString('es-AR', { minimumFractionDigits: 2 })}`;
    if (dom.labBalTotalSaldoAcreedor) dom.labBalTotalSaldoAcreedor.textContent = `$${totSalAcreedor.toLocaleString('es-AR', { minimumFractionDigits: 2 })}`;

    const sumasCuadran = Math.abs(totSumDebe - totSumHaber) < 0.01;
    const saldosCuadran = Math.abs(totSalDeudor - totSalAcreedor) < 0.01;
    const balanceado = sumasCuadran && saldosCuadran;

    if (dom.labBalanceVerificationText) {
        dom.labBalanceVerificationText.textContent = balanceado
            ? "Sumas Iguales y Saldos Cuadrados (Partida Doble Perfecta)"
            : `Descuadre detectado: Sumas diff $${Math.abs(totSumDebe - totSumHaber).toFixed(2)}, Saldos diff $${Math.abs(totSalDeudor - totSalAcreedor).toFixed(2)}`;
    }
}

function verificarEjercicioContable() {
    recalcularTotalesDiario();
    sincronizarLibroMayor();
    sincronizarBalanceSumasYSaldos();

    let totalDebe = 0;
    let totalHaber = 0;
    let asientosDescuadrados = [];

    contabilidadEstado.asientos.forEach((a, idx) => {
        let d = 0;
        let h = 0;
        a.filas.forEach(f => {
            d += (Number(f.debe) || 0);
            h += (Number(f.haber) || 0);
        });
        totalDebe += d;
        totalHaber += h;

        if (Math.abs(d - h) > 0.01) {
            asientosDescuadrados.push(`Asiento N° ${a.id || idx + 1} (Debe: $${d} vs Haber: $${h})`);
        }
    });

    if (!dom.labContabFeedbackBox) return;
    dom.labContabFeedbackBox.classList.remove("hidden");

    if (asientosDescuadrados.length > 0) {
        dom.labContabFeedbackBox.className = "lab-contab-feedback-box is-error";
        if (dom.labContabFeedbackIcon) dom.labContabFeedbackIcon.textContent = "⚠️";
        if (dom.labContabFeedbackTitle) dom.labContabFeedbackTitle.textContent = "Partida Doble Descuadrada";
        if (dom.labContabFeedbackMsg) {
            setHTML(dom.labContabFeedbackMsg, `
                Tenés asientos donde la suma del Debe no es igual a la suma del Haber:<br>
                <strong>${asientosDescuadrados.join("<br>")}</strong>.<br>
                Revisá que todo débito tenga su contrapartida acreditada por el mismo valor.
            `);
        }
        mostrarToast("⚠️ Hay asientos desbalanceados en el Libro Diario.", "aviso");
        return;
    }

    if (totalDebe === 0) {
        dom.labContabFeedbackBox.className = "lab-contab-feedback-box is-error";
        if (dom.labContabFeedbackIcon) dom.labContabFeedbackIcon.textContent = "📝";
        if (dom.labContabFeedbackTitle) dom.labContabFeedbackTitle.textContent = "Libro Diario Vacío";
        if (dom.labContabFeedbackMsg) dom.labContabFeedbackMsg.textContent = "Completá los importes y nombres de cuenta para poder verificar el ejercicio.";
        return;
    }

    // Si todo cuadra
    dom.labContabFeedbackBox.className = "lab-contab-feedback-box";
    if (dom.labContabFeedbackIcon) dom.labContabFeedbackIcon.textContent = "🎉";
    if (dom.labContabFeedbackTitle) dom.labContabFeedbackTitle.textContent = "¡Registración Contable Verificada con Éxito!";
    if (dom.labContabFeedbackMsg) {
        setHTML(dom.labContabFeedbackMsg, `
            Todos los asientos cumplen estrictamente con la <strong>Partida Doble</strong>.<br>
            Total contabilizado: <strong>$${totalDebe.toLocaleString('es-AR', { minimumFractionDigits: 2 })}</strong>.<br>
            El Libro Mayor y el Balance de Sumas y Saldos se encuentran 100% equilibrados. ¡Ganaste +100 XP contables!
        `);
    }

    laboratorioEstado.xpTotal = (laboratorioEstado.xpTotal || 0) + 100;
    if (dom.labXpDisplay) dom.labXpDisplay.textContent = `${laboratorioEstado.xpTotal} XP`;
    mostrarToast("🎉 ¡Excelente trabajo contable! Todos los libros cuadran a la perfección.", "exito");
    if (typeof dispararVibracion === "function") dispararVibracion("victoria");
}

function abrirModalPromptLab() {
    if (!dom.labPromptModal) {
        generarEjercicioLaboratorio(true);
        return;
    }
    if (typeof sincronizarSelectoresDificultadLab === "function") sincronizarSelectoresDificultadLab();
    const tema = laboratorioEstado.temaSeleccionado || "descriptiva";
    if (dom.labPromptModalTopicBadge) dom.labPromptModalTopicBadge.textContent = obtenerEtiquetaTema(tema);
    if (dom.labPromptModalFileBadge) {
        if (laboratorioEstado.pdfNombre) {
            dom.labPromptModalFileBadge.textContent = `📁 ${laboratorioEstado.pdfNombre}`;
            dom.labPromptModalFileBadge.className = "badge badge--success";
        } else {
            dom.labPromptModalFileBadge.textContent = "📄 Sin archivo cargado";
            dom.labPromptModalFileBadge.className = "badge badge--ghost";
        }
    }
    if (dom.labPromptOrderInput) {
        dom.labPromptOrderInput.value = laboratorioEstado.instruccionUsuario || "";
    }
    actualizarQuickChipsUI(tema);

    if (typeof dom.labPromptModal.showModal === "function") {
        try { dom.labPromptModal.showModal(); } catch { dom.labPromptModal.setAttribute("open", ""); }
    } else {
        dom.labPromptModal.setAttribute("open", "");
    }
    if (dom.labPromptOrderInput) dom.labPromptOrderInput.focus();
}

function cerrarModalPromptLab() {
    if (dom.labPromptModal) {
        if (typeof dom.labPromptModal.close === "function") {
            try { dom.labPromptModal.close(); } catch { dom.labPromptModal.removeAttribute("open"); }
        } else {
            dom.labPromptModal.removeAttribute("open");
        }
    }
}

