// Generadores Procedimentales Temáticos con Parámetros Aleatorios:

function generarEjercicioDescriptivaProcedural(orden = "") {
    const contextos = [
        {
            sector: "Auditoría Logística y Tiempos de Entrega",
            variable: "Tiempos de entrega (minutos)",
            x: [18, 22, 25, 30, 35],
            f: [6, 14, 18, 8, 4]
        },
        {
            sector: "Control de Calidad en Planta Metalúrgica",
            variable: "Espesor de láminas de acero (mm)",
            x: [10, 12, 15, 18, 20],
            f: [5, 15, 20, 7, 3]
        },
        {
            sector: "Rendimiento Académico Universitario",
            variable: "Calificaciones de examen parcial",
            x: [4, 6, 7, 8, 10],
            f: [8, 16, 22, 10, 4]
        },
        {
            sector: "Ventas Diarias en Locales Comerciales",
            variable: "Cantidad de operaciones registradas",
            x: [40, 50, 60, 70, 80],
            f: [7, 12, 21, 15, 5]
        },
        {
            sector: "Consumo Eléctrico de Equipos Industriales",
            variable: "Potencia media demandada (kW)",
            x: [15, 20, 25, 30, 40],
            f: [9, 18, 24, 12, 5]
        }
    ];

    const ctx = contextos[Math.floor(Math.random() * contextos.length)];
    const delta = Math.floor(Math.random() * 5) - 2; // variabilidad -2..+2
    const f = ctx.f.map(val => Math.max(2, val + delta));
    const x = ctx.x;

    let N = 0;
    let sumXiFi = 0;
    let sumXi2Fi = 0;
    for (let i = 0; i < x.length; i++) {
        N += f[i];
        sumXiFi += x[i] * f[i];
        sumXi2Fi += x[i] * x[i] * f[i];
    }
    const media = Number((sumXiFi / N).toFixed(2));
    const varianza = Number(((sumXi2Fi - (N * media * media)) / (N - 1)).toFixed(2));
    const desvio = Number(Math.sqrt(varianza).toFixed(2));
    const cv = Number(((desvio / media) * 100).toFixed(2));

    // Mediana
    let acum = 0;
    let mediana = x[0];
    for (let i = 0; i < x.length; i++) {
        acum += f[i];
        if (acum >= N / 2) {
            mediana = x[i];
            break;
        }
    }

    const enunciado = `Se recolectó una muestra de ${ctx.sector.toLowerCase()} para evaluar la distribución de ${ctx.variable.toLowerCase()}:`;
    const datosStr = x.map((val, idx) => `• Valor xi = ${val} : Frecuencia fi = ${f[idx]}`).join("\n");

    return {
        id: "desc_" + Date.now(),
        tema: "descriptiva",
        origen: "modelo",
        titulo: ctx.sector,
        dificultad: laboratorioEstado.dificultad || "Intermedia",
        enunciado: enunciado,
        datos: datosStr,
        datos_tipo: "tabla",
        narrativa: `${enunciado}\n\n${datosStr}`,
        preguntas: [
            {
                letra: "a",
                texto: "¿Cuál es el tamaño total de la muestra analizada (N = Σ fi)?",
                esperado: N,
                tolerancia: 0,
                pista: "Sumá todas las frecuencias absolutas fi: " + f.join(" + ") + " = " + N,
                explicacion: `El tamaño total de la muestra se obtiene de la suma marginal: N = Σ fi = ${N}.`
            },
            {
                letra: "b",
                texto: "Calculá la Media Aritmética o Promedio muestral (x̄):",
                esperado: media,
                tolerancia: 0.1,
                pista: `Multiplicá cada xi por su fi, sumalos y dividilos por N: x̄ = Σ(xi · fi) / N = ${sumXiFi} / ${N}`,
                explicacion: `Media x̄ = Σ(xi·fi)/N = ${sumXiFi} / ${N} = ${media}. Podés corroborarlo en la tarjeta "Promedio" del panel inferior.`
            },
            {
                letra: "c",
                texto: "Calculá el Desvío Estándar Muestral (s):",
                esperado: desvio,
                tolerancia: 0.15,
                pista: "El desvío es la raíz cuadrada de la varianza muestral: s = √(s²). Podés copiarlo desde la calculadora de la mesa.",
                explicacion: `Varianza s² = [Σ(xi²·fi) - N·x̄²] / (N - 1) ≈ ${varianza}. Por lo tanto, el desvío es s = √${varianza} ≈ ${desvio}.`
            },
            {
                letra: "d",
                texto: "¿Cuál es el Coeficiente de Variación porcentual (CV%)?",
                esperado: cv,
                tolerancia: 0.5,
                pista: "Fórmula del CV: (s / x̄) * 100. Ingresá el valor numérico en porcentaje (ej: 18.5).",
                explicacion: `CV = (s / x̄) * 100 = (${desvio} / ${media}) * 100 = ${cv}%. Indica la dispersión relativa de la distribución.`
            },
            {
                letra: "e",
                texto: "Determina el valor de la Mediana (Me) de esta serie:",
                esperado: mediana,
                tolerancia: 0.1,
                pista: `Buscá en la columna acumulada Fi el primer valor que alcance o supere la mitad de la muestra (N/2 = ${(N / 2).toFixed(1)}).`,
                explicacion: `La posición central N/2 = ${N / 2} queda comprendida en la clase con xi = ${mediana}. Por lo tanto, Me = ${mediana}.`
            }
        ]
    };
}

function generarEjercicioBayesProcedural(orden = "") {
    const ordenLower = (orden || "").toLowerCase();
    const casos = [
        {
            titulo: "Control Biométrico y Detección de Amenazas",
            sujeto: "pasajeros analizados",
            total: 10000,
            pA: 0.02,
            sens: 0.95,
            esp: 0.96,
            contexto: "Un sistema biométrico de seguridad aeroportuaria analiza a una población de n = 10.000 pasajeros.\nLa prevalencia de personas en lista de búsqueda es del 2%: P(Buscado) = 0.02 (200 de 10.000).\nCuando una persona está en búsqueda, el sensor dispara alarma con probabilidad del 95%: P(Alarma | Buscado) = 0.95.\nCuando una persona es un ciudadano normal (9.800 pasajeros), el sensor genera una falsa alarma el 4% de las veces: P(Alarma | Normal) = 0.04."
        },
        {
            titulo: "Diagnóstico Clínico y Pruebas Serológicas",
            sujeto: "pacientes testeados",
            total: 10000,
            pA: 0.03,
            sens: 0.92,
            esp: 0.95,
            contexto: "Un laboratorio médico evalúa una prueba rápida para detectar una patología que afecta al 3% de la población: P(Enfermo) = 0.03 (300 de 10.000 pacientes).\nLa sensibilidad del test ante un portador es del 92%: P(+ | Enfermo) = 0.92.\nEn personas sanas (9.700 pacientes), la tasa de falsos positivos es del 5%: P(+ | Sano) = 0.05."
        },
        {
            titulo: "Detección de Fraude en Transacciones Financieras",
            sujeto: "transacciones bancarias",
            total: 20000,
            pA: 0.015,
            sens: 0.94,
            esp: 0.97,
            contexto: "Un modelo de machine learning detecta transferencias fraudulentas en un banco con 20.000 operaciones diarias.\nLa tasa basal de fraude es del 1.5%: P(Fraude) = 0.015 (300 de 20.000).\nSi una transacción es fraudulenta, el algoritmo la marca como sospechosa el 94% de las veces: P(Alerta | Fraude) = 0.94.\nEn operaciones legítimas (19.700 transacciones), la tasa de falsa alarma es del 3%: P(Alerta | Legítima) = 0.03."
        }
    ];

    const c = casos[Math.floor(Math.random() * casos.length)];
    const enf = Math.round(c.total * c.pA);
    const sanos = c.total - enf;
    const fA = Number((1 - c.esp).toFixed(3));
    const VP = Math.round(enf * c.sens);
    const FP = Math.round(sanos * fA);
    const totalPositivos = VP + FP;
    const probTotalPos = Number((totalPositivos / c.total).toFixed(4));
    const posterior = Number((VP / totalPositivos).toFixed(4));

    const enunciado = `Un sistema de análisis de ${c.sujeto} evalúa una población de N = ${c.total.toLocaleString()} casos bajo los siguientes antecedentes de fiabilidad:`;
    const datosStr = `Prevalencia basal P(A) = ${(c.pA * 100).toFixed(1)}%\nSensibilidad del sensor P(Alerta | A) = ${(c.sens * 100).toFixed(1)}%\nTasa de Falsos Positivos P(Alerta | Normal) = ${(fA * 100).toFixed(1)}%`;

    return {
        id: "bayes_" + Date.now(),
        tema: "bayes",
        origen: "modelo",
        titulo: c.titulo,
        dificultad: laboratorioEstado.dificultad || "Intermedia",
        enunciado: enunciado,
        datos: datosStr,
        datos_tipo: "parametros",
        narrativa: `${enunciado}\n\n${datosStr}`,
        preguntas: [
            {
                letra: "a",
                texto: "¿Cuántos casos positivos verdaderos se detectarán con éxito (Verdaderos Positivos VP)?",
                esperado: VP,
                tolerancia: 1,
                pista: `VP = Total afectados * Sensibilidad = ${enf} * ${c.sens}`,
                explicacion: `VP = ${enf} * ${c.sens} = ${VP}. Son las detecciones correctas.`
            },
            {
                letra: "b",
                texto: "¿Cuántos casos sanos/normales activarán una falsa alarma (Falsos Positivos FP)?",
                esperado: FP,
                tolerancia: 2,
                pista: `FP = Total normales * Tasa falsa alarma = ${sanos} * ${fA}`,
                explicacion: `FP = ${sanos} * ${fA} = ${FP} casos clasificados erróneamente.`
            },
            {
                letra: "c",
                texto: "Calculá la probabilidad marginal total de activación: P(Positivo):",
                esperado: probTotalPos,
                tolerancia: 0.005,
                pista: `P(Positivo) = (VP + FP) / Total = (${VP} + ${FP}) / ${c.total}`,
                explicacion: `P(Positivo) = ${totalPositivos} / ${c.total} = ${probTotalPos}.`
            },
            {
                letra: "d",
                texto: "Aplicando el Teorema de Bayes, ¿cuál es la probabilidad real de que un caso positivo sea realmente afectado: P(Afectado | Positivo)?",
                esperado: posterior,
                tolerancia: 0.01,
                pista: `Teorema de Bayes: P(A | +) = VP / (VP + FP) = ${VP} / ${totalPositivos}`,
                explicacion: `P(A | +) = ${VP} / ${totalPositivos} ≈ ${posterior} (${(posterior * 100).toFixed(1)}%). Esta es la conocida paradoja del falso positivo.`
            }
        ]
    };
}

function generarEjercicioNormalProcedural(orden = "") {
    const ordenLower = (orden || "").toLowerCase();
    
    // Casos reales inspirados en la Guía de Trabajos Prácticos de Estadística Empresarial I (TP4 y TP5)
    const modelos = [
        {
            id: "cafe",
            titulo: "Distribución Normal: Peso de Bolsas de Café (TP4 Ejercicio 1)",
            mu: 1000,
            sigma: 15,
            xCrit: 990,
            xInf: 985,
            xSup: 1015,
            narrativa: "El peso en gramos de las bolsas de café recibidas en una empaquetadora sigue una distribución normal con media μ = 1000 g y desvío estándar σ = 15 g: X ~ N(1000, 15²).\nSe desea analizar el porcentaje de bolsas que quedan por debajo de la cota mínima de 990 g y el rango óptimo bilateral.\n\nUtilizá la suite 'Calculadora de Probabilidad' con la Campana de Gauss para verificar áreas, estandarización y cuantiles:"
        },
        {
            id: "gaseosa",
            titulo: "Distribución Normal: Control de Volumen de Latas de Gaseosa (TP4)",
            mu: 354,
            sigma: 8,
            xCrit: 340,
            xInf: 345,
            xSup: 365,
            narrativa: "Una línea automática embotelladora llena latas de gaseosa con una media de μ = 354 ml y un desvío estándar de σ = 8 ml: X ~ N(354, 8²).\nPor normas de bromatología, cualquier lata con un contenido menor a 340 ml se considera no conforme y es retirada del lote.\n\nUtilizá la curva continua interactiva para calcular probabilidades y cotas críticas:"
        },
        {
            id: "cemento",
            titulo: "Suma de Variables Normales: Carga de Camión de Materiales (TP5 Ejercicio 1)",
            mu: 10000,
            sigma: 53.385,
            xCrit: 10200,
            xInf: 9900,
            xSup: 10100,
            narrativa: "Un camión de carga transporta 100 bolsas de cemento y 200 de cal. Por el teorema de suma de variables aleatorias independientes, el peso total W se distribuye normalmente con media μ = 10.000 kg y desvío estándar σ = 53,385 kg: W ~ N(10000, 53.385²).\nLa capacidad máxima autorizada por la báscula de control es de 10.200 kg.\n\nDeterminá las probabilidades de sobrecarga y estandarización Z:"
        }
    ];

    let m = modelos[0];
    if (ordenLower.includes("gaseosa") || ordenLower.includes("lata") || ordenLower.includes("botella")) m = modelos[1];
    else if (ordenLower.includes("cemento") || ordenLower.includes("camion") || ordenLower.includes("suma")) m = modelos[2];
    else if (ordenLower.includes("cafe")) m = modelos[0];
    else m = modelos[Math.floor(Math.random() * modelos.length)];

    const z1 = Number(((m.xCrit - m.mu) / m.sigma).toFixed(2));
    const p1 = Number(labNormalCDF(m.xCrit, m.mu, m.sigma).toFixed(4));
    const pMayor = Number((1 - labNormalCDF(m.xCrit, m.mu, m.sigma)).toFixed(4));
    const pIntervalo = Number((labNormalCDF(m.xSup, m.mu, m.sigma) - labNormalCDF(m.xInf, m.mu, m.sigma)).toFixed(4));

    const enunciado = `El proceso bajo estudio de ${m.titulo.toLowerCase()} se modela rigurosamente como una variable continua X ~ N(μ, σ²):`;
    const datosStr = `Media del proceso (μ) = ${m.mu}\nDesvío estándar (σ) = ${m.sigma}\nValor crítico de análisis (X) = ${m.xCrit}`;

    return {
        id: "norm_" + Date.now(),
        materia: "estadistica",
        tema: "normal",
        origen: "modelo",
        titulo: m.titulo,
        dificultad: laboratorioEstado.dificultad || "Intermedia",
        enunciado: enunciado,
        datos: datosStr,
        datos_tipo: "parametros",
        narrativa: `${m.narrativa}\n\n${datosStr}`,
        preguntas: [
            {
                letra: "a",
                texto: `Estandarizá el valor crítico X = ${m.xCrit} calculando su puntaje Z = (X - μ) / σ:`,
                esperado: z1,
                tolerancia: 0.05,
                pista: `Z = (${m.xCrit} - ${m.mu}) / ${m.sigma}`,
                explicacion: `Z = (${m.xCrit} - ${m.mu}) / ${m.sigma} = ${z1}.`
            },
            {
                letra: "b",
                texto: `¿Cuál es la probabilidad de que una unidad seleccionada al azar pese/mida a lo sumo ${m.xCrit}: P(X ≤ ${m.xCrit})?`,
                esperado: p1,
                tolerancia: 0.005,
                pista: `Ingresá en la Calculadora: μ=${m.mu}, σ=${m.sigma}, x=${m.xCrit} con cola izquierda P(X ≤ x).`,
                explicacion: `P(X ≤ ${m.xCrit}) = P(Z ≤ ${z1}) ≈ ${p1} (${(p1 * 100).toFixed(2)}%).`
            },
            {
                letra: "c",
                texto: `¿Cuál es la probabilidad de superar dicho valor: P(X > ${m.xCrit})?`,
                esperado: pMayor,
                tolerancia: 0.005,
                pista: `Regla del complemento: 1 - P(X ≤ ${m.xCrit}) o cola derecha en la calculadora de probabilidad.`,
                explicacion: `P(X > ${m.xCrit}) = 1 - ${p1} = ${pMayor} (${(pMayor * 100).toFixed(2)}%).`
            },
            {
                letra: "d",
                texto: `¿Cuál es la probabilidad de que una unidad se ubique en el intervalo entre ${m.xInf} y ${m.xSup}: P(${m.xInf} ≤ X ≤ ${m.xSup})?`,
                esperado: pIntervalo,
                tolerancia: 0.015,
                pista: `P(${m.xInf} ≤ X ≤ ${m.xSup}) = F(${m.xSup}) - F(${m.xInf}). Podés usar la cola bilateral en la calculadora.`,
                explicacion: `P(${m.xInf} ≤ X ≤ ${m.xSup}) ≈ ${pIntervalo} (${(pIntervalo * 100).toFixed(2)}%).`
            }
        ]
    };
}

function generarEjercicioDiscretasProcedural(orden = "") {
    const ordenLower = (orden || "").toLowerCase();
    const temas = laboratorioEstado.temasSeleccionados || [];

    const prefiereHiper = ordenLower.includes("hiper") || ordenLower.includes("hyper") || ordenLower.includes("postulante") || temas.includes("hipergeometrica");
    const prefierePoisson = ordenLower.includes("poisson") || ordenLower.includes("llamada") || ordenLower.includes("minuto") || ordenLower.includes("tasa");

    if (prefiereHiper) {
        // Caso TP3 Ejercicio 13 de la Guía: Postulantes para puesto en empresa
        // N = 14 postulantes, K = 5 con experiencia, se eligen n = 7
        const N = 14;
        const K = 5;
        const n = 7;
        const k = 3;
        const media = Number(((n * K) / N).toFixed(2)); // 2.50
        const pExacta = Number(labHyperPMF(N, K, n, k).toFixed(5)); // ~0.36713
        let pAcum2 = 0;
        for (let i = 0; i <= 2; i++) pAcum2 += labHyperPMF(N, K, n, i);
        pAcum2 = Number(pAcum2.toFixed(4)); // ~0.5000
        let pMin4 = 0;
        for (let i = 4; i <= Math.min(n, K); i++) pMin4 += labHyperPMF(N, K, n, i);
        pMin4 = Number(pMin4.toFixed(4)); // ~0.13287

        const enunciado = "Entre los 14 postulantes que se presentaron para cubrir un puesto en una empresa, 5 acreditan experiencia previa en tareas similares. El director de RRHH decide elegir por sorteo sin reposición a 7 postulantes para entrevistar en primer término:";
        const datosStr = `Tamaño de la población (N) = ${N}\nCantidad de éxitos en la población (K) = ${K}\nTamaño de muestra elegida sin reposición (n) = ${n}`;

        return {
            id: "hyper_" + Date.now(),
            materia: "estadistica",
            tema: "hipergeometrica",
            origen: "modelo",
            titulo: "Distribución Hipergeométrica: Selección de Postulantes (TP3 Ejercicio 13)",
            dificultad: "Intermedia",
            enunciado: enunciado,
            datos: datosStr,
            datos_tipo: "parametros",
            narrativa: `${enunciado}\n\n${datosStr}`,
            preguntas: [
                {
                    letra: "a",
                    texto: `Calculá el número esperado de postulantes con experiencia en el grupo: E(X) = n · K / N:`,
                    esperado: media,
                    tolerancia: 0.1,
                    pista: `E(X) = (7 * 5) / 14 = 2.5 postulantes.`,
                    explicacion: `E(X) = n · (K / N) = 7 · (5 / 14) = ${media} postulantes con experiencia previa.`
                },
                {
                    letra: "b",
                    texto: `¿Cuál es la probabilidad de que haya exactamente 3 postulantes con experiencia: P(X = 3)?`,
                    esperado: pExacta,
                    tolerancia: 0.008,
                    pista: `Fórmula Hipergeométrica: [C(5,3) · C(9,4)] / C(14,7). Utilizá la pestaña Hipergeométrica en la mesa de trabajo.`,
                    explicacion: `P(X = 3) = [C(5,3) · C(9,4)] / C(14,7) = (10 · 126) / 3432 ≈ 0.36713 (36.71%).`
                },
                {
                    letra: "c",
                    texto: `¿Cuál es la probabilidad de que a lo sumo 2 postulantes tengan experiencia previa: P(X ≤ 2)?`,
                    esperado: pAcum2,
                    tolerancia: 0.015,
                    pista: `P(X ≤ 2) = P(0) + P(1) + P(2). Seleccioná cola izquierda acumulada P(X ≤ x) con x=2.`,
                    explicacion: `P(X ≤ 2) = P(X=0) + P(X=1) + P(X=2) = 0.0105 + 0.1538 + 0.3357 ≈ 0.5000 (50%).`
                },
                {
                    letra: "d",
                    texto: `¿Cuál es la probabilidad de encontrar como mínimo 4 postulantes con experiencia: P(X ≥ 4)?`,
                    esperado: pMin4,
                    tolerancia: 0.01,
                    pista: `P(X ≥ 4) = P(4) + P(5). Seleccioná cola derecha P(X ≥ x) con x=4.`,
                    explicacion: `P(X ≥ 4) = P(X=4) + P(X=5) = 0.1093 + 0.0236 ≈ 0.13287 (13.29%).`
                }
            ]
        };
    } else if (prefierePoisson) {
        // Caso TP3 Ejercicio 12 de la Guía: Central telefónica (5 llamadas/min)
        // En 2 minutos: lambda = 10 llamadas
        const lam = 10;
        const k = 8;
        
        function fact(n) { return n <= 1 ? 1 : n * fact(n - 1); }
        function pPois(l, x) { return (Math.exp(-l) * Math.pow(l, x)) / fact(x); }

        const pExacta = Number(pPois(lam, k).toFixed(4)); // ~0.1126
        let pAcum = 0;
        for (let i = 0; i <= k; i++) pAcum += pPois(lam, i);
        pAcum = Number(pAcum.toFixed(4)); // ~0.3328
        const pMasDe8 = Number((1 - pAcum).toFixed(4)); // ~0.6672 (Respuesta oficial guía: 0.66718)

        const enunciado = "En una central telefónica se reciben en promedio 5 llamadas por minuto. El proceso de arribo sigue un proceso de Poisson continuo sin memoria:";
        const datosStr = `Tasa promedio en 2 minutos (λ) = 10 llamadas\nVariable de análisis: Cantidad de llamadas recibidas en un lapso de 2 minutos`;

        return {
            id: "pois_" + Date.now(),
            materia: "estadistica",
            tema: "poisson",
            origen: "modelo",
            titulo: "Distribución de Poisson: Central Telefónica y Arribos (TP3 Ejercicio 12)",
            dificultad: "Intermedia",
            enunciado: enunciado,
            datos: datosStr,
            datos_tipo: "parametros",
            narrativa: `${enunciado}\n\n${datosStr}`,
            preguntas: [
                {
                    letra: "a",
                    texto: `Determiná el Valor Esperado o media de llamadas en el intervalo de 2 minutos: E(X) = λ:`,
                    esperado: lam,
                    tolerancia: 0.1,
                    pista: "En Poisson, el valor esperado y la varianza son idénticos a la tasa media del intervalo.",
                    explicacion: `E(X) = λ = 5 llamadas/min · 2 min = ${lam} llamadas.`
                },
                {
                    letra: "b",
                    texto: `Calculá la probabilidad de recibir exactamente k = 8 llamadas en 2 minutos: P(X = 8):`,
                    esperado: pExacta,
                    tolerancia: 0.008,
                    pista: `Fórmula de Poisson: (e^(-10) · 10^8) / 8!. Ingresá λ=10 y x=8 en la suite interactiva.`,
                    explicacion: `P(X = 8) = (e^(-10) · 10^8) / 8! ≈ ${pExacta} (${(pExacta * 100).toFixed(2)}%).`
                },
                {
                    letra: "c",
                    texto: `Calculá la probabilidad acumulada de recibir a lo sumo 8 llamadas: P(X ≤ 8):`,
                    esperado: pAcum,
                    tolerancia: 0.015,
                    pista: `Sumá las probabilidades puntuales desde 0 hasta 8 o usá cola izquierda en la calculadora.`,
                    explicacion: `P(X ≤ 8) ≈ ${pAcum} (${(pAcum * 100).toFixed(2)}%).`
                },
                {
                    letra: "d",
                    texto: `¿Cuál es la probabilidad de que en 2 minutos se reciban más de 8 llamadas: P(X > 8)?`,
                    esperado: pMasDe8,
                    tolerancia: 0.01,
                    pista: `Regla del complemento: P(X > 8) = 1 - P(X ≤ 8). Podés usar la cola derecha estricta P(X > x).`,
                    explicacion: `P(X > 8) = 1 - P(X ≤ 8) = 1 - ${pAcum} = ${pMasDe8} (Respuesta oficial guía: 0.66718).`
                }
            ]
        };
    } else {
        // Caso TP3 Ejercicio 8 de la Guía: Encuesta de aceptación de producto en mercado
        // n = 20 personas, p = 0.60
        const n = 20;
        const p = 0.60;
        const media = Number((n * p).toFixed(2)); // 12
        const k = 10;
        const pExacta10 = Number(labBinomialPMF(n, p, 10).toFixed(5)); // 0.11714 (Respuesta oficial guía: 0.11714)
        let pAcum12 = 0;
        for (let i = 0; i <= 12; i++) pAcum12 += labBinomialPMF(n, p, i);
        pAcum12 = Number(pAcum12.toFixed(5)); // 0.58411 (Respuesta oficial guía: 0.58411)
        let pMasDe9 = 0;
        for (let i = 10; i <= n; i++) pMasDe9 += labBinomialPMF(n, p, i);
        pMasDe9 = Number(pMasDe9.toFixed(4)); // 0.8725

        const enunciado = "Se realiza una encuesta de mercado para evaluar la repercusión de un producto que será lanzado comercialmente. Por estudios previos, se conoce que el porcentaje de aceptación es del 60% (p = 0,60). Se toma una muestra representativa de n = 20 personas:";
        const datosStr = `Tamaño de la muestra aleatoria (n) = ${n}\nProbabilidad de éxito / aceptación (p) = ${p}\nVariable X: Cantidad de personas que aceptan el producto`;

        return {
            id: "disc_" + Date.now(),
            materia: "estadistica",
            tema: "binomial",
            origen: "modelo",
            titulo: "Distribución Binomial: Encuesta de Aceptación de Mercado (TP3 Ejercicio 8)",
            dificultad: "Intermedia",
            enunciado: enunciado,
            datos: datosStr,
            datos_tipo: "parametros",
            narrativa: `${enunciado}\n\n${datosStr}`,
            preguntas: [
                {
                    letra: "a",
                    texto: `Calculá el Valor Esperado o media de compradores en la muestra: E(X) = n · p:`,
                    esperado: media,
                    tolerancia: 0.1,
                    pista: `E(X) = n · p = 20 · 0.60 = 12 personas.`,
                    explicacion: `El valor esperado de compradores es E(X) = 20 · 0.60 = ${media} personas.`
                },
                {
                    letra: "b",
                    texto: `¿Cuál es la probabilidad de que exactamente diez personas compren el producto: P(X = 10)?`,
                    esperado: pExacta10,
                    tolerancia: 0.008,
                    pista: `Fórmula Binomial: C(20, 10) · (0.60)^10 · (0.40)^10. Podés usar la suite de distribuciones con n=20, p=0.60 y x=10.`,
                    explicacion: `P(X = 10) = C(20,10) · 0.60^10 · 0.40^10 ≈ 0.11714 (Respuesta oficial guía).`
                },
                {
                    letra: "c",
                    texto: `¿Cuál es la probabilidad de que a lo sumo 12 personas compren el producto: P(X ≤ 12)?`,
                    esperado: pAcum12,
                    tolerancia: 0.015,
                    pista: `Sumá las probabilidades acumuladas P(X=0) + ... + P(X=12) o seleccioná cola izquierda P(X ≤ x) con x=12.`,
                    explicacion: `P(X ≤ 12) = Σ P(X = i) ≈ 0.58411 (Respuesta oficial guía).`
                },
                {
                    letra: "d",
                    texto: `¿Cuál es la probabilidad de que al menos 10 personas acepten el producto: P(X ≥ 10)?`,
                    esperado: pMasDe9,
                    tolerancia: 0.01,
                    pista: `P(X ≥ 10) = 1 - P(X ≤ 9). Seleccioná cola derecha P(X ≥ x) con x=10.`,
                    explicacion: `P(X ≥ 10) = 1 - P(X ≤ 9) ≈ ${pMasDe9} (${(pMasDe9 * 100).toFixed(2)}%).`
                }
            ]
        };
    }
}

function generarEjercicioInferenciaProcedural(orden = "") {
    const ordenLower = (orden || "").toLowerCase();
    
    if (ordenLower.includes("chi") || ordenLower.includes("chi2") || ordenLower.includes("cuadrado")) {
        const df = 5;
        const valCrit = 11.07;
        return {
            id: "chi_" + Date.now(),
            materia: "estadistica",
            tema: "inferencia",
            origen: "modelo",
            titulo: "Inferencia Estadística: Distribución Chi-cuadrado (χ²)",
            dificultad: "Intermedia",
            enunciado: "En una prueba de bondad de ajuste y homogeneidad se utiliza la distribución Chi-cuadrado con 5 grados de libertad:",
            datos: `Grados de libertad (ν) = ${df}\nNivel de significación (α) = 0.05 cola derecha\nValor crítico tabulated = ${valCrit}`,
            datos_tipo: "parametros",
            narrativa: `En una prueba estadística de varianzas o bondad de ajuste con ν = ${df} grados de libertad, se analiza la región crítica para un nivel α = 0.05.`,
            preguntas: [
                {
                    letra: "a",
                    texto: `Determiná la media o valor esperado de una variable Chi-cuadrado: E(χ²) = ν:`,
                    esperado: df,
                    tolerancia: 0.1,
                    pista: `En la distribución χ², la media es igual a sus grados de libertad ν.`,
                    explicacion: `E(χ²) = ν = ${df}.`
                },
                {
                    letra: "b",
                    texto: `Calculá la probabilidad de superar el valor crítico: P(χ² ≥ ${valCrit}):`,
                    esperado: 0.05,
                    tolerancia: 0.01,
                    pista: `Es el nivel de significación α del cuantil crítico.`,
                    explicacion: `P(χ² ≥ ${valCrit}) ≈ 0.05 (5%).`
                }
            ]
        };
    } else {
        // t de Student
        const df = 10;
        const valCrit = 2.228;
        return {
            id: "t_" + Date.now(),
            materia: "estadistica",
            tema: "inferencia",
            origen: "modelo",
            titulo: "Inferencia Estadística: Distribución t de Student (Intervalos de Confianza)",
            dificultad: "Intermedia",
            enunciado: "Para construir un intervalo de confianza del 95% para la media poblacional con muestra pequeña (n = 11, ν = n - 1 = 10 grados de libertad) y varianza poblacional desconocida:",
            datos: `Grados de libertad (ν) = ${df}\nNivel de confianza = 95% (bilateral α = 0.05)\nValor crítico t bilateral = ${valCrit}`,
            datos_tipo: "parametros",
            narrativa: `Se calcula el intervalo de confianza de Student con ν = ${df} grados de libertad. El valor crítico simétrico que encierra el 95% central es t = ±${valCrit}.`,
            preguntas: [
                {
                    letra: "a",
                    texto: `¿Cuál es el valor esperado o centro de simetría de la distribución t de Student?`,
                    esperado: 0,
                    tolerancia: 0.01,
                    pista: `La distribución t de Student es estrictamente simétrica centrada en el origen.`,
                    explicacion: `La media o centro es 0.`
                },
                {
                    letra: "b",
                    texto: `Verificá en la calculadora la probabilidad bilateral en las colas: P(|t| ≥ ${valCrit}):`,
                    esperado: 0.05,
                    tolerancia: 0.01,
                    pista: `Área en ambas colas = 1 - 0.95 = 0.05.`,
                    explicacion: `P(|t| ≥ ${valCrit}) = 0.05 (5% en dos colas).`
                }
            ]
        };
    }
}

function generarEjercicioIntegralProcedural(orden = "") {
    const examenes = [
        {
            titulo: "Simulacro de Examen Final: Control de Calidad y Dispersión Muestral",
            sector: "Industria Farmacéutica",
            narrativa: `EXAMEN FINAL DE CÁTEDRA - CASO INTEGRADOR:\nUn laboratorio farmacéutico analiza el peso efectivo en miligramos (xi) de un lote de cápsulas de antibiótico.\nSe tomó una muestra representativa con los siguientes pesos y frecuencias observadas:\n- 490 mg: 8 cápsulas\n- 495 mg: 15 cápsulas\n- 500 mg: 25 cápsulas\n- 505 mg: 18 cápsulas\n- 510 mg: 4 cápsulas\n\nCargá estos valores (xi y fi) en la tabla de frecuencias de la Mesa de Trabajo y utilizá la calculadora estadística y probabilística para responder los incisos del examen:`,
            x: [490, 495, 500, 505, 510],
            f: [8, 15, 25, 18, 4]
        },
        {
            titulo: "Simulacro de Examen Final: Auditoría de Tiempos y Rendimiento",
            sector: "Telecomunicaciones y Redes",
            narrativa: `EXAMEN FINAL DE CÁTEDRA - CASO INTEGRADOR:\nUna empresa de telecomunicaciones evalúa la latencia en milisegundos (xi) de paquetes de datos transmitidos por un enlace satelital.\nLos datos observados en una muestra de auditoría son:\n- 40 ms: 12 paquetes\n- 45 ms: 22 paquetes\n- 50 ms: 30 paquetes\n- 55 ms: 20 paquetes\n- 60 ms: 6 paquetes\n\nCargá estos valores en la tabla de la Mesa de Trabajo para obtener las sumatorias y responder los incisos del examen:`,
            x: [40, 45, 50, 55, 60],
            f: [12, 22, 30, 20, 6]
        }
    ];

    const sel = examenes[Math.floor(Math.random() * examenes.length)];
    let N = 0;
    let sumXiFi = 0;
    let sumXi2Fi = 0;
    for (let i = 0; i < sel.x.length; i++) {
        N += sel.f[i];
        sumXiFi += sel.x[i] * sel.f[i];
        sumXi2Fi += sel.x[i] * sel.x[i] * sel.f[i];
    }
    const media = Number((sumXiFi / N).toFixed(2));
    const varianza = Number(((sumXi2Fi - N * media * media) / (N - 1)).toFixed(2));
    const desvio = Number(Math.sqrt(varianza).toFixed(2));
    const cv = Number(((desvio / media) * 100).toFixed(2));

    const enunciado = `Simulacro de Examen Final de Cátedra: análisis de control en ${sel.sector}:`;
    const datosStr = sel.x.map((val, idx) => `• Valor xi = ${val} : Frecuencia fi = ${sel.f[idx]}`).join("\n");

    return {
        id: "exam_" + Date.now(),
        tema: "integral",
        origen: "modelo",
        titulo: sel.titulo,
        dificultad: laboratorioEstado.dificultad || "Intermedia",
        enunciado: enunciado,
        datos: datosStr,
        datos_tipo: "tabla",
        narrativa: `${enunciado}\n\n${datosStr}`,
        preguntas: [
            {
                letra: "a",
                texto: "Determina el tamaño total de la muestra analizada (N = Σ fi):",
                esperado: N,
                tolerancia: 0,
                pista: "Sumá todas las frecuencias absolutas observadas (fi).",
                explicacion: `N = Σ fi = ${N}. Podés verificarlo en la tarjeta 'Tamaño (N)'.`
            },
            {
                letra: "b",
                texto: "Calculá la Media Aritmética o Promedio muestral (x̄):",
                esperado: media,
                tolerancia: 0.1,
                pista: `x̄ = Σ(xi · fi) / N = ${sumXiFi} / ${N}`,
                explicacion: `x̄ = ${sumXiFi} / ${N} = ${media}.`
            },
            {
                letra: "c",
                texto: "Calculá el Desvío Estándar Muestral (s):",
                esperado: desvio,
                tolerancia: 0.15,
                pista: `s = √(s²) = √${varianza}`,
                explicacion: `s² = ${varianza} -> s = ${desvio}.`
            },
            {
                letra: "d",
                texto: "¿Cuál es el Coeficiente de Variación porcentual (CV%)?",
                esperado: cv,
                tolerancia: 0.5,
                pista: `CV = (s / x̄) * 100 = (${desvio} / ${media}) * 100`,
                explicacion: `CV = ${cv}%. Un CV menor al 20% suele indicar una muestra homogénea.`
            },
            {
                letra: "e",
                texto: "Si se asume distribución Normal N(μ = x̄, σ = s), ¿qué porcentaje (%) de las observaciones se espera que caigan dentro de ±1 desvío estándar de la media?",
                esperado: 68.3,
                tolerancia: 1.0,
                pista: "Propiedad de la regla empírica 68-95-99.7 de la campana de Gauss: P(μ - σ ≤ X ≤ μ + σ) ≈ 68.27%.",
                explicacion: "Por la regla empírica de Gauss, el 68.3% del área bajo la curva normal estándar cae entre -1 y +1 desviaciones típicas."
            }
        ]
    };
}

// ------------------------------------------
// SELECTORES DE DIFICULTAD Y FORMATEO DE DATOS
// ------------------------------------------

function sincronizarSelectoresDificultadLab() {
    const diff = (laboratorioEstado.dificultad || "intermedio").toLowerCase();
    const selectors = [
        document.getElementById("labConfigDifficultySelector"),
        document.getElementById("labPromptDifficultySelector")
    ];

    selectors.forEach(sel => {
        if (!sel) return;
        sel.querySelectorAll(".lab-diff-btn").forEach(btn => {
            const btnDiff = btn.dataset.diff;
            if (btnDiff === diff) {
                btn.classList.add("is-active");
            } else {
                btn.classList.remove("is-active");
            }

            if (!btn.dataset.wired) {
                btn.dataset.wired = "true";
                btn.addEventListener("click", () => {
                    laboratorioEstado.dificultad = btnDiff;
                    sincronizarSelectoresDificultadLab();
                });
            }
        });
    });
}

function formatearBloqueDatosLab(datos, tipo = "auto") {
    if (!datos) return "";

    // Si ya viene como HTML formateado
    if (typeof datos === "string" && (datos.includes("<div") || datos.includes("<table") || datos.includes("<ul"))) {
        return `<div class="lab-case-data-box">${datos}</div>`;
    }

    let headerBadge = "Datos de Estudio";
    let bodyHtml = "";

    // 1. Detección de Tabla (si tiene formato x | P(x) o pares xi = ... : fi = ...)
    if (tipo === "tabla" || (typeof datos === "string" && (datos.includes("|") || datos.includes("xi =") || datos.includes("xi:")))) {
        headerBadge = "Tabla de Datos / Distribución";
        bodyHtml = construirTablaDatosLabHtml(datos);
    } 
    // 2. Detección de Parámetros (probabilidades, medias, tasas)
    else if (tipo === "parametros" || (typeof datos === "string" && (datos.includes("P(") || datos.includes("μ") || datos.includes("mu") || datos.includes("σ") || datos.includes("lambda") || datos.includes("λ")))) {
        headerBadge = "Parámetros del Problema";
        const lineas = typeof datos === "string" ? datos.split(/\n|\;/).map(l => l.trim()).filter(Boolean) : [];
        bodyHtml = `
            <div class="lab-data-params-list">
                ${lineas.map(lin => {
                    const partes = lin.split(/[:=]/);
                    if (partes.length >= 2) {
                        return `<div class="lab-data-param-item"><span class="lab-data-param-symbol">${partes[0].trim()}:</span> <span>${partes.slice(1).join("=").trim()}</span></div>`;
                    }
                    return `<div class="lab-data-param-item">${lin}</div>`;
                }).join("")}
            </div>
        `;
    }
    // 3. Operaciones Comerciales / Lista de Hechos Económicos (Contabilidad / Enunciados)
    else if (tipo === "operaciones" || tipo === "lista" || (typeof datos === "string" && (datos.includes("1.") || datos.includes("•") || datos.includes("Op.") || datos.includes("Situación")))) {
        headerBadge = "Operaciones del Ejercicio";
        const lineas = typeof datos === "string" ? datos.split(/\n+/).map(l => l.trim()).filter(Boolean) : [];
        bodyHtml = `
            <div class="lab-operations-list" style="display: flex; flex-direction: column; gap: 0.65rem;">
                ${lineas.map(lin => {
                    const matchNum = lin.match(/^(\d+[\.\)]|\•|\-\s*)\s*(.*)/);
                    if (matchNum) {
                        return `
                            <div class="lab-operation-item" style="display: flex; align-items: flex-start; gap: 0.75rem; background: rgba(30, 41, 59, 0.6); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 8px; padding: 0.7rem 0.9rem; line-height: 1.55; font-size: 0.9rem;">
                                <span class="badge badge--accent" style="flex-shrink: 0; font-size: 0.75rem; font-weight: 700; margin-top: 0.15rem; background: rgba(56,189,248,0.15); color: #38bdf8; border: 1px solid rgba(56,189,248,0.3);">${matchNum[1]}</span>
                                <span style="color: #f1f5f9; word-break: break-word;">${matchNum[2]}</span>
                            </div>
                        `;
                    }
                    return `<div class="lab-case-data-content" style="font-size: 0.9rem; line-height: 1.55; color: #f1f5f9; padding: 0.35rem 0;">${lin}</div>`;
                }).join("")}
            </div>
        `;
    }
    // 4. Muestra de Datos Numéricos Puros (sin oraciones de texto)
    else {
        const isSentenceText = typeof datos === "string" && /[a-záéíóúñ]{4,}/i.test(datos);
        if (!isSentenceText) {
            headerBadge = "Muestra Observada";
            const nums = Array.isArray(datos) ? datos : String(datos).match(/-?\d+(\.\d+)?/g);
            if (nums && nums.length >= 3) {
                bodyHtml = `
                    <div style="font-size: 0.8rem; color: var(--color-text-muted); margin-bottom: 0.35rem;">
                        Valores registrados (n = ${nums.length}):
                    </div>
                    <div class="lab-data-chips">
                        ${nums.map(n => `<span class="lab-data-chip">${n}</span>`).join("")}
                    </div>
                `;
            } else {
                bodyHtml = `<div class="lab-case-data-content" style="white-space: pre-line; color: #f1f5f9; line-height: 1.6;">${datos}</div>`;
            }
        } else {
            headerBadge = "Enunciado del Caso";
            bodyHtml = `<div class="lab-case-data-content" style="white-space: pre-line; color: #f1f5f9; line-height: 1.6;">${datos}</div>`;
        }
    }

    return `
        <div class="lab-case-data-box">
            <div class="lab-case-data-header">
                <span>📋 Información y Datos del Caso</span>
                <span class="lab-case-data-header-badge">${headerBadge}</span>
            </div>
            ${bodyHtml}
        </div>
    `;
}

function construirTablaDatosLabHtml(datos) {
    if (typeof datos !== "string") return `<div class="lab-case-data-content">${datos}</div>`;

    const lineas = datos.split("\n").map(l => l.trim()).filter(Boolean);
    
    // Formato con viñetas: "• Valor xi = 18 : Frecuencia fi = 6"
    if (lineas.some(l => l.includes("xi =") && l.includes("fi ="))) {
        const rows = [];
        lineas.forEach(l => {
            const m = l.match(/xi\s*=\s*([0-9\.\-]+)\s*:\s*fi\s*=\s*([0-9\.\-]+)/i);
            if (m) rows.push({ x: m[1], f: m[2] });
        });
        if (rows.length > 0) {
            return `
                <div class="lab-data-table-wrapper">
                    <table class="lab-data-table">
                        <thead>
                            <tr>
                                <th>Valor Variable (xi)</th>
                                <th>Frecuencia Absoluta (fi)</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${rows.map(r => `<tr><td>${r.x}</td><td>${r.f}</td></tr>`).join("")}
                        </tbody>
                    </table>
                </div>
            `;
        }
    }

    // Formato con pipes markdown "|"
    if (lineas.some(l => l.includes("|"))) {
        const parsed = lineas.filter(l => !l.match(/^[\s\-\|\:]+$/)).map(l => l.split("|").map(c => c.trim()).filter(Boolean));
        if (parsed.length >= 2) {
            const header = parsed[0];
            const bodyRows = parsed.slice(1);
            return `
                <div class="lab-data-table-wrapper">
                    <table class="lab-data-table">
                        <thead>
                            <tr>${header.map(h => `<th>${h}</th>`).join("")}</tr>
                        </thead>
                        <tbody>
                            ${bodyRows.map(row => `<tr>${row.map(c => `<td>${c}</td>`).join("")}</tr>`).join("")}
                        </tbody>
                    </table>
                </div>
            `;
        }
    }

    return `<div class="lab-case-data-content" style="white-space: pre-line;">${datos}</div>`;
}

// ------------------------------------------
// ADAPTACIÓN INTELIGENTE DE LA MESA DE TRABAJO SEGÚN EL EJERCICIO
// ------------------------------------------

function adaptarMesaTrabajoSegunEjercicio(ej) {
    if (!ej) return;
    const materiaId = ej.materia || laboratorioEstado.materiaSeleccionada || "estadistica";
    const tema = (ej.tema || "").toLowerCase();

    // 1. Filtrar las pestañas visibles para esta materia
    filtrarTabsPorMateria(materiaId);

    // 2. Adaptar dinámicamente según el tema y la unidad
    if (materiaId === "estadistica") {
        if (tema.includes("normal") || tema.includes("gauss")) {
            activarTabLaboratorio("prob");
            let mu = 0, sigma = 1, xVal = 1.96;
            if (ej.datos && typeof ej.datos === "string") {
                const matchMu = ej.datos.match(/μ\s*=\s*([0-9.,]+)/i) || ej.datos.match(/media\s*[:=]\s*([0-9.,]+)/i);
                const matchSigma = ej.datos.match(/σ\s*=\s*([0-9.,]+)/i) || ej.datos.match(/desv[íi]o\s*[:=]\s*([0-9.,]+)/i);
                const matchX = ej.datos.match(/X\s*=\s*([0-9.,]+)/i) || ej.datos.match(/corte\s*[:=]\s*([0-9.,]+)/i);
                if (matchMu) mu = parseFloat(matchMu[1].replace(',', '.'));
                if (matchSigma) sigma = parseFloat(matchSigma[1].replace(',', '.'));
                if (matchX) xVal = parseFloat(matchX[1].replace(',', '.'));
            }
            seleccionarDistribucionLab("normal", { mu, sigma }, xVal, "left");
        } else if (tema.includes("discreta") || tema.includes("binomial") || tema.includes("bernoulli")) {
            activarTabLaboratorio("prob");
            let n = 10, pr = 0.5, k = 2;
            if (ej.datos && typeof ej.datos === "string") {
                const matchN = ej.datos.match(/n\s*=\s*([0-9]+)/i);
                const matchP = ej.datos.match(/p\s*=\s*([0-9.,]+)/i);
                const matchK = ej.datos.match(/k\s*=\s*([0-9]+)/i);
                if (matchN) n = parseInt(matchN[1]);
                if (matchP) pr = parseFloat(matchP[1].replace(',', '.'));
                if (matchK) k = parseInt(matchK[1]);
            }
            seleccionarDistribucionLab("binomial", { n, pr }, k, "left");
        } else if (tema.includes("poisson")) {
            activarTabLaboratorio("prob");
            let lambda = 3, k = 2;
            if (ej.datos && typeof ej.datos === "string") {
                const matchL = ej.datos.match(/λ\s*=\s*([0-9.,]+)/i) || ej.datos.match(/tasa\s*[:=]\s*([0-9.,]+)/i);
                const matchK = ej.datos.match(/k\s*=\s*([0-9]+)/i);
                if (matchL) lambda = parseFloat(matchL[1].replace(',', '.'));
                if (matchK) k = parseInt(matchK[1]);
            }
            seleccionarDistribucionLab("poisson", { lambda }, k, "left");
        } else if (tema.includes("hiper") || tema.includes("hyper")) {
            activarTabLaboratorio("prob");
            let N = 14, K = 5, n = 7, kVal = 3;
            if (ej.datos && typeof ej.datos === "string") {
                const matchN = ej.datos.match(/N\s*=\s*([0-9]+)/i);
                const matchK = ej.datos.match(/K\s*=\s*([0-9]+)/i);
                const matchn = ej.datos.match(/n\s*=\s*([0-9]+)/i);
                if (matchN) N = parseInt(matchN[1]);
                if (matchK) K = parseInt(matchK[1]);
                if (matchn) n = parseInt(matchn[1]);
            }
            seleccionarDistribucionLab("hyper", { N, K, n }, kVal, "exact");
        } else if (tema.includes("inferencia") || tema.includes("student") || tema.includes("chi") || tema.includes("fisher")) {
            activarTabLaboratorio("prob");
            const titLower = ((ej.titulo || "") + " " + (ej.enunciado || "")).toLowerCase();
            if (titLower.includes("chi") || titLower.includes("χ²")) {
                seleccionarDistribucionLab("chi2", { df: 5 }, 11.07, "right");
            } else if (titLower.includes("fisher") || titLower.includes("f de fisher")) {
                seleccionarDistribucionLab("f", { df1: 5, df2: 10 }, 3.33, "right");
            } else {
                seleccionarDistribucionLab("t", { df: 10 }, 2.228, "two");
            }
        } else if (tema.includes("bayes")) {
            activarTabLaboratorio("bayes");
        } else {
            // Descriptiva o Frecuencias
            activarTabLaboratorio("freq");
            if (ej.datos && typeof ej.datos === "string" && ej.datos.includes("xi =")) {
                const lineas = ej.datos.split("\n");
                const filas = [];
                lineas.forEach(l => {
                    const mXi = l.match(/xi\s*=\s*([0-9.,-]+)/i);
                    const mFi = l.match(/fi\s*=\s*([0-9.,-]+)/i);
                    if (mXi && mFi) {
                        filas.push({ xi: mXi[1], fi: mFi[1] });
                    }
                });
                if (filas.length > 0) {
                    laboratorioEstado.tablaDatos = filas;
                    renderizarGrillaFrecuencias();
                }
            }
        }
    } else if (materiaId === "contabilidad") {
        activarTabLaboratorio("contabilidad");
        if (tema.includes("mayor")) {
            cambiarSubvistaContabilidad("mayor");
        } else if (tema.includes("balance")) {
            cambiarSubvistaContabilidad("balance");
        } else if (tema.includes("cmv") || tema.includes("iva") || tema.includes("calc")) {
            cambiarSubvistaContabilidad("calc");
        } else {
            cambiarSubvistaContabilidad("diario");
        }
    } else if (materiaId === "quimica") {
        activarTabLaboratorio("quimica");
        if (tema.includes("calc") || tema.includes("mole") || tema.includes("ph") || tema.includes("gas") || tema.includes("soluci")) {
            if (typeof conmutarSubtabQuimica === "function") conmutarSubtabQuimica("calc");
        } else {
            if (typeof conmutarSubtabQuimica === "function") conmutarSubtabQuimica("tabla");
        }
    } else if (materiaId === "fisica") {
        activarTabLaboratorio("fisica");
        if (tema.includes("calc") || tema.includes("dinam") || tema.includes("ohm") || tema.includes("energia") || tema.includes("mru")) {
            if (typeof conmutarSubtabFisica === "function") conmutarSubtabFisica("calc");
        } else {
            if (typeof conmutarSubtabFisica === "function") conmutarSubtabFisica("sim");
        }
    } else if (materiaId === "matematicas") {
        activarTabLaboratorio("matematicas");
        if (tema.includes("bhask") || tema.includes("cuadra") || tema.includes("pitag") || tema.includes("regla") || tema.includes("calc")) {
            if (typeof conmutarSubtabMatematicas === "function") conmutarSubtabMatematicas("calc");
        } else {
            if (typeof conmutarSubtabMatematicas === "function") conmutarSubtabMatematicas("graf");
        }
    } else if (materiaId === "calculo") {
        activarTabLaboratorio("calculo");
    } else if (materiaId === "algebra_lineal") {
        activarTabLaboratorio("matrices");
        if (typeof conmutarSubtabMatrices === "function") {
            if (tema.includes("vector") || tema.includes("cramer") || tema.includes("punto") || tema.includes("cruz")) {
                conmutarSubtabMatrices("vectores");
            } else if (tema.includes("3x3") || tema.includes("sarrus")) {
                conmutarSubtabMatrices("3x3");
            } else {
                conmutarSubtabMatrices("2x2");
            }
        }
    } else if (materiaId === "computacion") {
        activarTabLaboratorio("computacion");
    } else if (materiaId === "biologia") {
        activarTabLaboratorio("biologia");
    } else if (materiaId === "financiera") {
        activarTabLaboratorio("financiera");
        if (typeof conmutarSubtabFinanciera === "function") {
            if (tema.includes("inter") || tema.includes("tasa") || tema.includes("tea") || tema.includes("compuesto") || tema.includes("calc")) {
                conmutarSubtabFinanciera("calc");
            } else {
                conmutarSubtabFinanciera("prest");
            }
        }
    } else if (materiaId === "medicina") {
        activarTabLaboratorio("medicina");
    }
}

// ------------------------------------------
// RENDERIZADO DEL ENUNCIADO Y LAS PREGUNTAS
// ------------------------------------------

function renderizarEjercicioActual(resetRespuestas = false) {
    const ej = laboratorioEstado.ejercicioActual;
    if (!ej) return;

    // Adaptar mesa de trabajo de acuerdo a lo que pide el ejercicio
    adaptarMesaTrabajoSegunEjercicio(ej);

    // Encabezado del caso
    if (dom.labTituloCaso) dom.labTituloCaso.textContent = ej.titulo || "Caso Práctico de Estudio";
    
    // Tag de Dificultad con icono y color
    const dLower = (ej.dificultad || laboratorioEstado.dificultad || "intermedio").toLowerCase();
    let diffIcon = "🟡";
    let diffNombre = "Intermedia";
    if (dLower.includes("facil")) {
        diffIcon = "🟢";
        diffNombre = "Fácil";
    } else if (dLower.includes("dificil")) {
        diffIcon = "🔴";
        diffNombre = "Difícil";
    } else if (dLower.includes("extremo")) {
        diffIcon = "⚡";
        diffNombre = "Extrema";
    }
    if (dom.labTagDificultad) dom.labTagDificultad.textContent = `${diffIcon} Dificultad: ${diffNombre}`;
    if (dom.labTagTema) dom.labTagTema.textContent = obtenerEtiquetaTema(ej.tema);

    // Enunciado corto + Bloque estructurado de datos destacados
    let textoEnunciado = ej.enunciado || "";
    let contenidoDatos = ej.datos || ej.datosHtml || "";

    if (!textoEnunciado && ej.narrativa) {
        // Extraer si vino como texto único
        const matchSplit = ej.narrativa.split(/\n\n|\n(?=[A-Z0-9\-\*\•]|Muestra|Datos|Valores|P\(|x\s*\|)/i);
        if (matchSplit.length > 1) {
            textoEnunciado = matchSplit[0].trim();
            contenidoDatos = matchSplit.slice(1).join("\n\n").trim();
        } else {
            textoEnunciado = ej.narrativa;
        }
    }

    if (dom.labNarrativaCaso) {
        dom.labNarrativaCaso.textContent = textoEnunciado || "Analizá la información provista y resolvé los incisos planteados:";
    }

    const containerDatos = dom.labDatosCasoContainer || document.getElementById("labDatosCasoContainer");
    if (containerDatos) {
        if (contenidoDatos) {
            containerDatos.classList.remove("hidden");
            setHTML(containerDatos, formatearBloqueDatosLab(contenidoDatos, ej.datos_tipo));
        } else {
            containerDatos.classList.add("hidden");
            setHTML(containerDatos, "");
        }
    }

    // Resetear estados de preguntas solo si es un ejercicio nuevo generado
    if (resetRespuestas) {
        laboratorioEstado.intentosPorPregunta = {};
        laboratorioEstado.resueltasPorPregunta = {};
        laboratorioEstado.pistasReveladas = {};
        laboratorioEstado.solucionesReveladas = {};
        laboratorioEstado.respuestasUsuario = {};
    } else {
        if (!laboratorioEstado.intentosPorPregunta) laboratorioEstado.intentosPorPregunta = {};
        if (!laboratorioEstado.resueltasPorPregunta) laboratorioEstado.resueltasPorPregunta = {};
        if (!laboratorioEstado.pistasReveladas) laboratorioEstado.pistasReveladas = {};
        if (!laboratorioEstado.solucionesReveladas) laboratorioEstado.solucionesReveladas = {};
        if (!laboratorioEstado.respuestasUsuario) laboratorioEstado.respuestasUsuario = {};
    }

    const total = (ej.preguntas || []).length;
    const resueltasCount = Object.keys(laboratorioEstado.resueltasPorPregunta || {}).length;
    if (dom.labCompletedCard) {
        if (resueltasCount >= total && total > 0) {
            dom.labCompletedCard.classList.remove("hidden");
        } else {
            dom.labCompletedCard.classList.add("hidden");
        }
    }

    actualizarProgresoPreguntasUI();

    // Renderizar incisos a), b), c), d), e)
    if (!dom.labQuestionsList) return;
    setHTML(dom.labQuestionsList, "");

    ej.preguntas.forEach((q, idx) => {
        const item = document.createElement("div");
        item.className = "lab-question-item";
        item.id = `labQuestionItem_${idx}`;

        const valorGuardado = (laboratorioEstado.respuestasUsuario && laboratorioEstado.respuestasUsuario[idx] !== undefined)
            ? String(laboratorioEstado.respuestasUsuario[idx])
            : "";

        setHTML(item, `
            <div class="lab-q-prompt-row">
                <span class="lab-q-letter-badge">${q.letra.toUpperCase()})</span>
                <p class="lab-q-text">${q.texto}</p>
            </div>
            <div class="lab-q-action-row">
                <input type="number" class="input input--sm lab-q-input" id="labQInput_${idx}" data-qindex="${idx}" placeholder="Ingresá tu respuesta..." step="any" value="${valorGuardado}">
                <button type="button" class="button button--primary button--sm lab-q-verify-btn" id="labBtnVerify_${idx}" data-qindex="${idx}">
                    Verificar
                </button>
                <span class="lab-q-status-badge" id="labQStatus_${idx}"></span>
            </div>
            <div class="lab-3rd-attempt-box hidden" id="lab3rdAttemptBox_${idx}">
                <p class="lab-3rd-attempt-prompt">🤔 ¿Querés una pista para resolver este inciso o preferís ver la respuesta explicada?</p>
                <div class="lab-3rd-attempt-actions">
                    <button type="button" class="button button--secondary button--xs" id="labBtnPista_${idx}" data-qindex="${idx}">
                        💡 Ver Pista
                    </button>
                    <button type="button" class="button button--accent button--xs" id="labBtnRespuesta_${idx}" data-qindex="${idx}">
                        📖 Ver Respuesta & Paso a Paso
                    </button>
                </div>
            </div>
            <div class="lab-q-reveal-box hidden" id="labQRevealBox_${idx}"></div>
        `);

        dom.labQuestionsList.appendChild(item);

        // Wire events de cada pregunta
        const verifyBtn = item.querySelector(`#labBtnVerify_${idx}`);
        const inputField = item.querySelector(`#labQInput_${idx}`);
        const pistaBtn = item.querySelector(`#labBtnPista_${idx}`);
        const respBtn = item.querySelector(`#labBtnRespuesta_${idx}`);
        const statusBadge = item.querySelector(`#labQStatus_${idx}`);
        const attemptBox = item.querySelector(`#lab3rdAttemptBox_${idx}`);
        const revealBox = item.querySelector(`#labQRevealBox_${idx}`);

        // Restaurar estado visual previo guardado
        if (laboratorioEstado.resueltasPorPregunta && laboratorioEstado.resueltasPorPregunta[idx]) {
            item.classList.add("is-correct");
            if (statusBadge) {
                statusBadge.className = "lab-q-status-badge is-correct";
                statusBadge.textContent = "✅ ¡Correcto! (+25 XP)";
            }
            if (inputField) inputField.disabled = true;
            if (verifyBtn) verifyBtn.disabled = true;
        } else if (laboratorioEstado.intentosPorPregunta && laboratorioEstado.intentosPorPregunta[idx]) {
            const intentos = laboratorioEstado.intentosPorPregunta[idx];
            item.classList.add("is-error");
            if (intentos < 3) {
                if (statusBadge) {
                    statusBadge.className = "lab-q-status-badge is-wrong";
                    statusBadge.textContent = `❌ No coincide (Intento ${intentos}/3). Verificá tu cálculo.`;
                }
            } else {
                if (statusBadge) {
                    statusBadge.className = "lab-q-status-badge is-wrong";
                    statusBadge.textContent = "❌ Intento 3/3 alcanzado.";
                }
                if (attemptBox) attemptBox.classList.remove("hidden");
            }
        }

        if (laboratorioEstado.pistasReveladas && laboratorioEstado.pistasReveladas[idx]) {
            if (revealBox) {
                revealBox.classList.remove("hidden");
                setHTML(revealBox, `<strong>💡 Pista para el Inciso ${q.letra.toUpperCase()}:</strong><p style="margin: 0.35rem 0 0;">${q.pista || "Consultá las fórmulas en la Mesa de Trabajo."}</p>`);
            }
        }
        if (laboratorioEstado.solucionesReveladas && laboratorioEstado.solucionesReveladas[idx]) {
            if (revealBox) {
                revealBox.classList.remove("hidden");
                setHTML(revealBox, `<strong>📖 Respuesta Exacta (${q.esperado}) & Paso a Paso:</strong><p style="margin: 0.35rem 0 0;">${q.explicacion || `El valor teórico exacto es ${q.esperado}.`}</p>`);
            }
        }

        // Eventos interactivos y guardado en tiempo real
        if (inputField) {
            inputField.addEventListener("input", (e) => {
                if (!laboratorioEstado.respuestasUsuario) laboratorioEstado.respuestasUsuario = {};
                laboratorioEstado.respuestasUsuario[idx] = e.target.value;
                guardarLaboratorioStorage();
            });
            inputField.addEventListener("keydown", (e) => {
                if (e.key === "Enter") {
                    e.preventDefault();
                    verificarPreguntaInciso(idx);
                }
            });
        }

        if (verifyBtn) verifyBtn.addEventListener("click", () => verificarPreguntaInciso(idx));
        if (pistaBtn) pistaBtn.addEventListener("click", () => mostrarPistaInciso(idx));
        if (respBtn) respBtn.addEventListener("click", () => mostrarRespuestaInciso(idx));
    });
}

function actualizarProgresoPreguntasUI() {
    const ej = laboratorioEstado.ejercicioActual;
    if (!ej || !dom.labQuestionsProgress) return;
    const total = ej.preguntas.length;
    const resueltas = Object.keys(laboratorioEstado.resueltasPorPregunta).length;
    dom.labQuestionsProgress.textContent = `${resueltas} de ${total} resueltos`;
}

// ------------------------------------------
// VERIFICACIÓN Y FLUJO DE 3 INTENTOS
// ------------------------------------------

function verificarPreguntaInciso(idx) {
    const ej = laboratorioEstado.ejercicioActual;
    if (!ej || !ej.preguntas[idx]) return;
    const q = ej.preguntas[idx];

    const input = document.getElementById(`labQInput_${idx}`);
    const verifyBtn = document.getElementById(`labBtnVerify_${idx}`);
    const statusBadge = document.getElementById(`labQStatus_${idx}`);
    const attemptBox = document.getElementById(`lab3rdAttemptBox_${idx}`);
    const itemCard = document.getElementById(`labQuestionItem_${idx}`);

    if (!input) return;
    const val = parseFloat(input.value);

    if (isNaN(val)) {
        mostrarToast("⚠️ Por favor, ingresá un número para verificar el inciso.", "aviso");
        return;
    }

    const tol = q.tolerancia || 0.05;
    const esCorrecto = Math.abs(val - q.esperado) <= tol;

    if (esCorrecto) {
        // Marcado de éxito
        laboratorioEstado.resueltasPorPregunta[idx] = true;
        if (itemCard) {
            itemCard.classList.remove("is-error");
            itemCard.classList.add("is-correct");
        }
        if (statusBadge) {
            statusBadge.className = "lab-q-status-badge is-correct";
            statusBadge.textContent = "✅ ¡Correcto! (+25 XP)";
        }
        if (input) input.disabled = true;
        if (verifyBtn) verifyBtn.disabled = true;
        if (attemptBox) attemptBox.classList.add("hidden");

        laboratorioEstado.xpTotal += 25;
        if (dom.labXpDisplay) dom.labXpDisplay.textContent = `${laboratorioEstado.xpTotal} XP`;

        reproducirSonidoDuelo("fanfare");
        actualizarProgresoPreguntasUI();
        guardarLaboratorioStorage();

        // Chequear si se completó todo el ejercicio
        if (Object.keys(laboratorioEstado.resueltasPorPregunta).length >= ej.preguntas.length) {
            finalizarEjercicioLaboratorio();
        }
    } else {
        // Intento fallido
        const intentos = (laboratorioEstado.intentosPorPregunta[idx] || 0) + 1;
        laboratorioEstado.intentosPorPregunta[idx] = intentos;
        guardarLaboratorioStorage();

        reproducirSonidoDuelo("buzzer");

        if (itemCard) itemCard.classList.add("is-error");

        if (intentos < 3) {
            if (statusBadge) {
                statusBadge.className = "lab-q-status-badge is-wrong";
                statusBadge.textContent = `❌ No coincide (Intento ${intentos}/3). Verificá tu cálculo.`;
            }
        } else {
            // Tercer intento o superior: desplegar caja interactiva
            if (statusBadge) {
                statusBadge.className = "lab-q-status-badge is-wrong";
                statusBadge.textContent = "❌ Intento 3/3 alcanzado.";
            }
            if (attemptBox) {
                attemptBox.classList.remove("hidden");
            }
        }
    }
}

function mostrarPistaInciso(idx) {
    const ej = laboratorioEstado.ejercicioActual;
    if (!ej || !ej.preguntas[idx]) return;
    const q = ej.preguntas[idx];

    laboratorioEstado.pistasReveladas = laboratorioEstado.pistasReveladas || {};
    laboratorioEstado.pistasReveladas[idx] = true;

    const revealBox = document.getElementById(`labQRevealBox_${idx}`);
    if (revealBox) {
        revealBox.classList.remove("hidden");
        setHTML(revealBox, `<strong>💡 Pista para el Inciso ${q.letra.toUpperCase()}:</strong><p style="margin: 0.35rem 0 0;">${q.pista || "Consultá las fórmulas en la Mesa de Trabajo."}</p>`);
        mostrarToast("💡 Pista desbloqueada.", "info");
    }
    guardarLaboratorioStorage();
}

function mostrarRespuestaInciso(idx) {
    const ej = laboratorioEstado.ejercicioActual;
    if (!ej || !ej.preguntas[idx]) return;
    const q = ej.preguntas[idx];

    laboratorioEstado.solucionesReveladas = laboratorioEstado.solucionesReveladas || {};
    laboratorioEstado.solucionesReveladas[idx] = true;

    const revealBox = document.getElementById(`labQRevealBox_${idx}`);
    const input = document.getElementById(`labQInput_${idx}`);

    if (revealBox) {
        revealBox.classList.remove("hidden");
        setHTML(revealBox, `<strong>📖 Respuesta Exacta (${q.esperado}) & Paso a Paso:</strong><p style="margin: 0.35rem 0 0;">${q.explicacion || `El valor teórico exacto es ${q.esperado}.`}</p>`);
    }

    if (input) {
        input.value = q.esperado;
        if (!laboratorioEstado.respuestasUsuario) laboratorioEstado.respuestasUsuario = {};
        laboratorioEstado.respuestasUsuario[idx] = q.esperado;
    }
    guardarLaboratorioStorage();
    mostrarToast(`📖 Respuesta revelada para el Inciso ${q.letra.toUpperCase()}.`, "info");
}

function finalizarEjercicioLaboratorio() {
    if (dom.labCompletedCard) dom.labCompletedCard.classList.remove("hidden");
    laboratorioEstado.xpTotal += 50;
    if (dom.labXpDisplay) dom.labXpDisplay.textContent = `${laboratorioEstado.xpTotal} XP`;

    const matId = laboratorioEstado.materiaSeleccionada || "estadistica";
    const mat = CATALOGO_MATERIAS_LABORATORIO[matId];
    const nomMat = mat ? mat.nombre : "la materia";

    reproducirSonidoDuelo("fanfare");
    mostrarToast(`🎉 ¡Felicitaciones! Completaste todos los incisos del ejercicio de ${nomMat}.`, "exito");
    guardarLaboratorioStorage();
}

// ------------------------------------------
// CONFIGURACIÓN DE EVENT LISTENERS DEL LAB
// ------------------------------------------

function configurarEventosLaboratorio() {
    // Modal de Configuración
    if (dom.labBtnAbrirConfigModal) {
        dom.labBtnAbrirConfigModal.addEventListener("click", abrirModalConfigLab);
    }
    if (dom.closeLabConfigModalBtn) {
        dom.closeLabConfigModalBtn.addEventListener("click", cerrarModalConfigLab);
    }
    if (dom.closeLabConfigModalBottomBtn) {
        dom.closeLabConfigModalBottomBtn.addEventListener("click", cerrarModalConfigLab);
    }
    if (dom.labConfigModal) {
        dom.labConfigModal.addEventListener("click", (e) => {
            if (e.target === dom.labConfigModal) cerrarModalConfigLab();
        });
        dom.labConfigModal.addEventListener("cancel", (e) => {
            e.preventDefault();
            cerrarModalConfigLab();
        });
    }

    // Carga de archivo PDF con Drag & Drop y Click
    if (dom.labUploadDropzone && dom.labPdfFileInput) {
        dom.labUploadDropzone.addEventListener("click", (e) => {
            if (e.target.closest("#labBtnQuitarPdf")) return;
            dom.labPdfFileInput.click();
        });

        dom.labPdfFileInput.addEventListener("change", (e) => {
            const file = e.target.files?.[0];
            if (file) procesarPdfLaboratorio(file);
        });

        dom.labUploadDropzone.addEventListener("dragover", (e) => {
            e.preventDefault();
            dom.labUploadDropzone.classList.add("is-dragover");
        });
        dom.labUploadDropzone.addEventListener("dragleave", () => {
            dom.labUploadDropzone.classList.remove("is-dragover");
        });
        dom.labUploadDropzone.addEventListener("drop", (e) => {
            e.preventDefault();
            dom.labUploadDropzone.classList.remove("is-dragover");
            const file = e.dataTransfer.files?.[0];
            if (file) procesarPdfLaboratorio(file);
        });
    }

    if (dom.labBtnQuitarPdf) {
        dom.labBtnQuitarPdf.addEventListener("click", (e) => {
            e.stopPropagation();
            limpiarPdfLaboratorio();
        });
    }

    // Botones de selección rápida de subtemas
    if (dom.labBtnSelectAllSubtopics) {
        dom.labBtnSelectAllSubtopics.addEventListener("click", seleccionarTodosSubtemasLab);
    }
    if (dom.labBtnClearSubtopics) {
        dom.labBtnClearSubtopics.addEventListener("click", limpiarSubtemasLab);
    }

    // Botón para volver al selector de materias (Paso 1)
    if (dom.labBtnVolverMaterias) {
        dom.labBtnVolverMaterias.addEventListener("click", () => {
            mostrarPasoModalLab(1);
        });
    }

    // Botón "Cargar y Preparar Laboratorio" del modal
    if (dom.labBtnCargarConfig) {
        dom.labBtnCargarConfig.addEventListener("click", () => {
            if (dom.labConfigOrderInput) {
                laboratorioEstado.instruccionUsuario = dom.labConfigOrderInput.value.trim();
            }
            if (!laboratorioEstado.temasSeleccionados || laboratorioEstado.temasSeleccionados.length === 0) {
                const mat = CATALOGO_MATERIAS_LABORATORIO[laboratorioEstado.materiaSeleccionada] || CATALOGO_MATERIAS_LABORATORIO.contabilidad;
                laboratorioEstado.temasSeleccionados = mat.subtemas.filter(s => s.default).map(s => s.id);
            }
            actualizarBadgesMateriaLabUI();

            // Filtrar y activar pestañas específicas de la disciplina seleccionada
            filtrarTabsPorMateria(laboratorioEstado.materiaSeleccionada);

            cerrarModalConfigLab();
            // Si ya hay un ejercicio guardado para esta materia y el alumno no escribió una orden nueva, reanudar
            if (laboratorioEstado.ejercicioActual && !laboratorioEstado.instruccionUsuario) {
                renderizarEjercicioActual(false);
            } else {
                generarEjercicioLaboratorio(true, laboratorioEstado.instruccionUsuario);
            }
        });
    }

    // Botón "Personalizar con IA" (Abre modal de orden / personalización)
    if (dom.labBtnGenerarConIA) {
        dom.labBtnGenerarConIA.addEventListener("click", () => {
            abrirModalPromptLab();
        });
    }

    // Botones directos "Otro Ejercicio con IA" (Generación inmediata sin repetir)
    if (dom.labBtnOtroEjercicioIA) {
        dom.labBtnOtroEjercicioIA.addEventListener("click", () => {
            generarOtroEjercicioIALab(dom.labBtnOtroEjercicioIA);
        });
    }
    if (dom.labBtnQuickOtroIA) {
        dom.labBtnQuickOtroIA.addEventListener("click", () => {
            generarOtroEjercicioIALab(dom.labBtnQuickOtroIA);
        });
    }
    if (dom.labBtnSiguienteCasoModal) {
        dom.labBtnSiguienteCasoModal.addEventListener("click", () => {
            generarOtroEjercicioIALab(dom.labBtnSiguienteCasoModal);
        });
    }

    // Modal de Orden & Prompt para Ejercicios
    if (dom.closeLabPromptModalBtn) {
        dom.closeLabPromptModalBtn.addEventListener("click", cerrarModalPromptLab);
    }
    if (dom.closeLabPromptModalBottomBtn) {
        dom.closeLabPromptModalBottomBtn.addEventListener("click", cerrarModalPromptLab);
    }
    if (dom.labPromptModalChangeConfigBtn) {
        dom.labPromptModalChangeConfigBtn.addEventListener("click", () => {
            cerrarModalPromptLab();
            abrirModalConfigLab();
        });
    }
    if (dom.labBtnEjecutarGeneracion) {
        dom.labBtnEjecutarGeneracion.addEventListener("click", () => {
            const orden = dom.labPromptOrderInput ? dom.labPromptOrderInput.value.trim() : "";
            laboratorioEstado.instruccionUsuario = orden;
            cerrarModalPromptLab();
            generarEjercicioLaboratorio(true, orden);
        });
    }
    if (dom.labBtnGenerarSorpresa) {
        dom.labBtnGenerarSorpresa.addEventListener("click", () => {
            cerrarModalPromptLab();
            generarEjercicioLaboratorio(true, "");
        });
    }
    if (dom.labPromptOrderInput) {
        dom.labPromptOrderInput.addEventListener("keydown", (e) => {
            if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                if (dom.labBtnEjecutarGeneracion) dom.labBtnEjecutarGeneracion.click();
            }
        });
    }

    if (dom.labBtnSiguienteCasoModal) {
        dom.labBtnSiguienteCasoModal.addEventListener("click", () => generarEjercicioLaboratorio(true, laboratorioEstado.instruccionUsuario));
    }

    // Copiar estadísticas a portapapeles desde el panel de 7 métricas
    if (dom.labWidgetFreq) {
        dom.labWidgetFreq.querySelectorAll(".lab-copy-stat-btn").forEach(btn => {
            btn.addEventListener("click", () => {
                const targetId = btn.getAttribute("data-target");
                const elem = document.getElementById(targetId);
                if (elem) {
                    const val = elem.textContent.replace("%", "").trim();
                    if (val && val !== "-") {
                        navigator.clipboard.writeText(val).then(() => {
                            mostrarToast(`📋 Copiado al portapapeles: ${val}`, "info");
                        }).catch(() => {
                            mostrarToast(`Valor: ${val}`, "info");
                        });
                    }
                }
            });
        });
    }

    // Conmutador Móvil de Vistas (Enunciado / Herramientas)
    if (dom.labMobileBtnEnunciado) {
        dom.labMobileBtnEnunciado.addEventListener("click", () => cambiarVistaMovilLab("enunciado"));
    }
    if (dom.labMobileBtnHerramientas) {
        dom.labMobileBtnHerramientas.addEventListener("click", () => cambiarVistaMovilLab("herramientas"));
    }
    if (dom.labMobileFloatToggleBtn) {
        dom.labMobileFloatToggleBtn.addEventListener("click", () => {
            const actual = dom.laboratorioSplit?.getAttribute("data-mobile-view") || "enunciado";
            cambiarVistaMovilLab(actual === "enunciado" ? "herramientas" : "enunciado");
        });
    }

    // Pestañas de Herramientas
    const tabBtns = [
        { btn: dom.labTabBtnFreq, id: "freq" },
        { btn: dom.labTabBtnProb, id: "prob" },
        { btn: dom.labTabBtnBayes, id: "bayes" },
        { btn: dom.labTabBtnScratch, id: "scratch" },
        { btn: dom.labTabBtnContabilidad, id: "contabilidad" },
        { btn: dom.labTabBtnQuimica, id: "quimica" },
        { btn: dom.labTabBtnFisica, id: "fisica" },
        { btn: dom.labTabBtnMatematicas, id: "matematicas" },
        { btn: dom.labTabBtnCalculo, id: "calculo" },
        { btn: dom.labTabBtnMatrices, id: "matrices" },
        { btn: dom.labTabBtnComputacion, id: "computacion" },
        { btn: dom.labTabBtnBiologia, id: "biologia" },
        { btn: dom.labTabBtnFinanciera, id: "financiera" },
        { btn: dom.labTabBtnMedicina, id: "medicina" }
    ];

    tabBtns.forEach(({ btn, id }) => {
        if (!btn) return;
        btn.addEventListener("click", () => activarTabLaboratorio(id));
    });

    if (typeof inicializarModuloMatricesYLogica === "function") {
        inicializarModuloMatricesYLogica();
    }

    // Exponer funciones globales requeridas por atributos onclick inline en tablas dinámicas
    window.eliminarAsientoContable = eliminarAsientoContable;
    window.actualizarCeldaDiario = actualizarCeldaDiario;
    window.eliminarFilaDeAsiento = eliminarFilaDeAsiento;
    window.agregarFilaAAsiento = agregarFilaAAsiento;

    // Grilla de Frecuencias
    if (dom.labBtnAddRow) dom.labBtnAddRow.addEventListener("click", agregarFilaGrilla);
    if (dom.labBtnRemoveRow) dom.labBtnRemoveRow.addEventListener("click", () => quitarFilaGrilla(laboratorioEstado.tablaDatos.length - 1));
    if (dom.labBtnAddCol) {
        dom.labBtnAddCol.addEventListener("click", () => {
            const tipo = dom.labSelectColType?.value || "xifi";
            agregarColumnaGrilla(tipo);
        });
    }
    if (dom.labBtnRemoveCol) {
        dom.labBtnRemoveCol.addEventListener("click", quitarColumnaGrilla);
    }
    if (dom.labBtnClearTable) dom.labBtnClearTable.addEventListener("click", limpiarGrillaFrecuencias);

    // Calculadora Normal inputs ("change" asegura que el <select> de cola actualice en todos los navegadores)
    [dom.labNormMean, dom.labNormStd, dom.labNormX, dom.labNormTail].forEach(elem => {
        if (!elem) return;
        elem.addEventListener("input", actualizarCalculosNormalUI);
        elem.addEventListener("change", actualizarCalculosNormalUI);
    });

    // Botón "📥 Copiar P a Checkpoint": pega la probabilidad calculada en el primer inciso sin resolver
    if (dom.labBtnCopyNormToInput) {
        dom.labBtnCopyNormToInput.addEventListener("click", () => {
            const pTexto = (dom.labNormPVal?.textContent || "").trim();
            const pValor = parseFloat(pTexto);
            if (!isFinite(pValor)) {
                mostrarToast("⚠️ No hay una probabilidad calculada para copiar.");
                return;
            }
            const inputs = [...document.querySelectorAll("#labQuestionsList .lab-q-input")];
            const destino = inputs.find(inp => !inp.disabled && !inp.readOnly && inp.value.trim() === "")
                || inputs.find(inp => !inp.disabled && !inp.readOnly);
            if (!destino) {
                navigator.clipboard?.writeText(String(pValor)).catch(() => {});
                mostrarToast(`📋 No hay incisos abiertos. P = ${pValor} copiado al portapapeles.`);
                return;
            }
            destino.value = String(pValor);
            destino.dispatchEvent(new Event("input", { bubbles: true }));
            destino.focus();
            destino.scrollIntoView({ behavior: "smooth", block: "center" });
            cambiarVistaMovilLab("enunciado");
            mostrarToast(`📥 P = ${pValor} pegado en el inciso. Revisalo y verificá tu respuesta.`);
        });
    }

    // Subtabs Calculadora Probabilidades
    if (dom.labWidgetProb) {
        dom.labWidgetProb.querySelectorAll(".lab-subtab-btn").forEach(btn => {
            btn.addEventListener("click", () => {
                const target = btn.getAttribute("data-subtab");
                dom.labWidgetProb.querySelectorAll(".lab-subtab-btn").forEach(b => b.classList.remove("is-active"));
                btn.classList.add("is-active");

                const subpanels = {
                    normal: document.getElementById("labSubpanelNormal"),
                    binomial: document.getElementById("labSubpanelBinomial"),
                    poisson: document.getElementById("labSubpanelPoisson"),
                    calc: document.getElementById("labSubpanelCalc")
                };

                Object.entries(subpanels).forEach(([k, p]) => {
                    if (p) p.classList.toggle("hidden", k !== target);
                });

                if (target === "normal") actualizarCalculosNormalUI();
            });
        });
    }

    // Binomial inputs
    [dom.labBinoN, dom.labBinoP, dom.labBinoK].forEach(elem => {
        if (elem) elem.addEventListener("input", actualizarCalculosBinomialUI);
    });

    // Poisson inputs
    [dom.labPoisLambda, dom.labPoisK].forEach(elem => {
        if (elem) elem.addEventListener("input", actualizarCalculosPoissonUI);
    });

    // Bayes inputs
    [dom.labBayesCellAB, dom.labBayesCellANotB, dom.labBayesCellNotAB, dom.labBayesCellNotANotB].forEach(elem => {
        if (elem) elem.addEventListener("input", recalcularMatrizBayes);
    });

    [dom.labBayesEvAName, dom.labBayesEvNotAName, dom.labBayesEvBName, dom.labBayesEvNotBName].forEach(elem => {
        if (elem) elem.addEventListener("input", recalcularMatrizBayes);
    });
}

